/**
 * pension.js — 勞工退休金（新制 / 舊制）
 *
 * ## 法源（已於 https://law.moj.gov.tw 全國法規資料庫驗證）
 * - 勞退條例§14                   雇主應為勞工負擔提繳之退休金，不得低於勞工每月工資 6%；
 *                                 勞工得於每月工資 6% 範圍內，自願另行提繳退休金，不計入薪資所得課稅
 * - 勞退條例§24、§24-2             一次領 / 月退、平均餘命月數
 * - 勞基法§55、§54                 舊制
 *
 * ## 月提繳工資分級表
 * 由 `brackets.js` 之 `PENSION_BRACKETS_2026`（62 級）統一供應；查表函式 `getPensionBracket`。
 * 本檔之 `calcLaborPension` 透過該表將實領月薪轉為提繳工資。
 */

import { createTrace, addStep, addLaw, setSummary } from './trace.js';
import { getPensionBracket, PENSION_BRACKETS_2026 } from './brackets.js';

/**
 * 勞退／勞保老年給付「平均餘命月數」逐歲表
 *
 * 法源：勞動部勞工保險局 113/4/1 公告「月退休金之平均餘命」
 *       依內政部 111 年全國簡易生命表（全體，單一年齡組）換算
 *       月退採計之平均餘命 = 原生命表平均餘命四捨五入至整數年
 *       月數 = 整數年 × 12
 *
 *   公告頁：https://www.bli.gov.tw/0108333.html
 *   PDF：  https://www.bli.gov.tw/files/16482
 *
 * 官方表涵蓋 60-85+（勞退§24 月退最低起領 60 歲）。age < 60 的呼叫以
 * 60 歲（最慷慨值）回應；age >= 85 以 85+ 列回應。
 *
 * 版本化：未來 BLI 更新以新 key 進 LIFE_MONTHS_VERSIONS，舊版永不刪。
 *
 * 本模組為**所有頁面的平均餘命月數單一真實來源**，禁止頁面內硬編。
 */
export const LIFE_MONTHS_VERSIONS = {
  '113-04-01': {
    effective: '113-04-01',
    lawSource: '勞動部勞工保險局 月退休金之平均餘命',
    underlyingTable: '內政部 111 年全國簡易生命表（全體，單一年齡組）',
    announcementUrl: 'https://www.bli.gov.tw/0108333.html',
    sourceUrl: 'https://www.bli.gov.tw/files/16482',
    minAge: 60,
    maxAgeTerminal: 85, // 85+ 同列
    // age → 月退採計整數年
    years: {
      60: 23, 61: 23, 62: 22, 63: 21, 64: 20,
      65: 19, 66: 19, 67: 18, 68: 17, 69: 16,
      70: 16, 71: 15, 72: 14, 73: 13, 74: 13,
      75: 12, 76: 11, 77: 11, 78: 10, 79: 9,
      80: 9,  81: 8,  82: 8,  83: 7,  84: 6,
      85: 6, // 85+
    },
  },
};

export const LIFE_MONTHS_CURRENT_VERSION = '113-04-01';

/**
 * 取得平均餘命月數（月退採計）
 * @param {number} age 申請月退休金時之年齡（整歲）
 * @param {{ version?: string }} [opts] version 預設為現行版本
 * @returns {number} 月數（整數年 × 12）
 */
export function getLifeMonths(age, opts = {}) {
  if (!Number.isFinite(age) || age < 0) throw new TypeError('age 必須為非負有限數');
  const version = opts.version || LIFE_MONTHS_CURRENT_VERSION;
  const table = LIFE_MONTHS_VERSIONS[version];
  if (!table) throw new Error(`Unknown lifeMonths version: ${version}`);

  const a = Math.floor(age);
  const key = a < table.minAge
    ? table.minAge
    : a >= table.maxAgeTerminal
    ? table.maxAgeTerminal
    : a;
  return table.years[key] * 12;
}

/**
 * 勞退新制（勞退條例§24、§24-2）一次領 / 月退
 * - 年資滿 15 年可選月退或一次領；未滿 15 年僅能一次領
 * - 月退 = 個人專戶累積本金與收益 ÷ 平均餘命月數
 * @returns {{ lumpSum: number, monthlyPension: number, lifeMonths: number, canMonthly: boolean }}
 */
export function calcPensionNew(accountTotal, age, seniorityYears) {
  if (!Number.isFinite(accountTotal) || accountTotal < 0) throw new TypeError('accountTotal 必須為非負有限數');
  if (!Number.isFinite(seniorityYears) || seniorityYears < 0) throw new TypeError('seniorityYears 必須為非負有限數');
  const lifeMonths = getLifeMonths(age);
  return {
    lumpSum: accountTotal,
    monthlyPension: accountTotal / lifeMonths,
    lifeMonths,
    canMonthly: seniorityYears >= 15,
  };
}

/**
 * 勞退舊制（勞基法§55）基數計算
 * - 前 15 年每滿 1 年 2 個基數
 * - 第 16 年起每滿 1 年 1 個基數
 * - 合計上限 45 個基數
 * - **強制退休且心神喪失或身體殘廢**（§54-I-1）→ 加給基數 20%
 *
 * @param {number} totalYears
 * @param {number} avgWage
 * @param {boolean} [isDisabledRetirement=false] 是否屬「強制退休且心神喪失/身體殘廢」
 *   （§54-I-1）。**不限職災造成**：非職災心神喪失亦適用。原參數名 `isWorkDisability`
 *   誤導為僅限職災，2026-05-24 P2-5 更名為 `isDisabledRetirement`。
 * @returns {{ first15: number, after15: number, baseUnits: number, disabilityUnits: number, totalUnits: number, totalPay: number, capped: boolean }}
 */
export function calcPensionOld(totalYears, avgWage, isDisabledRetirement = false) {
  if (!Number.isFinite(totalYears) || totalYears < 0) throw new TypeError('totalYears 必須為非負有限數');
  if (!Number.isFinite(avgWage) || avgWage < 0) throw new TypeError('avgWage 必須為非負有限數');
  const first15 = Math.min(totalYears, 15) * 2;
  const after15 = Math.max(totalYears - 15, 0) * 1;
  const baseUnitsRaw = first15 + after15;
  const baseUnits = Math.min(baseUnitsRaw, 45);
  const capped = baseUnitsRaw > 45;
  const disabilityUnits = isDisabledRetirement ? baseUnits * 0.2 : 0;
  const totalUnits = baseUnits + disabilityUnits;
  return {
    first15,
    after15,
    baseUnits,
    disabilityUnits,
    totalUnits,
    totalPay: totalUnits * avgWage,
    capped,
  };
}

// ─── HR-UX-3：calcLaborPension（新制月提繳，traced） ─────────────────

/** 雇主提繳法定下限（勞退條例§14 I：6%） */
export const PENSION_EMPLOYER_RATE_FLOOR = 0.06;
/** 勞工自願提繳上限（勞退條例§14 III：6%） */
export const PENSION_EMPLOYEE_RATE_CAP = 0.06;

/**
 * 勞退新制單月提繳金額試算（雇主 6%、勞工自願 0-6%；含 trace）
 *
 * @param {Object} params
 * @param {number} params.monthlySalary               實際月薪（NTD）
 * @param {number} [params.employerRate=6]            雇主提繳率（百分比，下限 6）
 * @param {number} [params.employeeRate=0]            勞工自願提繳率（百分比，上限 6）
 * @param {number} [params.years]                     年資（年）— 僅在進一步試算「累積本金」時使用，
 *                                                    本函式以單月為主；years 給時加一行年化試算（年×12）
 * @returns {import('./trace.js').TracedResult}
 *           result = 雇主＋勞工合計單月提繳金額（NTD）
 */
export function calcLaborPension(params) {
  const {
    monthlySalary,
    employerRate = 6,
    employeeRate = 0,
    years,
  } = params;

  if (typeof monthlySalary !== 'number' || monthlySalary <= 0) {
    throw new Error(`calcLaborPension: invalid monthlySalary=${monthlySalary}`);
  }
  // 勞退條例§14：雇主率不得低於 6%，勞工自願不得高於 6%（兩端守門，超出視為違法不受理）
  const employerPct = Math.max(employerRate, 6) / 100;
  const employeePct = Math.min(Math.max(employeeRate, 0), 6) / 100;

  const trace = createTrace();
  addLaw(trace, {
    article: '勞退條例§14',
    description: '雇主提繳不得低於勞工每月工資 6%；勞工得於 6% 範圍內自願提繳，不計入薪資所得課稅',
  });

  addStep(trace, {
    label: '輸入月薪',
    formula: 'monthlySalary',
    inputs: { monthlySalary },
    value: monthlySalary,
    note: '勞工實際月薪（含本俸 + 經常性給與）',
  });

  // 走 62 級分級表（§14 末段授權）
  const bracket = getPensionBracket(monthlySalary);
  addLaw(trace, {
    article: '勞動部 114-11-24 勞動福 3 字第 1140153598 號令',
    description: '勞工退休金月提繳工資分級表 2026 版（62 級，自 115/01/01 施行；下限 1,500、上限 150,000）',
  });
  addStep(trace, {
    label: '查 62 級提繳工資',
    formula: 'getPensionBracket(monthlySalary)',
    inputs: { monthlySalary },
    value: bracket,
    note: `對照分級表第 ${PENSION_BRACKETS_2026.indexOf(bracket) + 1} 級`,
  });

  const employerAmt = bracket * employerPct;
  addStep(trace, {
    label: '雇主提繳',
    formula: `bracket × ${employerPct.toFixed(4)}`,
    inputs: { bracket, rate: employerPct },
    value: employerAmt,
    note: '勞退條例§14 I 法定下限 6%',
  });

  let employeeAmt = 0;
  if (employeePct > 0) {
    employeeAmt = bracket * employeePct;
    addStep(trace, {
      label: '勞工自願提繳',
      formula: `bracket × ${employeePct.toFixed(4)}`,
      inputs: { bracket, rate: employeePct },
      value: employeeAmt,
      note: '勞退條例§14 III：自願提繳，不計入薪資所得課稅',
    });
  }

  const monthly = employerAmt + employeeAmt;
  addStep(trace, {
    label: '單月合計',
    formula: 'employer + employee',
    value: monthly,
  });

  let yearly;
  let lifetime;
  if (typeof years === 'number' && years > 0) {
    yearly = monthly * 12;
    lifetime = yearly * years;
    addStep(trace, {
      label: '年提繳合計',
      formula: 'monthly × 12',
      inputs: { monthly },
      value: yearly,
    });
    addStep(trace, {
      label: `${years} 年累積本金（不含投資收益）`,
      formula: 'yearly × years',
      inputs: { yearly, years },
      value: lifetime,
      note: '僅本金；實際個人專戶含勞退基金每年保證收益（不低於二年期定存）— 不在此函式估算',
    });
  }

  setSummary(
    trace,
    `月提繳 ${Math.round(monthly).toLocaleString()} 元（雇主 ${Math.round(employerAmt).toLocaleString()} + 勞工 ${Math.round(employeeAmt).toLocaleString()}）` +
      (lifetime ? ` · ${years} 年累積本金 ${Math.round(lifetime).toLocaleString()} 元` : ''),
  );

  return { result: monthly, trace };
}

