/**
 * overtime-detail.js — 加班費逐筆明細聚合（多筆 entry → 月總額 + 分類拆分）
 *
 * 抽 apps/etp/public/hr-tools/overtime-detail.html 的 calcOvertimePay +
 * recalcAll 進 core-labor。
 *
 * 單筆加班費沿用既有 overtime-calculator.js 的 calcOvertimePay（§24 倍率
 * 已驗證 + traced），本檔負責：
 *
 *   1. 多筆 entries 聚合（按 type 分桶 + 總額 + 總時數）
 *   2. 例假日（§36/§40）出勤 illegal flag
 *   3. §32 II 月加班 > 46 hr（無協議）/ > 54 hr（有協議）warning
 *   4. 每筆 entry 保留 date / type / hours / pay 供寫回 payroll_records
 *
 * ## 法源（每條已於 https://law.moj.gov.tw 全國法規資料庫驗證）
 *
 * - 勞基法§24 I（平日延長工時加成）
 *     一、延長工作時間在二小時以內者，按平日每小時工資額加給三分之一以上。
 *     二、再延長工作時間在二小時以內者，按平日每小時工資額加給三分之二以上。
 *     三、依§32 IV 之規定，雇主使勞工延長工作時間者，按平日每小時工資額加倍發給。
 *
 * - 勞基法§24 II（休息日加成）
 *     雇主使勞工於休息日工作，工作時間在二小時以內者，每小時工資加給一又三分之一；
 *     工作二小時後再繼續工作者，按平日每小時工資加給一又三分之二以上。
 *     ※ 107 修法後核實計算，不再以 4/8/12 分級。
 *
 * - 勞基法§39（國定假日 / 特別休假出勤加倍）
 *     第三十六條所定之例假、休息日、第三十七條所定之休假⋯⋯工資應由雇主照給。
 *     雇主經徵得勞工同意於休假日工作者，工資應加倍發給。
 *
 * - 勞基法§40（例假日出勤限制）
 *     因天災、事變或突發事件，雇主認有繼續工作之必要時，得停止第三十六條至第
 *     三十八條所定勞工之假期。但停止假期之工資，應加倍發給，並應於事後補假
 *     休息。前項停止勞工假期，事業單位應於事後 24 小時內，詳述理由，報請當地
 *     主管機關核備。
 *     ※ 非屬§40 列舉事由而使勞工於例假日出勤 → 違法（標 illegal）
 *
 * - 勞基法§32 II（月加班時數上限，見 work-hours-compliance.js）
 *
 * @module overtime-detail
 */

import { createTrace, addStep, addLaw, setSummary } from './trace.js';
import { calcOvertimePay, monthlyToHourly } from './overtime-calculator.js';
import {
  MONTHLY_OT_LIMIT_NO_AGREEMENT,
  MONTHLY_OT_LIMIT_WITH_AGREEMENT,
} from './work-hours-compliance.js';

/** hr-tools 用的 4 種 type → core-labor overtime-calculator 的 shiftKind 對應 */
export const OVERTIME_TYPE_MAP = Object.freeze({
  weekday: 'weekday',
  restday: 'restday',
  holiday: 'statutory_holiday', // §39 國定假日
  mandatory: 'mandatory_leave', // §36/§40 例假日（出勤通常違法）
});

/** 對應顯示用標籤 */
export const OVERTIME_TYPE_LABELS = Object.freeze({
  weekday: '平日',
  restday: '休息日',
  holiday: '國定假日',
  mandatory: '例假日',
});

function emptyBucket() {
  return { hours: 0, pay: 0, count: 0 };
}

/**
 * 聚合多筆加班記錄
 *
 * @param {object} params
 * @param {Array<{ date: string, type: 'weekday'|'restday'|'holiday'|'mandatory', hours: number }>} params.entries
 * @param {number} params.monthlySalary 月薪（用來推時薪）
 * @param {boolean} [params.hasOvertimeAgreement=false] 依§32 II，是否經工會 / 勞資會議同意
 * @param {boolean} [params.emergency=false] 依§40，天災事變突發事件（mandatory 出勤合法化）
 * @returns {{
 *   perEntry: Array<{ date, type, hours, pay, label, illegal, formula, segments }>,
 *   totals: { hours, pay, count },
 *   byType: { weekday, restday, holiday, mandatory },
 *   hourlyWage: number,
 *   monthlyLimit: { value, exceedsBy, level, note, otBilling },
 *   illegalEntries: array,
 *   trace
 * }}
 */
export function aggregateOvertimeEntries({
  entries,
  monthlySalary,
  hasOvertimeAgreement = false,
  emergency = false,
}) {
  if (!Array.isArray(entries)) {
    throw new Error('aggregateOvertimeEntries: entries 必須為陣列');
  }
  if (!Number.isFinite(monthlySalary) || monthlySalary <= 0) {
    throw new Error('aggregateOvertimeEntries: monthlySalary 必須為 > 0');
  }

  const hourlyWage = monthlyToHourly(monthlySalary);

  const byType = {
    weekday: emptyBucket(),
    restday: emptyBucket(),
    holiday: emptyBucket(),
    mandatory: emptyBucket(),
  };
  const perEntry = [];
  let totalHours = 0;
  let totalPay = 0;
  const illegalEntries = [];

  for (const e of entries) {
    if (e == null || typeof e !== 'object') continue;
    const type = e.type in OVERTIME_TYPE_MAP ? e.type : 'weekday';
    const hours = Number(e.hours);
    if (!Number.isFinite(hours) || hours <= 0) continue;

    const shiftKind = OVERTIME_TYPE_MAP[type];
    const result = calcOvertimePay({
      shiftKind,
      overtimeHours: hours,
      hourlyWage,
      // 例假日出勤合法化需§40 emergency；其他類型 emergency 旗標目前不影響倍率
      emergency: type === 'mandatory' ? emergency : false,
    });

    const illegal = type === 'mandatory' && !emergency;
    const entryRecord = {
      date: e.date ?? null,
      type,
      label: OVERTIME_TYPE_LABELS[type],
      hours,
      pay: result.totalAmount,
      formula: result.formula,
      segments: result.segments,
      illegal,
    };

    perEntry.push(entryRecord);
    byType[type].hours += hours;
    byType[type].pay += result.totalAmount;
    byType[type].count += 1;
    totalHours += hours;
    totalPay += result.totalAmount;
    if (illegal) illegalEntries.push(entryRecord);
  }

  // §32 II 月加班上限。例假日 + 國定假日屬假日工資不計入延長工時，僅以 weekday + restday 比對。
  const limit = hasOvertimeAgreement
    ? MONTHLY_OT_LIMIT_WITH_AGREEMENT
    : MONTHLY_OT_LIMIT_NO_AGREEMENT;
  const otBilling = byType.weekday.hours + byType.restday.hours;
  let level = 'pass';
  let exceedsBy = 0;
  let note = '';
  if (otBilling > limit) {
    level = 'fail';
    exceedsBy = otBilling - limit;
    note = `合計 ${otBilling} 小時，超過§32 II 上限 ${limit} 小時 ${exceedsBy} hr。`;
  } else if (hasOvertimeAgreement && otBilling > MONTHLY_OT_LIMIT_NO_AGREEMENT) {
    level = 'warn';
    note = `合計 ${otBilling} 小時，落在勞資協議延長 46-54 區間；3 個月仍需 ≤ 138。`;
  } else {
    level = 'pass';
    note = `平日 + 休息日合計 ${otBilling} 小時，未逾§32 II 上限 ${limit} 小時。`;
  }

  const trace = createTrace();
  addStep(trace, {
    label: '時薪換算',
    formula: 'monthlySalary / 30 / 8',
    inputs: { monthlySalary },
    value: Number(hourlyWage.toFixed(2)),
    note: '勞基法施行細則 + 行政函釋：以平日每小時工資為基礎',
  });
  addStep(trace, {
    label: '逐筆加總',
    formula: 'sum(perEntry.pay)',
    inputs: {
      entries: perEntry.length,
      weekdayH: byType.weekday.hours,
      restdayH: byType.restday.hours,
      holidayH: byType.holiday.hours,
      mandatoryH: byType.mandatory.hours,
    },
    value: Math.round(totalPay),
  });
  addStep(trace, {
    label: '§32 II 月加班上限檢查',
    formula: 'weekdayH + restdayH ≤ (hasAgreement ? 54 : 46) ?',
    inputs: { otBilling, limit, hasAgreement: hasOvertimeAgreement },
    value: exceedsBy,
    note,
  });
  addLaw(trace, {
    article: '勞基法§24 I',
    description: '平日延長工時前 2 小時 × 4/3、第 3-4 小時 × 5/3；天災事變 × 2。',
  });
  addLaw(trace, {
    article: '勞基法§24 II',
    description:
      '休息日工作前 2 小時 × 4/3、第 3 小時起 × 5/3（107 年修法後核實計算）。',
  });
  addLaw(trace, {
    article: '勞基法§39',
    description: '國定假日 / 特別休假經勞工同意出勤，工資加倍發給。',
  });
  if (illegalEntries.length > 0) {
    addLaw(trace, {
      article: '勞基法§40',
      description:
        '例假日出勤限於天災 / 事變 / 突發事件，且應事後 24 小時內報主管機關核備；違者依§79 處罰。',
    });
  }
  addLaw(trace, {
    article: '勞基法§32 II',
    description:
      '延長工時月 ≤ 46，經工會 / 勞資會議同意可至 54，每 3 個月 ≤ 138。',
  });
  setSummary(
    trace,
    `本月加班 ${perEntry.length} 筆共 ${totalHours} 小時，加班費 NT$ ${Math.round(totalPay).toLocaleString()}（${level}${illegalEntries.length > 0 ? ` · 例假日違法 ${illegalEntries.length} 筆` : ''}）。`,
  );

  return {
    perEntry,
    totals: {
      hours: totalHours,
      pay: Math.round(totalPay),
      count: perEntry.length,
    },
    byType: {
      weekday: { ...byType.weekday, pay: Math.round(byType.weekday.pay) },
      restday: { ...byType.restday, pay: Math.round(byType.restday.pay) },
      holiday: { ...byType.holiday, pay: Math.round(byType.holiday.pay) },
      mandatory: { ...byType.mandatory, pay: Math.round(byType.mandatory.pay) },
    },
    hourlyWage: Number(hourlyWage.toFixed(2)),
    monthlyLimit: { value: limit, exceedsBy, level, note, otBilling },
    illegalEntries,
    trace,
  };
}
