/**
 * non-compete.js — 勞基法§9-1 離職後競業禁止合法性分析（traced）
 *
 * ## 法源（已於 https://law.moj.gov.tw 全國法規資料庫驗證）
 *
 * - 勞基法§9-1 第 1 項（4 款要件）
 *     未符合下列規定者，雇主不得與勞工為離職後競業禁止之約定：
 *     一、雇主有應受保護之正當營業利益。
 *     二、勞工擔任之職位或職務，能接觸或使用雇主之營業秘密。
 *     三、競業禁止之期間、區域、職業活動之範圍及就業對象，未逾合理範疇。
 *     四、雇主對勞工因不從事競業行為所受損失有合理補償。
 * - 勞基法§9-1 第 2 項：前項第四款所定合理補償，不包括勞工於工作期間所受領之給付。
 * - 勞基法§9-1 第 3 項：違反第一項各款規定之一者，其約定無效。
 * - 勞基法§9-1 第 4 項：離職後競業禁止之期間，最長不得逾二年；逾二年者，縮短為二年。
 *
 * - 勞基法施行細則§7-1：離職後競業禁止之約定，應以書面為之。
 * - 勞基法施行細則§7-2：第 1 項第 3 款所定合理範疇——
 *     一、競業禁止之期間，不得逾雇主欲保護之營業秘密或技術資訊之生命週期，且最長不得逾二年。
 *     二、競業禁止之區域，應以原雇主實際營業活動之範圍為限。
 *     三、競業禁止之職業活動範圍，應具體明確，且與勞工原職業活動範圍相同或類似。
 *     四、競業禁止之就業對象，應具體明確，並以與原雇主有競爭關係者為限。
 * - 勞基法施行細則§7-3：雇主對勞工因不從事競業行為所受損失之合理補償，
 *     應就下列事項綜合考量：
 *     一、每月補償金額不低於勞工離職時一個月平均工資百分之五十。
 *     二、補償金額足以維持勞工離職後競業禁止期間之生活所需。
 *     三、補償金額與勞工遵守競業禁止之期間、區域、職業活動範圍及就業對象之範疇所受損失相當。
 *     四、其他與判斷補償基準合理性有關之事項。
 *     前項合理補償，應約定離職後一次預為給付或按月給付。
 *
 * ## 用途
 * 給 HR / 勞工自我檢核離職後競業禁止協議是否符合§9-1 全部要件。
 * 任一要件不通過 → 依§9-1 III 全部無效；期間超過 2 年 → 依§9-1 IV 縮短。
 *
 * @module non-compete
 */

import { createTrace, addStep, addLaw, setSummary } from './trace.js';

/** §9-1 4 款要件（細則§7-2、§7-3 拆解後常以 5 點呈現，本檔以條文 4 款為主，第 3 款內含 期間 + 範圍 兩子項） */
export const NON_COMPETE_REQUIREMENTS = Object.freeze({
  LEGIT_INTEREST: '§9-1 I 1：雇主有應受保護之正當營業利益',
  SECRET_ACCESS: '§9-1 I 2：勞工職務能接觸或使用營業秘密',
  PERIOD_REASONABLE: '§9-1 I 3（前段）：期間合理（≤ 2 年）',
  SCOPE_REASONABLE: '§9-1 I 3（後段）：區域 / 職業活動 / 就業對象範圍合理',
  COMPENSATION_ADEQUATE: '§9-1 I 4：合理補償（細則§7-3：月薪 ≥ 50%）',
});

const PERIOD_CAP_MONTHS = 24;
const COMPENSATION_FLOOR_RATIO = 0.5;

/**
 * 分析離職後競業禁止協議合法性
 *
 * @param {Object} params
 * @param {boolean} params.hasLegitInterest          雇主是否有應受保護之正當營業利益
 * @param {boolean} params.hasSecretAccess           勞工職務是否能接觸或使用雇主營業秘密
 * @param {number}  params.periodMonths              競業禁止期間（月）
 * @param {boolean} params.scopeReasonable           區域 / 職業活動 / 就業對象範圍是否合理且有限縮
 * @param {number}  params.monthlySalary             勞工離職時 1 個月平均工資（NTD）
 * @param {number}  params.monthlyCompensation       每月補償金額（NTD）
 * @returns {{
 *   result: {
 *     passCount: number,                    // 0-5 要件通過數（細項展開）
 *     verdict: 'green'|'yellow'|'red',      // 整體合法性燈號
 *     checks: Array<{ key: string, status: 'pass'|'fail'|'warn', detail: string }>,
 *     compensationGap: { monthlyGap: number, totalGap: number, minRequired: number, ratio: number },
 *     effectivePeriodMonths: number,        // 法院縮減後可主張之有效期間
 *   },
 *   trace: import('./trace.js').CalcTrace
 * }}
 */
export function analyzeNonCompete(params) {
  const {
    hasLegitInterest,
    hasSecretAccess,
    periodMonths,
    scopeReasonable,
    monthlySalary,
    monthlyCompensation,
  } = params;

  if (typeof monthlySalary !== 'number' || monthlySalary <= 0) {
    throw new Error(`analyzeNonCompete: invalid monthlySalary=${monthlySalary}`);
  }
  if (typeof monthlyCompensation !== 'number' || monthlyCompensation < 0) {
    throw new Error(`analyzeNonCompete: invalid monthlyCompensation=${monthlyCompensation}`);
  }
  if (typeof periodMonths !== 'number' || periodMonths < 0) {
    throw new Error(`analyzeNonCompete: invalid periodMonths=${periodMonths}`);
  }

  const trace = createTrace();
  addLaw(trace, {
    article: '勞基法§9-1 I',
    description:
      '未符合下列規定者，雇主不得與勞工為離職後競業禁止之約定：' +
      '一、雇主有應受保護之正當營業利益。' +
      '二、勞工擔任之職位或職務，能接觸或使用雇主之營業秘密。' +
      '三、競業禁止之期間、區域、職業活動之範圍及就業對象，未逾合理範疇。' +
      '四、雇主對勞工因不從事競業行為所受損失有合理補償。',
  });
  addLaw(trace, {
    article: '勞基法§9-1 III',
    description: '違反第一項各款規定之一者，其約定無效。',
  });

  /** @type {Array<{ key: string, status: 'pass'|'fail'|'warn', detail: string }>} */
  const checks = [];

  // 要件 1：正當營業利益
  if (hasLegitInterest === true) {
    checks.push({ key: 'LEGIT_INTEREST', status: 'pass', detail: '雇主具備應受保護之正當營業利益（§9-1 I 1）。' });
  } else {
    checks.push({
      key: 'LEGIT_INTEREST',
      status: 'fail',
      detail: '欠缺應受保護之正當營業利益，依§9-1 III 整份約定無效。',
    });
  }

  // 要件 2：勞工接觸營業秘密
  if (hasSecretAccess === true) {
    checks.push({ key: 'SECRET_ACCESS', status: 'pass', detail: '勞工職務能接觸或使用營業秘密（§9-1 I 2）。' });
  } else {
    checks.push({
      key: 'SECRET_ACCESS',
      status: 'fail',
      detail: '勞工未接觸或使用雇主營業秘密，限制競業欠缺必要性，依§9-1 III 約定無效。',
    });
  }

  // 要件 3a：期間 ≤ 2 年（§9-1 IV 強制縮短）
  const effectivePeriodMonths = Math.min(periodMonths, PERIOD_CAP_MONTHS);
  if (periodMonths <= PERIOD_CAP_MONTHS) {
    checks.push({
      key: 'PERIOD_REASONABLE',
      status: 'pass',
      detail: `競業禁止期間 ${periodMonths} 個月，未超過§9-1 IV 法定上限 24 個月。`,
    });
  } else {
    checks.push({
      key: 'PERIOD_REASONABLE',
      status: 'fail',
      detail:
        `競業禁止期間 ${periodMonths} 個月超過§9-1 IV 法定上限 24 個月，` +
        '超過部分依條文文義縮短為 2 年（細則§7-2 I 1 亦明定期間最長不得逾二年）。',
    });
  }
  addStep(trace, {
    label: '有效期間（§9-1 IV 縮短後）',
    formula: 'min(periodMonths, 24)',
    inputs: { periodMonths },
    value: effectivePeriodMonths,
    note: '逾 2 年部分當然無效',
  });

  // 要件 3b：範圍合理
  if (scopeReasonable === true) {
    checks.push({
      key: 'SCOPE_REASONABLE',
      status: 'pass',
      detail: '區域 / 職業活動 / 就業對象範圍合理且具體（細則§7-2）。',
    });
  } else {
    checks.push({
      key: 'SCOPE_REASONABLE',
      status: 'warn',
      detail:
        '範圍過寬或不具體者，未符§9-1 I 3 合理範疇要件（細則§7-2）；該款不符依§9-1 III 約定無效，實務上法院亦多酌減至合理範圍。',
    });
  }

  // 要件 4：補償金 ≥ 月薪 50%（細則§7-3）
  const minRequired = monthlySalary * COMPENSATION_FLOOR_RATIO;
  const monthlyGap = Math.max(0, minRequired - monthlyCompensation);
  const totalGap = monthlyGap * effectivePeriodMonths;
  const ratio = monthlySalary > 0 ? monthlyCompensation / monthlySalary : 0;
  addLaw(trace, {
    article: '勞基法施行細則§7-3 I 1',
    description: '每月補償金額不低於勞工離職時 1 個月平均工資百分之五十。',
  });
  addStep(trace, {
    label: '補償金最低標準',
    formula: 'monthlySalary × 0.5',
    inputs: { monthlySalary },
    value: minRequired,
  });
  if (monthlyCompensation >= minRequired) {
    checks.push({
      key: 'COMPENSATION_ADEQUATE',
      status: 'pass',
      detail: `補償金 ${Math.round(monthlyCompensation).toLocaleString()}/月（達月薪 ${(ratio * 100).toFixed(1)}%），符合細則§7-3 I 1 之 50% 最低標準。`,
    });
  } else {
    checks.push({
      key: 'COMPENSATION_ADEQUATE',
      status: 'fail',
      detail:
        `補償金 ${Math.round(monthlyCompensation).toLocaleString()}/月（僅達月薪 ${(ratio * 100).toFixed(1)}%）` +
        `低於細則§7-3 I 1 之 50% 下限（${Math.round(minRequired).toLocaleString()}/月）；` +
        `每月差額 ${Math.round(monthlyGap).toLocaleString()}，` +
        `有效期間 ${effectivePeriodMonths} 個月總差額 ${Math.round(totalGap).toLocaleString()}。` +
        '依§9-1 III 約定無效。',
    });
    addStep(trace, {
      label: '補償金差額試算',
      formula: '(minRequired − monthlyCompensation) × effectivePeriodMonths',
      inputs: { minRequired, monthlyCompensation, effectivePeriodMonths },
      value: totalGap,
    });
  }

  const passCount = checks.filter((c) => c.status === 'pass').length;
  /** @type {'green'|'yellow'|'red'} */
  let verdict;
  if (passCount === 5) {
    verdict = 'green';
    setSummary(trace, `合法性高：5 / 5 要件通過，協議具備較高效力（有效期間 ${effectivePeriodMonths} 個月）。`);
  } else if (passCount >= 3) {
    verdict = 'yellow';
    setSummary(trace, `合法性存疑：${passCount} / 5 要件通過，部分要件未達標。`);
  } else {
    verdict = 'red';
    setSummary(trace, `合法性低：${passCount} / 5 要件通過，依§9-1 III 可主張全部無效。`);
  }

  return {
    result: {
      passCount,
      verdict,
      checks,
      compensationGap: { monthlyGap, totalGap, minRequired, ratio },
      effectivePeriodMonths,
    },
    trace,
  };
}
