/**
 * leave.js — 特別休假與各類請假
 *
 * ## 法源（每條皆已於 https://law.moj.gov.tw 全國法規資料庫驗證原文）
 * - 勞基法§38                   特別休假
 * - 勞基法§43                   勞工因婚、喪、疾病或其他正當事由得請假；具體標準由
 *                              中央主管機關訂定（即「勞工請假規則」之授權條文）。
 * - 勞基法§50                   分娩前後產假 8 週；流產 4 週。受僱滿 6 個月者工資照給，
 *                              未滿 6 個月減半發給。
 * - 勞工請假規則§2              婚假 8 日，工資照給
 * - 勞工請假規則§3              喪假 8/6/3 日，工資照給（依親等三級）
 * - 勞工請假規則§4              普通傷病假；未住院 1 年內 30 日為限，住院 2 年內 1 年
 *                              365 日為限。請假期間工資折半發給；保險給付不足半薪時雇主補足。
 * - 勞工請假規則§6              公傷病假；治療休養期間，工資照給
 * - 勞工請假規則§7              事假 1 年內 14 日，不給工資
 * - 性平法§14                   生理假每月 1 日；全年未逾 3 日不併入病假計算，
 *                              其餘併入病假。薪資減半發給（半薪）。
 * - 性平法§15                   分娩前後產假 8 週；流產依妊娠週數 4 週/1 週/5 日；
 *                              產檢假 7 日（薪資照給）；陪產檢及陪產假 7 日（薪資照給）。
 *                              注意：性平法§15 V 之假名於 111-12-28 修正為「陪產檢及陪產假」。
 * - 性平法§20                   家庭照顧假併入事假計算，全年 7 日為限（薪資依事假規定）。
 *
 * ## 注意
 * 此檔之 traced 函式 `calcLeavePay` 同時提供舊有 `getAnnualLeaveDays`（純查表）。
 * 民眾版 laborpro 仍可繼續 import `getAnnualLeaveDays` 不受影響。
 */

import { createTrace, addStep, addLaw, setSummary } from './trace.js';
import { resolveValue, LEGAL_FLOOR } from './overrides.js';

// ─── 既有：特別休假天數查表（保留，不改 signature） ─────────────────

/**
 * 特休天數查表（勞基法§38）— 門檻型，應傳入整數月曆月（calcMonths 之 fullCalendarMonths）。
 * 法條原文以「繼續工作滿六個月以上一年未滿者」等月曆整月為門檻，故此處比較僅對整數月有意義。
 * 若傳入 totalMonths（serviceYears × 12）亦可運作，但邊界日（第 175-185 天）會有 ±3 天偏差。
 *   <6 月：無特休；<12 月：3 日；<24 月：7 日；<36 月：10 日
 *   <60 月：14 日；<120 月：15 日；10 年後每滿 1 年 +1 日，上限 30 日
 */
export function getAnnualLeaveDays(calendarMonths) {
  // 防呆：負數 / NaN / 非數字 → 視為 0 月（無特休）
  const months = Math.max(0, Number.isFinite(calendarMonths) ? calendarMonths : 0);
  if (months < 6) return 0;
  if (months < 12) return 3;
  if (months < 24) return 7;
  if (months < 36) return 10;
  if (months < 60) return 14;
  if (months < 120) return 15;

  const fullYears = Math.floor(months / 12);
  return Math.min(15 + (fullYears - 10), 30);
}

// ─── 新增：calcLeavePay（HR-UX-3） ────────────────────────────────

/**
 * 請假類型支援：
 *  - sick           普通傷病假（勞工請假規則§4）— 半薪
 *  - sick_serious   重大傷病假（住院型；勞工請假規則§4 後段）— 半薪
 *  - personal       事假（勞工請假規則§7）— 不給薪
 *  - bereavement    喪假（勞工請假規則§3）— 全薪；天數依親等：grade='1'|'2'|'3'
 *  - marriage       婚假（勞工請假規則§2）— 全薪 8 日
 *  - maternity      分娩產假（勞基法§50 / 性平法§15）— 滿 6 月全薪、未滿 6 月半薪；分娩 8 週
 *  - miscarriage_3m 流產假：妊娠 3 個月以上 4 週（性平法§15 I — 與分娩產假同條同項）
 *  - miscarriage_2m 流產假：妊娠 2-3 個月 1 週（性平法§15 I）
 *  - miscarriage_lt 流產假：妊娠未滿 2 個月 5 日（性平法§15 I）
 *  - paternity      陪產檢及陪產假（性平法§15 V）— 全薪 7 日
 *  - prenatal       產檢假（性平法§15 IV）— 全薪 7 日
 *  - family_care    家庭照顧假（性平法§20）— 併入事假計算全年 7 日，依事假規定（不給薪）
 *  - menstrual      生理假（性平法§14）— 半薪；全年未逾 3 日不併入病假
 *  - public_injury  公傷病假（勞工請假規則§6）— 全薪
 *  - public_duty    公假（勞工請假規則§8）— 全薪
 *
 * 工資成數常數（依條文，不自創）。
 */
export const LEAVE_PAY_RATE = Object.freeze({
  full: 1,
  half: 0.5,
  unpaid: 0,
});

/**
 * 各假別「條文上限天數」與「工資成數」的查表
 * 各 entry 來源條文已在頂部 ## 法源 註明
 */
const LEAVE_RULES = Object.freeze({
  sick:          { maxDays: 30,  rate: LEAVE_PAY_RATE.half,   article: '勞工請假規則§4', desc: '普通傷病假未住院 1 年內以 30 日為限，工資折半發給' },
  sick_serious:  { maxDays: 365, rate: LEAVE_PAY_RATE.half,   article: '勞工請假規則§4', desc: '住院傷病假 2 年內合計 1 年 365 日為限，工資折半發給；保險給付不足半薪時雇主補足' },
  personal:      { maxDays: 14,  rate: LEAVE_PAY_RATE.unpaid, article: '勞工請假規則§7', desc: '事假 1 年內 14 日為限，不給工資' },
  marriage:      { maxDays: 8,   rate: LEAVE_PAY_RATE.full,   article: '勞工請假規則§2', desc: '婚假 8 日，工資照給' },
  // bereavement 三級走 helper（grade 決定天數）
  maternity:     { maxDays: 56,  rate: LEAVE_PAY_RATE.full,   article: '勞基法§50、性平法§15 I', desc: '分娩前後產假 8 週共 56 日；受僱滿 6 個月工資照給，未滿 6 個月減半發給' },
  miscarriage_3m:{ maxDays: 28,  rate: LEAVE_PAY_RATE.full,   article: '性平法§15 I',      desc: '妊娠 3 個月以上流產者，產假 4 週（28 日）；薪資依勞基法§50' },
  miscarriage_2m:{ maxDays: 7,   rate: LEAVE_PAY_RATE.full,   article: '性平法§15 I',      desc: '妊娠 2-3 個月流產者，產假 1 週（7 日）；薪資依勞基法§50' },
  miscarriage_lt:{ maxDays: 5,   rate: LEAVE_PAY_RATE.full,   article: '性平法§15 I',      desc: '妊娠未滿 2 個月流產者，產假 5 日；薪資依勞基法§50' },
  paternity:     { maxDays: 7,   rate: LEAVE_PAY_RATE.full,   article: '性平法§15 V',    desc: '陪產檢及陪產假 7 日，薪資照給' },
  prenatal:      { maxDays: 7,   rate: LEAVE_PAY_RATE.full,   article: '性平法§15 IV',   desc: '產檢假 7 日，薪資照給' },
  family_care:   { maxDays: 7,   rate: LEAVE_PAY_RATE.unpaid, article: '性平法§20',     desc: '家庭照顧假併入事假計算，全年 7 日為限；薪資依事假規定（不給薪）' },
  menstrual:     { maxDays: 12,  rate: LEAVE_PAY_RATE.half,   article: '性平法§14',     desc: '每月 1 日，全年 3 日不併入病假計算；薪資減半發給' },
  public_injury: { maxDays: 0,   rate: LEAVE_PAY_RATE.full,   article: '勞工請假規則§6', desc: '公傷病假，治療休養期間工資照給；上限視實際治療期間而定（本函式不限）' },
  public_duty:   { maxDays: 0,   rate: LEAVE_PAY_RATE.full,   article: '勞工請假規則§8', desc: '公假，工資照給；期限視法令需要' },
});

/** 喪假天數依親等（勞工請假規則§3） */
const BEREAVEMENT_DAYS = Object.freeze({
  grade1: 8, // 父母、養父母、繼父母、配偶
  grade2: 6, // 祖父母、子女、配偶之父母、配偶之養父母或繼父母
  grade3: 3, // 曾祖父母、兄弟姊妹、配偶之祖父母
});

/**
 * 解析單一假別的工資成數（含 override 守門）
 *
 * 目前 LEGAL_FLOOR 涵蓋：
 *   - leave_marriage_days        (婚假天數)
 *   - leave_menstrual_pay_rate   (生理假成數)
 * 其他假別暫無 override key（API 端 whitelist 控制），後續若 0005 migration 加 key 再展開。
 */
function resolveLeaveDays(overrides, leaveType) {
  if (leaveType === 'marriage') {
    return resolveValue(
      overrides,
      'leave.marriage_days',
      'days',
      LEGAL_FLOOR.leave_marriage_days,
    );
  }
  return null;
}
function resolveLeaveRate(overrides, leaveType) {
  if (leaveType === 'menstrual') {
    return resolveValue(
      overrides,
      'leave.menstrual_pay_rate',
      'rate',
      LEGAL_FLOOR.leave_menstrual_pay_rate,
    );
  }
  return null;
}

/**
 * 計算單筆請假應發工資（含 trace）
 *
 * @param {Object} params
 * @param {keyof typeof LEAVE_RULES | 'bereavement'} params.leaveType
 * @param {number} params.days                  本次請假日數（小時數請於 caller 端先 ÷8 換算為日）
 * @param {number} params.monthlySalary         月薪（用於日薪換算 monthlySalary / 30）
 * @param {('grade1'|'grade2'|'grade3')} [params.bereavementGrade]   leaveType=bereavement 時必填
 * @param {boolean} [params.maternityOver6Months]                    leaveType=maternity 時：是否受僱滿 6 個月（影響工資成數）
 * @param {Object} [params.overrides]                                 內部規範覆寫
 * @returns {import('./trace.js').TracedResult}
 *           result = 應發工資（NTD）
 */
export function calcLeavePay(params) {
  const {
    leaveType,
    days,
    monthlySalary,
    bereavementGrade,
    maternityOver6Months,
    overrides,
  } = params;

  if (typeof days !== 'number' || days < 0) {
    throw new Error(`calcLeavePay: invalid days=${days}`);
  }
  if (typeof monthlySalary !== 'number' || monthlySalary < 0) {
    throw new Error(`calcLeavePay: invalid monthlySalary=${monthlySalary}`);
  }

  const trace = createTrace();
  const dailyRate = monthlySalary / 30;

  addStep(trace, {
    label: '日薪換算',
    formula: 'monthlySalary / 30',
    inputs: { monthlySalary },
    value: dailyRate,
    note: '勞基法§2 第 4 款平均工資推算之日薪基礎',
  });
  addLaw(trace, { article: '勞基法§43', description: '勞工因婚、喪、疾病或其他正當事由得請假；具體標準依「勞工請假規則」' });

  // ── 喪假特殊路徑（grade 決天數，皆全薪） ──
  if (leaveType === 'bereavement') {
    if (!bereavementGrade || !(bereavementGrade in BEREAVEMENT_DAYS)) {
      throw new Error(`calcLeavePay(bereavement): missing/invalid bereavementGrade`);
    }
    const maxDays = BEREAVEMENT_DAYS[bereavementGrade];
    const eligibleDays = Math.min(days, maxDays);
    const overflow = Math.max(days - maxDays, 0);
    const pay = eligibleDays * dailyRate * LEAVE_PAY_RATE.full;
    addLaw(trace, {
      article: '勞工請假規則§3',
      description: `喪假 ${maxDays} 日（親等 ${bereavementGrade}），工資照給`,
    });
    addStep(trace, {
      label: '可請喪假日數',
      formula: `min(days, ${maxDays})`,
      inputs: { days, max: maxDays },
      value: eligibleDays,
      note: `親等 ${bereavementGrade}：條文上限 ${maxDays} 日`,
    });
    addStep(trace, {
      label: '應發工資',
      formula: 'eligibleDays × dailyRate × 1',
      inputs: { eligibleDays, dailyRate },
      value: pay,
      note: '喪假全薪（rate=1）',
    });
    setSummary(
      trace,
      `喪假 ${eligibleDays} 日（全薪）= ${Math.round(pay).toLocaleString()} 元` +
        (overflow > 0 ? ` · 超出條文上限 ${overflow} 日不予計` : ''),
    );
    return { result: pay, trace };
  }

  // ── 一般查表路徑 ──
  const rule = LEAVE_RULES[leaveType];
  if (!rule) throw new Error(`calcLeavePay: unknown leaveType=${leaveType}`);

  // override：天數（目前僅 marriage）
  let appliedMaxDays = rule.maxDays;
  const daysOverride = resolveLeaveDays(overrides, leaveType);
  if (daysOverride && daysOverride.overridden) {
    appliedMaxDays = daysOverride.value;
    addLaw(trace, {
      article: daysOverride.sourceRef ?? '內部規範（優於法規）',
      description:
        `${leaveType} 上限 ${appliedMaxDays} 日（法規 ${rule.maxDays}）` +
        (daysOverride.note ? ' · ' + daysOverride.note : ''),
    });
  }

  // override：工資成數（目前僅 menstrual）
  /** @type {number} */
  let appliedRate = rule.rate;
  let rateOverride = resolveLeaveRate(overrides, leaveType);
  if (rateOverride && rateOverride.overridden) {
    appliedRate = rateOverride.value;
    addLaw(trace, {
      article: rateOverride.sourceRef ?? '內部規範（優於法規）',
      description:
        `${leaveType} 工資成數 ${appliedRate}（法規 ${rule.rate}）` +
        (rateOverride.note ? ' · ' + rateOverride.note : ''),
    });
  }

  // 產假滿 / 未滿 6 個月（勞基法§50 II）
  if (leaveType === 'maternity') {
    if (typeof maternityOver6Months !== 'boolean') {
      throw new Error('calcLeavePay(maternity): maternityOver6Months 必填 boolean');
    }
    appliedRate = maternityOver6Months ? LEAVE_PAY_RATE.full : LEAVE_PAY_RATE.half;
    addStep(trace, {
      label: '受僱滿 6 個月判定',
      formula: 'maternityOver6Months ? 1 : 0.5',
      inputs: { maternityOver6Months: maternityOver6Months ? 1 : 0 },
      value: appliedRate,
      note: '勞基法§50 II：受僱滿 6 月者工資照給，未滿 6 月減半',
    });
  }

  addLaw(trace, { article: rule.article, description: rule.desc });

  // 上限套用：max=0 視為「條文未訂上限」（公假 / 公傷病假），不裁切
  const eligibleDays = appliedMaxDays > 0 ? Math.min(days, appliedMaxDays) : days;
  const overflow = appliedMaxDays > 0 ? Math.max(days - appliedMaxDays, 0) : 0;

  if (appliedMaxDays > 0) {
    addStep(trace, {
      label: '可請日數',
      formula: `min(days, ${appliedMaxDays})`,
      inputs: { days, max: appliedMaxDays },
      value: eligibleDays,
      note: overflow > 0 ? `超出條文/內部上限 ${overflow} 日` : '在條文上限內',
    });
  } else {
    addStep(trace, {
      label: '可請日數',
      formula: 'days',
      inputs: { days },
      value: eligibleDays,
      note: '條文未訂上限（公假 / 公傷病假，依實際治療或法令需要）',
    });
  }

  const pay = eligibleDays * dailyRate * appliedRate;
  addStep(trace, {
    label: '應發工資',
    formula: 'eligibleDays × dailyRate × rate',
    inputs: { eligibleDays, dailyRate, rate: appliedRate },
    value: pay,
    note:
      appliedRate === 0
        ? '不給工資（事假 / 家庭照顧假）'
        : appliedRate === 0.5
        ? '半薪'
        : '全薪',
  });

  setSummary(
    trace,
    `${leaveType} ${eligibleDays} 日 (${(appliedRate * 100).toFixed(0)}%) = ${Math.round(pay).toLocaleString()} 元` +
      (overflow > 0 ? ` · 超出 ${overflow} 日不予計` : ''),
  );

  return { result: pay, trace };
}
