/**
 * payslip-checker.js — 薪資單核對（按勞健保級距 + 本薪 + 加扣項勾稽）
 *
 * 抽 apps/etp/public/hr-tools/payslip-checker.html 內 calculate() 進 core-labor。
 *
 * ## 法源（每條已於 https://law.moj.gov.tw 全國法規資料庫驗證）
 *
 * - 勞基法§22 II（工資全額給付）
 *     工資應全額直接給付勞工。但法令另有規定或勞雇雙方另有約定者，不在此限。
 *
 * - 勞工保險條例§13（普通事故保險費率）
 *     普通事故保險費率，為被保險人當月投保薪資百分之七點五至百分之十三；現行
 *     11%（含就業保險 1% 共 12%）；勞工自付 20%。
 *     ※ 本檔採 LABOR_RATES_2026.labor = 0.125（含就保），勞工自付 20% → 有效
 *        個人費率 0.125 × 0.20 = 0.025 = 2.5%
 *
 * - 勞工保險條例§14（投保薪資分級表）
 *     被保險人之投保薪資，按其月薪資總額依「勞工保險投保薪資分級表」之規定，
 *     向保險人申報之。115 年 11 級下限 29,500、上限 45,800（勞動保 2 字
 *     第 1140091863 號令）。
 *
 * - 全民健康保險法§19、§27（健保費 + 分擔比例）
 *     一般受僱者投保金額 × 保險費率（115 年 5.17%）；
 *     受僱者負擔 30%、雇主 60%、政府 10%。
 *     ※ 有效個人費率 0.0517 × 0.30 ≈ 1.551%
 *
 * ## 檢查項目
 *
 *   1. 本薪：按比例 (actualDays / expectedDays) × agreedSalary
 *   2. 勞保自付：findLaborBracket(agreedSalary) × 2.5%
 *      - 實扣 < 應扣 → 警示「可能高薪低報」（勞保條例§72 III）
 *      - 實扣 > 應扣 → 警示「請確認級距」
 *   3. 健保自付：findNhiBracket(agreedSalary) × 1.551%
 *      - 偵測倍數（眷屬人數）— 整數倍視為含眷屬
 *      - 實扣 < 應扣 × 0.9 → 警示「可能高薪低報」
 *   4. 加總 slipGross / slipDeductions → calcNetPay
 *   5. 與薪資單 netPay 比對：差額 > 1 元 → 警示
 *
 * @module payslip-checker
 */

import { createTrace, addStep, addLaw, setSummary } from './trace.js';
import {
  LABOR_INSURANCE_BRACKETS_2026,
  NHI_BRACKETS_2026,
  getLaborInsuranceBracket,
  getNhiBracket,
} from './brackets.js';
import { LABOR_RATES_2026 } from './insurance.js';

/** 勞工個人勞保有效費率（labor × laborEmployee） */
export const LABOR_INS_WORKER_RATE =
  LABOR_RATES_2026.labor * LABOR_RATES_2026.laborEmployee;

/** 健保個人有效費率（nhi × nhiEmployee） */
export const HEALTH_INS_WORKER_RATE =
  LABOR_RATES_2026.nhi * LABOR_RATES_2026.nhiEmployee;

/** 差額容許閾值（NT$） */
const TOLERANCE = 1;

/** 健保倍數判斷容許誤差（含眷屬時實扣為 N 倍應扣） */
const HEALTH_MULTIPLE_TOLERANCE = 0.05;

function roundCurrency(n) {
  return Math.round(n);
}

function statusLabel(actual, expected, opts = {}) {
  if (actual === 0) return 'missing';
  const diff = Math.abs(actual - expected);
  if (diff < (opts.toleranceAbs ?? 2)) return 'pass';
  if (actual < expected) return 'underpaid';
  return 'overpaid';
}

/**
 * 主檢查：薪資單 vs 約定薪資 + 級距推算
 *
 * @param {object} params
 * @param {number} params.agreedSalary 約定月薪（級距用）
 * @param {number} params.actualDays 本月實際工作天數
 * @param {number} [params.expectedDays=22] 預期工作天數
 * @param {object} params.slip 薪資單欄位
 * @param {number} params.slip.basePay 本薪
 * @param {number} [params.slip.overtimePay=0] 加班費
 * @param {number} [params.slip.attendanceBonus=0] 全勤獎金
 * @param {number} [params.slip.otherAdd=0] 其他加項
 * @param {number} params.slip.laborInsurance 勞保自付
 * @param {number} params.slip.healthInsurance 健保自付
 * @param {number} [params.slip.taxWithhold=0] 所得稅預扣
 * @param {number} [params.slip.otherDeduct=0] 其他扣項
 * @param {number} params.slip.netPay 實領
 * @returns {{
 *   expected: { basePay, laborBracket, expectedLaborIns, healthBracket, expectedHealthIns, healthDependents },
 *   slip: { gross, deductions, calcNetPay },
 *   checks: { basePay, laborIns, healthIns, netPay },
 *   netPayDiff: number,
 *   overallLevel: 'pass'|'warn'|'fail',
 *   trace
 * }}
 */
export function checkPayslip({
  agreedSalary,
  actualDays,
  expectedDays = 22,
  slip,
}) {
  if (!Number.isFinite(agreedSalary) || agreedSalary <= 0) {
    throw new Error('checkPayslip: agreedSalary 必須為 > 0 的數字');
  }
  if (!Number.isFinite(actualDays) || actualDays < 0) {
    throw new Error('checkPayslip: actualDays 必須為 ≥ 0');
  }
  if (!Number.isFinite(expectedDays) || expectedDays <= 0) {
    throw new Error('checkPayslip: expectedDays 必須為 > 0');
  }
  if (!slip || typeof slip !== 'object') {
    throw new Error('checkPayslip: slip 物件必填');
  }

  const basePay = Number(slip.basePay) || 0;
  const otPay = Number(slip.overtimePay) || 0;
  const attendanceBonus = Number(slip.attendanceBonus) || 0;
  const otherAdd = Number(slip.otherAdd) || 0;
  const laborIns = Number(slip.laborInsurance) || 0;
  const healthIns = Number(slip.healthInsurance) || 0;
  const taxWithhold = Number(slip.taxWithhold) || 0;
  const otherDeduct = Number(slip.otherDeduct) || 0;
  const netPay = Number(slip.netPay) || 0;

  // 1. 本薪預期
  const expectedBasePay =
    actualDays >= expectedDays
      ? agreedSalary
      : roundCurrency(agreedSalary * (actualDays / expectedDays));

  // 2. 勞保
  const laborBracket = getLaborInsuranceBracket(agreedSalary);
  const expectedLaborIns = roundCurrency(laborBracket * LABOR_INS_WORKER_RATE);

  // 3. 健保（含眷屬倍數偵測）
  const healthBracket = getNhiBracket(agreedSalary);
  const expectedHealthIns = roundCurrency(
    healthBracket * HEALTH_INS_WORKER_RATE,
  );
  let healthDependents = 0;
  let isHealthMultiple = false;
  if (healthIns > 0 && expectedHealthIns > 0) {
    const ratio = healthIns / expectedHealthIns;
    const rounded = Math.round(ratio);
    if (
      rounded >= 1 &&
      Math.abs(ratio - rounded) < HEALTH_MULTIPLE_TOLERANCE
    ) {
      isHealthMultiple = true;
      healthDependents = rounded;
    }
  }

  // 4. 加總
  const slipGross = basePay + otPay + attendanceBonus + otherAdd;
  const slipDeductions = laborIns + healthIns + taxWithhold + otherDeduct;
  const calcNetPay = slipGross - slipDeductions;
  const netPayDiff = netPay - calcNetPay;

  // 5. 個別 check 等級
  const checks = {
    basePay: {
      level:
        Math.abs(basePay - expectedBasePay) < TOLERANCE ? 'pass' : 'fail',
      actual: basePay,
      expected: expectedBasePay,
      diff: roundCurrency(basePay - expectedBasePay),
    },
    laborIns: (() => {
      const s = statusLabel(laborIns, expectedLaborIns, { toleranceAbs: 2 });
      let level = 'pass';
      let note = '';
      if (s === 'missing') {
        level = 'warn';
        note = '未扣勞保（可能未投保）';
      } else if (s === 'pass') {
        level = 'pass';
      } else if (s === 'underpaid') {
        level = 'fail';
        note = '低於應扣，可能高薪低報（勞保條例§72 III）';
      } else {
        level = 'warn';
        note = '高於應扣，請確認級距';
      }
      return {
        level,
        actual: laborIns,
        expected: expectedLaborIns,
        bracket: laborBracket,
        note,
      };
    })(),
    healthIns: (() => {
      let level = 'pass';
      let note = '';
      if (healthIns === 0) {
        level = 'warn';
        note = '未扣健保（可能未投保）';
      } else if (isHealthMultiple) {
        level = 'pass';
        note =
          healthDependents > 1
            ? `本人 + ${healthDependents - 1} 名眷屬`
            : '本人';
      } else if (healthIns < expectedHealthIns * 0.9) {
        level = 'fail';
        note = '顯著低於應扣，可能高薪低報';
      } else {
        level = 'warn';
        note = '請確認眷屬人數與級距';
      }
      return {
        level,
        actual: healthIns,
        expected: expectedHealthIns,
        bracket: healthBracket,
        dependents: isHealthMultiple ? healthDependents : null,
        note,
      };
    })(),
    netPay: {
      level: Math.abs(netPayDiff) < TOLERANCE ? 'pass' : 'fail',
      actual: netPay,
      expected: calcNetPay,
      diff: roundCurrency(netPayDiff),
      direction:
        netPayDiff > 0 ? 'over' : netPayDiff < 0 ? 'under' : 'match',
    },
  };

  const allLevels = Object.values(checks).map((c) => c.level);
  const overallLevel = allLevels.includes('fail')
    ? 'fail'
    : allLevels.includes('warn')
      ? 'warn'
      : 'pass';

  // trace
  const trace = createTrace();
  addStep(trace, {
    label: '本薪比對',
    formula:
      actualDays >= expectedDays
        ? 'agreedSalary'
        : 'agreedSalary × (actualDays / expectedDays)',
    inputs: { agreedSalary, actualDays, expectedDays },
    value: expectedBasePay,
    note: `薪資單本薪 ${basePay.toLocaleString()}，差 ${(basePay - expectedBasePay).toLocaleString()}`,
  });
  addStep(trace, {
    label: '勞保自付推算',
    formula: 'getLaborInsuranceBracket(agreedSalary) × 2.5%',
    inputs: {
      bracket: laborBracket,
      rate: Number(LABOR_INS_WORKER_RATE.toFixed(4)),
    },
    value: expectedLaborIns,
    note: checks.laborIns.note || '與薪資單一致',
  });
  addStep(trace, {
    label: '健保自付推算',
    formula: 'getNhiBracket(agreedSalary) × 1.551%',
    inputs: {
      bracket: healthBracket,
      rate: Number(HEALTH_INS_WORKER_RATE.toFixed(4)),
    },
    value: expectedHealthIns,
    note: checks.healthIns.note || '與薪資單一致',
  });
  addStep(trace, {
    label: '實領比對',
    formula: 'gross − deductions = calcNet ?= 薪資單 net',
    inputs: {
      gross: slipGross,
      deductions: slipDeductions,
      calcNet: roundCurrency(calcNetPay),
      slipNet: netPay,
    },
    value: roundCurrency(netPayDiff),
    note:
      Math.abs(netPayDiff) < TOLERANCE
        ? '一致'
        : netPayDiff < 0
          ? '薪資單實領低於計算（可能短付）'
          : '薪資單實領高於計算',
  });
  addLaw(trace, {
    article: '勞基法§22 II',
    description: '工資應全額直接給付勞工。',
  });
  addLaw(trace, {
    article: '勞工保險條例§13、§14',
    description:
      '普通事故保險費率現行 12.5%（含就保），個人自付 20%；投保薪資依分級表申報。',
  });
  addLaw(trace, {
    article: '全民健康保險法§19、§27',
    description:
      '健保費率 5.17%；受僱者負擔 30%、雇主 60%、政府 10%。',
  });
  if (checks.laborIns.level === 'fail' || checks.healthIns.level === 'fail') {
    addLaw(trace, {
      article: '勞工保險條例§72 III',
      description:
        '高薪低報之雇主處應繳保險費金額 4 倍之罰鍰，並補繳差額；勞工得申訴勞保局查核。',
    });
  }
  setSummary(
    trace,
    overallLevel === 'pass'
      ? '薪資單與級距 + 約定薪資一致。'
      : `${overallLevel === 'fail' ? '可能違規' : '部分需確認'}：` +
          `本薪${checks.basePay.level}、勞保${checks.laborIns.level}、健保${checks.healthIns.level}、實領${checks.netPay.level}`,
  );

  return {
    expected: {
      basePay: expectedBasePay,
      laborBracket,
      expectedLaborIns,
      healthBracket,
      expectedHealthIns,
      healthDependents: isHealthMultiple ? healthDependents : 0,
    },
    slip: {
      gross: roundCurrency(slipGross),
      deductions: roundCurrency(slipDeductions),
      calcNetPay: roundCurrency(calcNetPay),
    },
    checks,
    netPayDiff: roundCurrency(netPayDiff),
    overallLevel,
    trace,
  };
}

// 對外露 brackets table 給 UI 顯示（簡寫版）
export { LABOR_INSURANCE_BRACKETS_2026, NHI_BRACKETS_2026 } from './brackets.js';
