/**
 * overtime-matrix.js — 加班費情境矩陣（HR-UX-3 補完）
 *
 * 在既有 `overtime-traced.js`（weekday/restday/holiday/mixed）之外，加上：
 *   1. 例假（regular_off）         — 勞基法§40：天災事變突發事件加倍 + 補假
 *   2. 國定假日（national_holiday） — 勞基法§37、§39：應放假；雇主經勞工同意工作工資加倍
 *   3. 颱風假（typhoon）            — 內政部「天然災害發生事業單位勞工出勤管理及工資給付要點」
 *                                    法律上非「假日」；雇主給薪本不強制，但實務多以工資照給或
 *                                    加給處理
 *   4. 休息日「2-2-2 階梯」說明     — 現有實作已涵蓋（§24 II），本檔只額外標記階梯
 *   5. 補休 vs 加班費（§32-1）      — 勞工選擇補休、雇主同意者，依時數 1:1 換補休；
 *                                    補休期限屆滿或契約終止未補休者，按原延長工作當日工資計發
 *
 * ## 法源（每條已於全國法規資料庫驗證）
 * - 勞基法§24                         平日延長工時 + 休息日階梯
 * - 勞基法§32-1                       補休（一比一）；屆期未休發回工資
 * - 勞基法§36                         例假與休息日（七休一）
 * - 勞基法§37                         應放假之紀念日 / 節日 / 勞動節
 * - 勞基法§39                         休假日工作經勞工同意者，工資應加倍發給
 * - 勞基法§40                         天災 / 事變 / 突發事件停止假期、工資加倍 + 事後補假
 * - 內政部「天然災害發生事業單位勞工出勤管理及工資給付要點」（颱風假）
 */

import { createTrace, addStep, addLaw, setSummary } from './trace.js';
import { resolveOvertimeRate, LEGAL_FLOOR } from './overrides.js';
import { calcOvertimeCostTraced } from './overtime-traced.js';

/**
 * 例假日 / 國定假日出勤工資（勞基法§37、§39、§40）
 *
 * @param {Object} params
 * @param {number} params.monthlySalary
 * @param {number} params.hours                  本日出勤時數（一般當日 8 小時為一日）
 * @param {'regular_off'|'national_holiday'} params.type
 * @param {boolean} [params.disasterClause]      `§40`：是否屬於天災 / 事變 / 突發事件停止假期
 * @param {Object} [params.overrides]
 * @returns {import('./trace.js').TracedResult}
 */
export function calcSpecialHolidayPay(params) {
  const { monthlySalary, hours, type, disasterClause, overrides } = params;
  if (typeof monthlySalary !== 'number' || monthlySalary <= 0) {
    throw new Error('calcSpecialHolidayPay: invalid monthlySalary');
  }
  if (typeof hours !== 'number' || hours < 0) {
    throw new Error('calcSpecialHolidayPay: invalid hours');
  }

  const trace = createTrace();
  const hourly = monthlySalary / 30 / 8;

  addStep(trace, {
    label: '時薪換算',
    formula: 'monthlySalary / 30 / 8',
    inputs: { monthlySalary },
    value: hourly,
  });

  if (type === 'regular_off') {
    addLaw(trace, {
      article: '勞基法§36、§40',
      description: '例假非天災事變突發事件不得使勞工工作；§40 停止假期工資加倍發給並給予事後補假',
    });
    if (!disasterClause) {
      addStep(trace, {
        label: '合法性提示',
        formula: 'n/a',
        value: 0,
        note: '⚠️ 例假非§40 三事由（天災 / 事變 / 突發事件）不得使勞工工作；本試算僅作為違法時應給之最低補償參考',
      });
    }
    const rh = resolveOvertimeRate(overrides, 'holiday'); // 例假倍率與國定同走 holiday key
    const total = hours * hourly * rh.value;
    addStep(trace, {
      label: '例假出勤加倍工資',
      formula: `hours × hourly × ${rh.value}`,
      inputs: { hours, hourly, rate: rh.value },
      value: total,
      note: rh.overridden
        ? `貴單位倍率 ${rh.value}（法規 ${LEGAL_FLOOR.overtime_rate_holiday}）`
        : '加倍發給（§40）',
    });
    setSummary(
      trace,
      `例假出勤 ${hours} 小時 = ${Math.round(total).toLocaleString()} 元（${rh.value}x）` +
        (disasterClause ? ' · 已勾選§40 三事由' : ' · 提示：非§40 事由不得出勤'),
    );
    return { result: total, trace };
  }

  if (type === 'national_holiday') {
    addLaw(trace, {
      article: '勞基法§37、§39',
      description: '紀念日 / 節日 / 勞動節應放假；經勞工同意工作者，工資應加倍發給',
    });
    const rh = resolveOvertimeRate(overrides, 'holiday');
    const total = hours * hourly * rh.value;
    addStep(trace, {
      label: '國定假日出勤',
      formula: `hours × hourly × ${rh.value}`,
      inputs: { hours, hourly, rate: rh.value },
      value: total,
      note: rh.overridden
        ? `貴單位倍率 ${rh.value}（法規 ${LEGAL_FLOOR.overtime_rate_holiday}）`
        : '工資加倍發給（§39）',
    });
    setSummary(
      trace,
      `國定假日出勤 ${hours} 小時 = ${Math.round(total).toLocaleString()} 元（${rh.value}x）`,
    );
    return { result: total, trace };
  }

  throw new Error(`calcSpecialHolidayPay: unknown type=${type}`);
}

/**
 * 颱風假（天然災害）工資處理 — 提示型函式
 *
 * 法源：內政部「天然災害發生事業單位勞工出勤管理及工資給付要點」（行政指導，非強制）。
 * 結論（要點明訂）：
 *   - 雇主「不得視為曠工、遲到或強迫勞工以事假處理」
 *   - 工資是否照給「由勞雇雙方協商」（要點未強制工資照給）
 *   - 出勤者宜「加給勞工工資」；停班期間工資照給為宜
 *
 * 本函式僅依使用者輸入回報「應如何處理」+ 試算金額（出勤者建議加成）。
 *
 * @param {Object} params
 * @param {number} params.monthlySalary
 * @param {number} params.hours                  出勤時數（0 = 未到班）
 * @param {boolean} [params.workplaceAnnouncedClosure]   雇主有公告停班
 * @returns {import('./trace.js').TracedResult}
 */
export function calcTyphoonDay(params) {
  const { monthlySalary, hours, workplaceAnnouncedClosure } = params;
  const trace = createTrace();
  const dailyRate = monthlySalary / 30;
  const hourly = dailyRate / 8;

  addLaw(trace, {
    article: '內政部「天然災害發生事業單位勞工出勤管理及工資給付要點」',
    description:
      '勞動部 / 內政部行政指導；非勞基法強制條文。雇主不得視颱風假為曠工或強迫以事假處理；工資是否照給由勞雇雙方協商，出勤者宜加成發給。',
  });

  addStep(trace, {
    label: '日薪換算',
    formula: 'monthlySalary / 30',
    inputs: { monthlySalary },
    value: dailyRate,
  });

  if (hours === 0) {
    // 未出勤
    addStep(trace, {
      label: '未出勤處理',
      formula: 'n/a',
      value: 0,
      note: workplaceAnnouncedClosure
        ? '雇主公告停班 → 不得視為曠工；工資照給為宜（依要點建議）'
        : '雇主未公告停班 → 仍不得逕行扣全勤或強迫以事假處理；個案處理',
    });
    setSummary(
      trace,
      workplaceAnnouncedClosure
        ? '颱風停班未出勤：建議工資照給（要點建議，非強制）'
        : '颱風日未出勤：依要點不得視為曠工，個案協商',
    );
    return { result: workplaceAnnouncedClosure ? dailyRate : 0, trace };
  }

  // 有出勤：原工資 + 建議加成（要點僅建議「加給」，無法定倍率）
  // 採行政指導實務常見做法：原工資全給 + 加發 1 日工資（共 2 倍），
  // 但必須註記為「建議」非法定強制
  const basePay = hours * hourly;
  const recommendedExtra = hours * hourly; // 額外 1 倍建議
  const total = basePay + recommendedExtra;

  addStep(trace, {
    label: '出勤工資（基本）',
    formula: 'hours × hourly',
    inputs: { hours, hourly },
    value: basePay,
  });
  addStep(trace, {
    label: '建議加成（行政指導）',
    formula: 'hours × hourly × 1',
    inputs: { hours, hourly, rate: 1 },
    value: recommendedExtra,
    note: '⚠️ 要點僅「宜加給」，未明定倍率；本系統採實務常見的 +1 倍作建議基準（非法定強制）',
  });
  addStep(trace, {
    label: '合計',
    formula: 'basePay + recommendedExtra',
    value: total,
  });
  setSummary(
    trace,
    `颱風日出勤 ${hours} 小時：建議共 ${Math.round(total).toLocaleString()} 元（基本 + 行政指導建議加成）`,
  );

  return { result: total, trace };
}

/**
 * computeOvertimePay — HR-UX-3 Pack A 規格 API
 *
 * 統一封裝四類加班費（平日延長 / 休息日 / 國定假日 / 例假日），全部回傳 traced 結果。
 *
 * @param {Object} params
 * @param {number} params.baseSalary       月薪（NTD）
 * @param {number} params.dailyHours       當日加班時數（不是當日總工時；本參數已扣除前 8h 正常工時）
 * @param {'workday'|'restday'|'holiday'|'rest_holiday'} params.weekday
 *        - workday      平日延長（§24 I：前 2h 1.34 倍 / 第 3-4h 1.67 倍）
 *        - restday      休息日（§24 II：前 2h 1.34 倍 / 第 3-12h 1.67 倍）
 *        - holiday      國定假日（§37、§39：當日工資加倍 + 出勤工時加倍 ≈ 2 倍）
 *        - rest_holiday 例假日（§40：須先停休再勞動，出勤工時加倍）
 * @param {boolean} [params.disasterClause] 例假日：是否屬於§40 三事由（天災/事變/突發事件）
 * @param {Object} [params.overrides]       內部規範覆寫
 * @returns {{ amount: number, trace: import('./trace.js').CalcTrace }}
 *
 * 法源：勞基法§24 I/II、§37、§39、§40
 */
export function computeOvertimePay(params) {
  const { baseSalary, dailyHours, weekday, disasterClause, overrides } = params;
  if (typeof baseSalary !== 'number' || baseSalary <= 0) {
    throw new Error('computeOvertimePay: invalid baseSalary');
  }
  if (typeof dailyHours !== 'number' || dailyHours < 0) {
    throw new Error('computeOvertimePay: invalid dailyHours');
  }

  switch (weekday) {
    case 'workday': {
      const r = calcOvertimeCostTraced(baseSalary, dailyHours, 'weekday', { overrides });
      return { amount: r.result, trace: r.trace };
    }
    case 'restday': {
      const r = calcOvertimeCostTraced(baseSalary, dailyHours, 'restday', { overrides });
      return { amount: r.result, trace: r.trace };
    }
    case 'holiday': {
      const r = calcSpecialHolidayPay({
        monthlySalary: baseSalary,
        hours: dailyHours,
        type: 'national_holiday',
        overrides,
      });
      return { amount: r.result, trace: r.trace };
    }
    case 'rest_holiday': {
      const r = calcSpecialHolidayPay({
        monthlySalary: baseSalary,
        hours: dailyHours,
        type: 'regular_off',
        disasterClause: disasterClause === true,
        overrides,
      });
      return { amount: r.result, trace: r.trace };
    }
    default:
      throw new Error(
        `computeOvertimePay: unknown weekday=${weekday} (allowed: workday|restday|holiday|rest_holiday)`,
      );
  }
}

/**
 * §32-1 補休 vs 加班費換算
 *
 * 用途：HR 在規劃「員工選補休」時，預估補休時數與「補休過期未休應發工資」。
 *
 * @param {Object} params
 * @param {number} params.monthlySalary
 * @param {number} params.overtimeHours          當日延長工作時數
 * @param {'weekday'|'restday'} params.overtimeType 加班發生於平日延長 / 休息日
 * @param {boolean} params.takeCompensatoryLeave 是否選補休（勞工意願 + 雇主同意，§32-1 I）
 * @param {boolean} [params.expiredUnused]       補休期限屆期或契約終止仍未補休
 * @returns {import('./trace.js').TracedResult}
 *           result = 補休時數（選補休且未過期）或應發工資（過期 / 未選補休）
 */
export function calcCompensatoryLeave(params) {
  const {
    monthlySalary,
    overtimeHours,
    overtimeType,
    takeCompensatoryLeave,
    expiredUnused,
  } = params;
  if (typeof monthlySalary !== 'number' || monthlySalary <= 0) {
    throw new Error('calcCompensatoryLeave: invalid monthlySalary');
  }
  if (typeof overtimeHours !== 'number' || overtimeHours < 0) {
    throw new Error('calcCompensatoryLeave: invalid overtimeHours');
  }

  const trace = createTrace();
  const hourly = monthlySalary / 30 / 8;
  addStep(trace, {
    label: '時薪換算',
    formula: 'monthlySalary / 30 / 8',
    inputs: { monthlySalary },
    value: hourly,
  });
  addLaw(trace, {
    article: '勞基法§32-1',
    description:
      '雇主延長工作時間 / 休息日工作後，依勞工意願選擇補休經雇主同意者，依工作時數計算補休時數（一比一）；補休期限屆期或契約終止未補休者，依延長工作當日工資計算標準發給工資。',
  });

  if (takeCompensatoryLeave && !expiredUnused) {
    // 選補休、未過期 → 1:1 換補休時數
    addStep(trace, {
      label: '補休時數（1:1 換）',
      formula: 'overtimeHours × 1',
      inputs: { overtimeHours },
      value: overtimeHours,
      note: '§32-1 I：依工作時數計算補休時數（不適用加班費倍率）',
    });
    setSummary(
      trace,
      `選補休：${overtimeHours} 小時補休（1:1）；過期未休須回算當日加班費`,
    );
    return { result: overtimeHours, trace };
  }

  // 未選補休（直接發加班費），或選補休但過期 → 依當日加班費標準
  const hourly_h1 = LEGAL_FLOOR.overtime_rate_weekday_h1_h2;
  const hourly_h3 = LEGAL_FLOOR.overtime_rate_weekday_h3_h4;
  let pay = 0;
  if (overtimeType === 'weekday') {
    const h1 = Math.min(overtimeHours, 2);
    const h2 = Math.max(Math.min(overtimeHours - 2, 2), 0);
    pay = h1 * hourly * hourly_h1 + h2 * hourly * hourly_h3;
    addStep(trace, {
      label: '應發加班費（平日）',
      formula: 'h1×4/3 + h2×5/3',
      inputs: { h1, h2, hourly },
      value: pay,
      note: expiredUnused
        ? '§32-1 II：補休期限屆期未補休 → 依延長工作當日工資計算標準發給'
        : '勞工未選補休 → 直接依§24 發給加班費',
    });
  } else {
    // restday
    const r1 = Math.min(overtimeHours, 2);
    const r2 = Math.max(Math.min(overtimeHours - 2, 6), 0);
    const r3 = Math.max(overtimeHours - 8, 0);
    pay =
      r1 * hourly * LEGAL_FLOOR.overtime_rate_restday_h1_h2 +
      r2 * hourly * LEGAL_FLOOR.overtime_rate_restday_h2_h8 +
      r3 * hourly * LEGAL_FLOOR.overtime_rate_restday_h2_h8;
    addStep(trace, {
      label: '應發加班費（休息日）',
      formula: 'r1×4/3 + r2×5/3 + r3×5/3',
      inputs: { r1, r2, r3, hourly },
      value: pay,
      note: expiredUnused
        ? '§32-1 II：補休期限屆期未補休 → 依延長工作當日工資計算標準發給'
        : '§24 II 休息日階梯',
    });
  }
  setSummary(
    trace,
    expiredUnused
      ? `補休過期 ${overtimeHours} 小時 → 依當日加班費發 ${Math.round(pay).toLocaleString()} 元`
      : `未選補休 → 直接發加班費 ${Math.round(pay).toLocaleString()} 元`,
  );
  return { result: pay, trace };
}
