/**
 * attendance-anomaly.js — 出勤異常偵測（HR Pro wedge 2026-05-13）
 *
 * 與 schedule-checker.js 的分工：
 *   - schedule-checker：純看「排班表」是否合規（事前）— §32 II 上限、§34 II 換班間隔、
 *     §36 七休一、§38 特休額度
 *   - attendance-anomaly：比對「實際打卡」vs「排定 shift」，標出實際出勤的偏差與違規（事後）
 *     並接 overtime-calculator 算出建議補發金額。
 *
 * ## 偵測項目
 *  - A-OT-UNFILED   加班未申請（actual > scheduled + tolerance）
 *  - A-LATE         遲到（actual_in > scheduled_in + threshold）
 *  - A-EARLY-LEAVE  早退（actual_out < scheduled_out - threshold）
 *  - A-R34          連續工作違 §34 II（兩班相隔 < 11hr）
 *  - A-R36          七休一違 §36 I（連 7 日無例假）
 *
 * ## 法源（law.moj.gov.tw verify 2026-05-13）
 *  - §24：加班費（透過 overtime-calculator 計算，附條號）
 *  - §32 II：一日延時 + 正常 ≤ 12hr；月延時 ≤ 46hr（協商 54hr）
 *  - §34 II：輪班換班至少連續 11 小時休息
 *  - §36 I：每七日二日休（一例假、一休息日）
 *
 * @module attendance-anomaly
 */

import { calcOvertimePay, monthlyToHourly } from './overtime-calculator.js';

const LAW_MOJ = (flno) =>
  `https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=N0030001&flno=${flno}`;

/**
 * @typedef {Object} ScheduledShift
 * @property {string} employeeId
 * @property {string} date          YYYY-MM-DD
 * @property {string} startTime     HH:mm
 * @property {string} endTime       HH:mm
 * @property {number} [breakMinutes]
 * @property {'weekday'|'restday'|'mandatory_leave'|'statutory_holiday'} [shiftKind]
 *           班別（不填預設 weekday）
 */

/**
 * @typedef {Object} ActualPunch
 * @property {string} employeeId
 * @property {string} date          YYYY-MM-DD
 * @property {string} actualIn      HH:mm 實際打卡進
 * @property {string} actualOut     HH:mm 實際打卡出（HH:mm < actualIn 視為跨日）
 * @property {number} [breakMinutes]
 */

/**
 * @typedef {Object} AnomalyOptions
 * @property {number} [lateThresholdMinutes]      遲到容忍（預設 5）
 * @property {number} [earlyLeaveThresholdMinutes] 早退容忍（預設 5）
 * @property {number} [otToleranceMinutes]         加班未申請容忍（預設 15）
 * @property {number} [hourlyWage]                 平日時薪（接 overtime-calculator 用）
 * @property {number} [monthlySalary]              月薪（如未提供 hourlyWage，自動 /30/8）
 */

/**
 * @typedef {Object} Anomaly
 * @property {string} anomalyId
 * @property {'A-OT-UNFILED'|'A-LATE'|'A-EARLY-LEAVE'|'A-R34'|'A-R36'} ruleId
 * @property {'violation'|'warning'|'info'} severity
 * @property {string} employeeId
 * @property {string[]} affectedDates
 * @property {string} message
 * @property {string} statuteRef
 * @property {string} lawMojUrl
 * @property {Object} [details]                   各 rule 自帶細節
 * @property {Object} [suggestedOvertimePay]      接 overtime-calculator 的試算（若適用）
 */

// ─── helpers ──────────────────────────────────────────────────────

function pad(n) {
  return String(n).padStart(2, '0');
}

function timeToMs(date, hhmm) {
  const [h, m] = hhmm.split(':').map(Number);
  return new Date(`${date}T${pad(h)}:${pad(m)}:00`).getTime();
}

/**
 * 計算一筆 shift 的 startMs/endMs/durationHours（跨日處理）
 * @param {{date:string, startTime:string, endTime:string, breakMinutes?:number}} s
 */
function interval(s) {
  const startMs = timeToMs(s.date, s.startTime);
  let endMs = timeToMs(s.date, s.endTime);
  if (endMs <= startMs) endMs += 24 * 3600 * 1000;
  const durationHours =
    (endMs - startMs) / 3600000 - (s.breakMinutes || 0) / 60;
  return { startMs, endMs, durationHours: Math.max(0, durationHours) };
}

function intervalFromPunch(p) {
  const startMs = timeToMs(p.date, p.actualIn);
  let endMs = timeToMs(p.date, p.actualOut);
  if (endMs <= startMs) endMs += 24 * 3600 * 1000;
  const durationHours =
    (endMs - startMs) / 3600000 - (p.breakMinutes || 0) / 60;
  return { startMs, endMs, durationHours: Math.max(0, durationHours) };
}

function addDays(dateStr, n) {
  const [y, m, d] = dateStr.split('-').map(Number);
  const dt = new Date(Date.UTC(y, m - 1, d));
  dt.setUTCDate(dt.getUTCDate() + n);
  return dt.toISOString().slice(0, 10);
}

/**
 * 取得對應的排定 shift（同員工同日）
 * @param {ScheduledShift[]} shifts
 * @param {string} employeeId
 * @param {string} date
 */
function findScheduled(shifts, employeeId, date) {
  return shifts.find((s) => s.employeeId === employeeId && s.date === date);
}

// ─── 偵測規則 ─────────────────────────────────────────────────────

/**
 * A-OT-UNFILED：實際工時 > 排定工時 + tolerance → 加班未申請
 * @param {ActualPunch} punch
 * @param {ScheduledShift} sched
 * @param {AnomalyOptions} opts
 * @returns {Anomaly | null}
 */
function detectUnfiledOvertime(punch, sched, opts) {
  const tolMin = opts.otToleranceMinutes ?? 15;
  const actual = intervalFromPunch(punch);
  const scheduled = interval(sched);
  const diffHours = actual.durationHours - scheduled.durationHours;
  if (diffHours <= tolMin / 60 + 1e-9) return null;

  const extraHours = Math.round(diffHours * 100) / 100;
  const shiftKind = sched.shiftKind || 'weekday';

  /** @type {Anomaly} */
  const anomaly = {
    anomalyId: `A-OT-UNFILED-${punch.employeeId}-${punch.date}`,
    ruleId: 'A-OT-UNFILED',
    severity: 'warning',
    employeeId: punch.employeeId,
    affectedDates: [punch.date],
    statuteRef: '勞基法 §24（未申請加班，仍應給付加班費）',
    lawMojUrl: LAW_MOJ(24),
    message: `${punch.date} 實際工時 ${actual.durationHours.toFixed(2)}hr 超過排定 ${scheduled.durationHours.toFixed(2)}hr 約 ${extraHours}hr，疑為未申請加班。`,
    details: {
      scheduledHours: Math.round(scheduled.durationHours * 100) / 100,
      actualHours: Math.round(actual.durationHours * 100) / 100,
      extraHours,
    },
  };

  // 若有時薪資訊，接 overtime-calculator
  const hourlyWage =
    opts.hourlyWage ??
    (opts.monthlySalary != null
      ? monthlyToHourly(opts.monthlySalary)
      : undefined);
  if (hourlyWage != null) {
    anomaly.suggestedOvertimePay = calcOvertimePay({
      shiftKind,
      overtimeHours: extraHours,
      hourlyWage,
    });
  }
  return anomaly;
}

/**
 * A-LATE：actual_in 晚於 scheduled startTime + threshold
 * @returns {Anomaly | null}
 */
function detectLate(punch, sched, opts) {
  const thresholdMin = opts.lateThresholdMinutes ?? 5;
  const schedStart = timeToMs(sched.date, sched.startTime);
  const actStart = timeToMs(punch.date, punch.actualIn);
  const lateMin = (actStart - schedStart) / 60000;
  if (lateMin <= thresholdMin + 1e-9) return null;
  return {
    anomalyId: `A-LATE-${punch.employeeId}-${punch.date}`,
    ruleId: 'A-LATE',
    severity: 'info',
    employeeId: punch.employeeId,
    affectedDates: [punch.date],
    statuteRef: '出勤管理（非勞基法直接違規；惟雇主不得逕扣全勤獎金以外工資）',
    lawMojUrl: LAW_MOJ(22),
    message: `${punch.date} 遲到 ${Math.round(lateMin)} 分鐘（排定 ${sched.startTime}，實際 ${punch.actualIn}）。`,
    details: { lateMinutes: Math.round(lateMin) },
  };
}

/**
 * A-EARLY-LEAVE：actual_out 早於 scheduled endTime - threshold
 * @returns {Anomaly | null}
 */
function detectEarlyLeave(punch, sched, opts) {
  const thresholdMin = opts.earlyLeaveThresholdMinutes ?? 5;
  const schedEndOrig = timeToMs(sched.date, sched.endTime);
  const schedStart = timeToMs(sched.date, sched.startTime);
  let schedEnd = schedEndOrig;
  if (schedEnd <= schedStart) schedEnd += 24 * 3600 * 1000;

  const actStartOrig = timeToMs(punch.date, punch.actualIn);
  let actEnd = timeToMs(punch.date, punch.actualOut);
  if (actEnd <= actStartOrig) actEnd += 24 * 3600 * 1000;

  const earlyMin = (schedEnd - actEnd) / 60000;
  if (earlyMin <= thresholdMin + 1e-9) return null;
  return {
    anomalyId: `A-EARLY-LEAVE-${punch.employeeId}-${punch.date}`,
    ruleId: 'A-EARLY-LEAVE',
    severity: 'info',
    employeeId: punch.employeeId,
    affectedDates: [punch.date],
    statuteRef: '出勤管理（同 A-LATE 說明）',
    lawMojUrl: LAW_MOJ(22),
    message: `${punch.date} 早退 ${Math.round(earlyMin)} 分鐘（排定 ${sched.endTime}，實際 ${punch.actualOut}）。`,
    details: { earlyMinutes: Math.round(earlyMin) },
  };
}

/**
 * A-R34：兩相鄰班之間休息 < 11hr（§34 II）
 *
 * 比對「實際下班 ms → 次班實際上班 ms」差距；不分日，跨日 punch 已在 intervalFromPunch 處理。
 * @param {ActualPunch[]} punches
 * @returns {Anomaly[]}
 */
function detectR34(punches) {
  const sorted = [...punches].sort((a, b) => {
    if (a.employeeId !== b.employeeId)
      return a.employeeId < b.employeeId ? -1 : 1;
    return a.date < b.date ? -1 : 1;
  });
  /** @type {Anomaly[]} */
  const out = [];
  for (let i = 1; i < sorted.length; i++) {
    const prev = sorted[i - 1];
    const cur = sorted[i];
    if (prev.employeeId !== cur.employeeId) continue;
    const prevEnd = intervalFromPunch(prev).endMs;
    const curStart = timeToMs(cur.date, cur.actualIn);
    const gapHr = (curStart - prevEnd) / 3600000;
    if (gapHr < 11 - 1e-9 && gapHr >= 0) {
      out.push({
        anomalyId: `A-R34-${cur.employeeId}-${cur.date}`,
        ruleId: 'A-R34',
        severity: 'violation',
        employeeId: cur.employeeId,
        affectedDates: [prev.date, cur.date],
        statuteRef: '勞基法 §34 II（輪班換班至少連續 11 小時休息）',
        lawMojUrl: LAW_MOJ(34),
        message: `${prev.date} 下班至 ${cur.date} 上班僅間隔 ${gapHr.toFixed(2)} 小時，違 §34 II（11 小時）。`,
        details: { gapHours: Math.round(gapHr * 100) / 100 },
      });
    }
  }
  return out;
}

/**
 * A-R36：滾動 7 日視窗內若無任一天為「例假」（無打卡 + 排定為 mandatory_leave 或當日無 shift）→ 違 §36
 *
 * minimal viable：以「實際 punch 連續 7 日均有上班」為違規條件（保守認定）。
 * @param {ActualPunch[]} punches
 * @returns {Anomaly[]}
 */
function detectR36(punches) {
  const byEmp = new Map();
  for (const p of punches) {
    if (!byEmp.has(p.employeeId)) byEmp.set(p.employeeId, new Set());
    byEmp.get(p.employeeId).add(p.date);
  }
  /** @type {Anomaly[]} */
  const out = [];
  for (const [emp, dateSet] of byEmp) {
    const sortedDates = [...dateSet].sort();
    if (sortedDates.length < 7) continue;
    for (let i = 0; i <= sortedDates.length - 7; i++) {
      const window = [];
      for (let j = 0; j < 7; j++) {
        window.push(addDays(sortedDates[i], j));
      }
      const allWorked = window.every((d) => dateSet.has(d));
      if (allWorked) {
        out.push({
          anomalyId: `A-R36-${emp}-${window[0]}`,
          ruleId: 'A-R36',
          severity: 'violation',
          employeeId: emp,
          affectedDates: window,
          statuteRef: '勞基法 §36 I（每七日二日休：一例假、一休息日）',
          lawMojUrl: LAW_MOJ(36),
          message: `${window[0]} ~ ${window[6]} 連續 7 日皆有出勤打卡，違 §36 I 七休一。`,
          details: { window },
        });
      }
    }
  }
  return out;
}

// ─── 主入口 ───────────────────────────────────────────────────────

/**
 * 偵測出勤異常
 * @param {{ scheduled: ScheduledShift[], actual: ActualPunch[] }} input
 * @param {AnomalyOptions} [options]
 * @returns {Anomaly[]}
 */
export function detectAttendanceAnomalies(input, options) {
  const opts = options || {};
  const { scheduled, actual } = input;

  /** @type {Anomaly[]} */
  const anomalies = [];

  // per-punch 比對（需找到對應 scheduled）
  for (const punch of actual) {
    const sched = findScheduled(scheduled, punch.employeeId, punch.date);
    if (!sched) continue; // 無排定不比對；可後續加 A-NO-SCHEDULE rule
    const ot = detectUnfiledOvertime(punch, sched, opts);
    if (ot) anomalies.push(ot);
    const late = detectLate(punch, sched, opts);
    if (late) anomalies.push(late);
    const early = detectEarlyLeave(punch, sched, opts);
    if (early) anomalies.push(early);
  }

  // 跨班規則
  anomalies.push(...detectR34(actual));
  anomalies.push(...detectR36(actual));

  return anomalies;
}

export const ANOMALY_RULES = {
  'A-OT-UNFILED': { statute: '勞基法 §24', severity: 'warning' },
  'A-LATE': { statute: '出勤管理', severity: 'info' },
  'A-EARLY-LEAVE': { statute: '出勤管理', severity: 'info' },
  'A-R34': { statute: '勞基法 §34 II', severity: 'violation' },
  'A-R36': { statute: '勞基法 §36 I', severity: 'violation' },
};
