/**
 * min-wage-compliance.js — 基本工資合規檢查（§21 + §79 罰則）
 *
 * 抽 apps/etp/public/hr-tools/min-wage.html 內 calculate() 進 core-labor。
 *
 * ## 法源（每條皆已於 https://law.moj.gov.tw 全國法規資料庫驗證）
 *
 * - 勞基法§21 I（基本工資底線）
 *     工資由勞雇雙方議定之。但不得低於基本工資。
 *
 * - 勞基法§21 II（基本工資審議）
 *     基本工資由中央主管機關設基本工資審議會擬訂後，報請行政院核定之。
 *
 * - 勞基法§79 I 1（違反基本工資罰則）
 *     違反第二十一條第一項⋯⋯規定者，處新臺幣二萬元以上一百萬元以下罰鍰。
 *
 * ## 計薪基礎判斷（行政實務見解）
 *
 *   計入：底薪、職務加給、技術加給等「經常性給與」
 *   有限計入：伙食津貼以財政部公告免納所得稅標準為上限（目前 2,400 元 / 月）
 *   不計入：全勤獎金、加班費、年終獎金、紅利等非經常性給與或法定加給
 *
 * 雇主不得藉由分項規避基本工資規定。
 *
 * ## 基本工資金額來源
 *
 * 直接複用 hourly.js 的 MIN_HOURLY_WAGE_VERSIONS（最新者為 LATEST_HOURLY_VERSION）：
 *   115 年 (2026/1/1+)：月薪 29,500 / 時薪 196
 *   勞動部 114.9.4 公告
 *
 * @module min-wage-compliance
 */

import { createTrace, addStep, addLaw, setSummary } from './trace.js';
import { LATEST_HOURLY_VERSION } from './hourly.js';

/** 伙食津貼可計入基本工資的上限（財政部公告免納所得稅標準） */
export const MEAL_ALLOWANCE_CAP = 2400;

/** §79 I 1 罰鍰下限 */
export const PENALTY_MIN = 20_000;

/** §79 I 1 罰鍰上限 */
export const PENALTY_MAX = 1_000_000;

function roundCurrency(n) {
  return Math.round(n);
}

/**
 * 月薪制合規檢查
 *
 * 計薪基礎 = baseSalary + min(mealAllowance, 2400)
 * 全勤獎金、加班費 不計入
 *
 * @param {object} params
 * @param {number} params.baseSalary 底薪
 * @param {number} [params.mealAllowance=0] 伙食津貼
 * @param {number} [params.fullAttendanceBonus=0] 全勤獎金（不計入，僅展示）
 * @param {number} [params.overtimePay=0] 加班費（不計入，僅展示）
 * @param {number} [params.weeklyHours=40] 每週工時，給隱含時薪 cross-check
 * @param {number} [params.minMonthly] override 法定月薪；預設取最新公告值
 * @param {number} [params.minHourly] override 法定時薪；預設取最新公告值
 * @returns {{
 *   payType: 'monthly',
 *   countableWage: number,
 *   countableBreakdown: { baseSalary: number, mealCountable: number, mealExcluded: number, fullAttendanceBonus: number, overtimePay: number },
 *   gap: number,
 *   level: 'pass'|'fail',
 *   minMonthly: number,
 *   impliedHourly: number,
 *   impliedHourlyPasses: boolean,
 *   trace: object
 * }}
 */
export function checkMonthlyMinWage({
  baseSalary,
  mealAllowance = 0,
  fullAttendanceBonus = 0,
  overtimePay = 0,
  weeklyHours = 40,
  minMonthly = LATEST_HOURLY_VERSION.monthly,
  minHourly = LATEST_HOURLY_VERSION.hourly,
}) {
  if (!Number.isFinite(baseSalary) || baseSalary < 0) {
    throw new Error('checkMonthlyMinWage: baseSalary 必須為 ≥ 0 的數字');
  }
  if (!Number.isFinite(mealAllowance) || mealAllowance < 0) {
    throw new Error('checkMonthlyMinWage: mealAllowance 必須為 ≥ 0 的數字');
  }
  if (!Number.isFinite(weeklyHours) || weeklyHours <= 0) {
    throw new Error('checkMonthlyMinWage: weeklyHours 必須為 > 0 的數字');
  }

  const mealCountable = Math.min(mealAllowance, MEAL_ALLOWANCE_CAP);
  const mealExcluded = Math.max(0, mealAllowance - MEAL_ALLOWANCE_CAP);
  const countableWage = baseSalary + mealCountable;
  const gap = minMonthly - countableWage;
  const level = countableWage >= minMonthly ? 'pass' : 'fail';

  // 隱含時薪 cross-check：底薪 / (52/12) / weeklyHours
  const monthsFactor = 52 / 12;
  const impliedHourly = baseSalary / monthsFactor / weeklyHours;
  const impliedHourlyPasses = impliedHourly >= minHourly;

  const trace = createTrace();
  addStep(trace, {
    label: '計薪基礎',
    formula: 'baseSalary + min(mealAllowance, 2400)',
    inputs: { baseSalary, mealAllowance, mealCountable, mealCap: MEAL_ALLOWANCE_CAP },
    value: countableWage,
    note: mealExcluded > 0
      ? `伙食津貼超出 2,400 的 ${mealExcluded} 元不計入比較基礎`
      : '全勤獎金、加班費屬非經常性 / 法定加給，不計入',
  });
  addStep(trace, {
    label: '基本工資比對',
    formula: 'countable ≥ minMonthly ?',
    inputs: { countableWage, minMonthly },
    value: gap,
    note:
      level === 'pass'
        ? `多 ${Math.abs(gap).toLocaleString()} 元，合規`
        : `差 ${gap.toLocaleString()} 元 / 月（年差 ${(gap * 12).toLocaleString()} 元），違反§21 I`,
  });
  addStep(trace, {
    label: '隱含時薪 cross-check',
    formula: 'baseSalary / (52/12) / weeklyHours',
    inputs: { baseSalary, monthsFactor: Number(monthsFactor.toFixed(4)), weeklyHours, minHourly },
    value: Number(impliedHourly.toFixed(2)),
    note: impliedHourlyPasses
      ? '隱含時薪 ≥ 法定時薪，合規'
      : '隱含時薪 < 法定時薪，雇主不得藉時 / 月薪換算規避（勞動部函釋）',
  });
  addLaw(trace, {
    article: '勞基法§21 I',
    description: '工資由勞雇雙方議定之，但不得低於基本工資。',
  });
  if (level === 'fail') {
    addLaw(trace, {
      article: '勞基法§79 I 1',
      description: `違反§21 I 處新臺幣 ${PENALTY_MIN.toLocaleString()} 元以上 ${PENALTY_MAX.toLocaleString()} 元以下罰鍰；雇主並應補足差額。`,
    });
  }
  setSummary(
    trace,
    level === 'pass'
      ? `計薪基礎 ${countableWage.toLocaleString()} 元 ≥ 基本工資月薪 ${minMonthly.toLocaleString()} 元，合規。`
      : `計薪基礎 ${countableWage.toLocaleString()} 元 < 基本工資 ${minMonthly.toLocaleString()} 元，月差 ${gap.toLocaleString()} 元，違反§21 I（§79 I 1 罰 2 萬 ～ 100 萬元）。`,
  );

  return {
    payType: 'monthly',
    countableWage: roundCurrency(countableWage),
    countableBreakdown: {
      baseSalary,
      mealCountable,
      mealExcluded,
      fullAttendanceBonus,
      overtimePay,
    },
    gap: roundCurrency(gap),
    level,
    minMonthly,
    impliedHourly: Number(impliedHourly.toFixed(2)),
    impliedHourlyPasses,
    trace,
  };
}

/**
 * 時薪制合規檢查
 *
 * @param {object} params
 * @param {number} params.hourlyWage 時薪
 * @param {number} [params.weeklyHours=40] 每週工時，產隱含月薪
 * @param {number} [params.minHourly] override 法定時薪
 * @returns {{
 *   payType: 'hourly',
 *   hourlyWage: number,
 *   gap: number,
 *   level: 'pass'|'fail',
 *   minHourly: number,
 *   impliedMonthly: number,
 *   trace: object
 * }}
 */
export function checkHourlyMinWage({
  hourlyWage,
  weeklyHours = 40,
  minHourly = LATEST_HOURLY_VERSION.hourly,
}) {
  if (!Number.isFinite(hourlyWage) || hourlyWage < 0) {
    throw new Error('checkHourlyMinWage: hourlyWage 必須為 ≥ 0 的數字');
  }
  if (!Number.isFinite(weeklyHours) || weeklyHours <= 0) {
    throw new Error('checkHourlyMinWage: weeklyHours 必須為 > 0 的數字');
  }
  const gap = hourlyWage - minHourly;
  const level = hourlyWage >= minHourly ? 'pass' : 'fail';
  const monthsFactor = 52 / 12;
  const impliedMonthly = hourlyWage * weeklyHours * monthsFactor;

  const trace = createTrace();
  addStep(trace, {
    label: '時薪比對',
    formula: 'hourlyWage ≥ minHourly ?',
    inputs: { hourlyWage, minHourly },
    value: gap,
    note: level === 'pass' ? '時薪 ≥ 法定下限，合規' : `差 ${Math.abs(gap)} 元 / 小時`,
  });
  addStep(trace, {
    label: '隱含月薪（參考）',
    formula: 'hourlyWage × weeklyHours × (52/12)',
    inputs: { hourlyWage, weeklyHours, monthsFactor: Number(monthsFactor.toFixed(4)) },
    value: roundCurrency(impliedMonthly),
    note: '勞動部函釋：時薪 / 月薪基本工資各自獨立，不得換算規避',
  });
  addLaw(trace, {
    article: '勞基法§21 I',
    description: '工資由勞雇雙方議定之，但不得低於基本工資。',
  });
  if (level === 'fail') {
    addLaw(trace, {
      article: '勞基法§79 I 1',
      description: `違反§21 I 處新臺幣 ${PENALTY_MIN.toLocaleString()} 元以上 ${PENALTY_MAX.toLocaleString()} 元以下罰鍰。`,
    });
  }
  setSummary(
    trace,
    level === 'pass'
      ? `時薪 ${hourlyWage} 元 ≥ 基本時薪 ${minHourly} 元，合規。`
      : `時薪 ${hourlyWage} 元 < 基本時薪 ${minHourly} 元（差 ${Math.abs(gap)} 元 / hr），違反§21 I。`,
  );

  return {
    payType: 'hourly',
    hourlyWage,
    gap: Number(gap.toFixed(2)),
    level,
    minHourly,
    impliedMonthly: roundCurrency(impliedMonthly),
    trace,
  };
}
