/**
 * 取得近年勞檢命中率／檢查違規率（per 條文）
 *
 * 勞動部雖每年公告「勞動條件檢查結果統計」，但個別條文違反率口徑不一、且公開資料
 * 多為大類（工資 / 工時 / 假別）而非單一條號。本函式採保守策略：
 *   - 一律回 null + reason
 *   - 由 UI 顯示「資料待勞動部公告補上」而非自創排名
 *
 * @param {string} articleNumber  例 '§22' / '§24' / 'lba-22-fullwage'
 * @returns {{ rate: number | null, reason: string, sourceUrl: string }}
 */
export function getInspectionFrequency(articleNumber) {
  return {
    rate: null,
    reason:
      `勞動部「勞動條件檢查結果統計」未逐條公告 ${articleNumber} 違反率；資料待勞動部統計處 117 年公告補上`,
    sourceUrl: 'https://www.mol.gov.tw/1607/1632/1633/',
  };
}

/**
 * 依違反條文 id 找對應 LABOR_PENALTIES 項目
 * @param {string} id
 * @returns {LaborPenalty | undefined}
 */
export function getPenaltyById(id) {
  return LABOR_PENALTIES.find((p) => p.id === id);
}

/**
 * 依被違反條文（例 '勞基法§22'）找對應 LABOR_PENALTIES 項目
 * @param {string} articleCited
 * @returns {LaborPenalty | undefined}
 */
export function getPenaltyByArticle(articleCited) {
  return LABOR_PENALTIES.find((p) => p.articleCited === articleCited);
}
