/**
 * service-charge.js — 餐飲服務費（小費）分配計算（traced）
 *
 * ## 為何存在
 * 餐飲業普遍向消費者收取一成（10%）服務費。「服務費」本質是消費者向餐廳的對價，
 * 但實務上餐廳會分配部分或全部給員工作為獎金 / 工資加項。
 *
 * ## 法源（已驗證）
 * - 勞基法§22 II「工資應全額直接給付勞工」+「不得克扣」原則
 * - 勞基法§2 (3)「工資」定義：勞工因工作而獲得之報酬
 * - **重要**：台灣法令未明定服務費「強制分配公式」；分配方式應於工作規則
 *   或勞動契約明訂（勞基法§70 工作規則應報請主管機關核備）
 *
 * ## 函釋
 * 勞動部就「服務費是否屬工資」歷有解釋，其性質依個案約定判斷：
 *   - 若約定「按月固定金額」或「依出勤狀況發給」 → 偏向工資
 *   - 若為「不確定盈餘分配」、「客戶任意給付」 → 偏向恩惠性給與
 * 確切函釋字號未取得驗證，本檔留 TODO 不寫死。
 *
 * ## 設計
 * 不假設特定分配模式；提供 3 種常見方案 + 自訂權重，計算結果僅供管理層試算。
 */

import { createTrace, addStep, addLaw, setSummary } from './trace.js';

/**
 * @typedef {Object} EmployeeShare
 * @property {string} employeeId
 * @property {string} [name]
 * @property {number} [weight]   - 權重（method='weighted' 時必填）
 * @property {string} [role]     - 職務（method='role_based' 時對 roleWeights 查表）
 * @property {number} [hours]    - 工時（用 method='hours' 時依工時比例分配）
 */

/**
 * @typedef {Object} ServiceChargeInput
 * @property {number} totalCollected           — 本期收取的服務費總額
 * @property {ReadonlyArray<EmployeeShare>} employeeShares
 * @property {'equal'|'weighted'|'role_based'|'hours'} method
 * @property {Record<string, number>} [roleWeights]   - method='role_based' 時必填
 * @property {number} [employerRetention]      - 雇主自留比例（0~1，預設 0）
 */

/**
 * @typedef {Object} DistributionLine
 * @property {string} employeeId
 * @property {string} [name]
 * @property {number} amount
 * @property {number} sharePct   — 占可分配總額的百分比（0~100）
 * @property {string} [reason]
 */

/**
 * @typedef {Object} ServiceChargeResult
 * @property {number} totalCollected
 * @property {number} employerRetained
 * @property {number} distributed
 * @property {ReadonlyArray<DistributionLine>} lines
 */

/**
 * 服務費分配試算
 *
 * @param {ServiceChargeInput} params
 * @returns {{ result: ServiceChargeResult, trace: import('./trace.js').CalcTrace }}
 */
export function distributeServiceCharge(params) {
  const {
    totalCollected,
    employeeShares,
    method,
    roleWeights,
    employerRetention = 0,
  } = params;

  if (typeof totalCollected !== 'number' || totalCollected < 0) {
    throw new Error('distributeServiceCharge: invalid totalCollected');
  }
  if (!Array.isArray(employeeShares) || employeeShares.length === 0) {
    throw new Error('distributeServiceCharge: employeeShares required');
  }
  if (employerRetention < 0 || employerRetention > 1) {
    throw new Error('distributeServiceCharge: employerRetention must be 0~1');
  }

  const trace = createTrace();

  addLaw(trace, {
    article: '勞基法§22 II',
    description:
      '工資應全額直接給付勞工；不得預扣工資作為違約金或賠償費用。本系統採此條為服務費分配後不得克扣之上位原則。',
  });
  addLaw(trace, {
    article: '勞基法§2 (3)',
    description:
      '工資指勞工因工作而獲得之報酬。服務費是否計入工資，依個案約定（持續性、勞務對價性）認定。',
  });
  addLaw(trace, {
    article: '勞基法§70',
    description:
      '雇主僱用勞工人數在三十人以上者，應依其事業性質訂立工作規則並報請主管機關核備。服務費分配方式建議於工作規則或勞動契約明訂。',
  });

  // 重要備註：無法定強制公式
  addStep(trace, {
    label: '法源備註',
    formula: 'n/a',
    value: 0,
    note:
      '⚠️ 台灣法令未明定服務費強制分配公式；本系統試算僅供管理層參考。' +
      '分配方式必須於工作規則或勞動契約明訂，並依§22 II 全額直接給付，不得克扣。',
  });

  // ── 雇主自留 ──
  const employerRetained = totalCollected * employerRetention;
  const distributable = totalCollected - employerRetained;

  addStep(trace, {
    label: '可分配總額',
    formula: 'totalCollected × (1 - employerRetention)',
    inputs: { totalCollected, employerRetention },
    value: distributable,
    note:
      employerRetention > 0
        ? `雇主自留 ${(employerRetention * 100).toFixed(1)}% = ${Math.round(employerRetained).toLocaleString()} 元（須有工作規則明訂）`
        : '雇主未自留，全額分配給員工',
  });

  /** @type {DistributionLine[]} */
  let lines = [];

  if (method === 'equal') {
    // 平均分配
    const per = distributable / employeeShares.length;
    lines = employeeShares.map((e) => ({
      employeeId: e.employeeId,
      name: e.name,
      amount: per,
      sharePct: 100 / employeeShares.length,
      reason: '平均分配',
    }));
    addStep(trace, {
      label: '分配方式：平均',
      formula: 'distributable / employeeCount',
      inputs: { distributable, employeeCount: employeeShares.length },
      value: per,
    });
  } else if (method === 'weighted') {
    // 自訂權重
    const totalWeight = employeeShares.reduce(
      (s, e) => s + (typeof e.weight === 'number' && e.weight > 0 ? e.weight : 0),
      0,
    );
    if (totalWeight <= 0) {
      throw new Error('distributeServiceCharge: weighted method requires positive weight');
    }
    lines = employeeShares.map((e) => {
      const w = typeof e.weight === 'number' && e.weight > 0 ? e.weight : 0;
      const amount = (distributable * w) / totalWeight;
      const pct = (w / totalWeight) * 100;
      return {
        employeeId: e.employeeId,
        name: e.name,
        amount,
        sharePct: pct,
        reason: `權重 ${w}（占 ${pct.toFixed(1)}%）`,
      };
    });
    addStep(trace, {
      label: '分配方式：自訂權重',
      formula: 'distributable × weight / totalWeight',
      inputs: { distributable, totalWeight },
      value: distributable,
    });
  } else if (method === 'role_based') {
    if (!roleWeights || typeof roleWeights !== 'object') {
      throw new Error('distributeServiceCharge: role_based requires roleWeights');
    }
    const weights = employeeShares.map((e) => {
      const w = e.role && typeof roleWeights[e.role] === 'number' ? roleWeights[e.role] : 0;
      return { e, w };
    });
    const totalWeight = weights.reduce((s, x) => s + x.w, 0);
    if (totalWeight <= 0) {
      throw new Error('distributeServiceCharge: role weights produce zero total');
    }
    lines = weights.map(({ e, w }) => {
      const amount = (distributable * w) / totalWeight;
      const pct = (w / totalWeight) * 100;
      return {
        employeeId: e.employeeId,
        name: e.name,
        amount,
        sharePct: pct,
        reason: `${e.role ?? ''} 權重 ${w}（占 ${pct.toFixed(1)}%）`,
      };
    });
    addStep(trace, {
      label: '分配方式：依職務權重',
      formula: 'distributable × roleWeight / totalRoleWeight',
      inputs: { distributable, totalWeight },
      value: distributable,
    });
  } else if (method === 'hours') {
    const totalHours = employeeShares.reduce(
      (s, e) => s + (typeof e.hours === 'number' && e.hours > 0 ? e.hours : 0),
      0,
    );
    if (totalHours <= 0) {
      throw new Error('distributeServiceCharge: hours method requires positive hours');
    }
    lines = employeeShares.map((e) => {
      const h = typeof e.hours === 'number' && e.hours > 0 ? e.hours : 0;
      const amount = (distributable * h) / totalHours;
      const pct = (h / totalHours) * 100;
      return {
        employeeId: e.employeeId,
        name: e.name,
        amount,
        sharePct: pct,
        reason: `工時 ${h}h（占 ${pct.toFixed(1)}%）`,
      };
    });
    addStep(trace, {
      label: '分配方式：依工時比例',
      formula: 'distributable × hours / totalHours',
      inputs: { distributable, totalHours },
      value: distributable,
    });
  } else {
    throw new Error(`distributeServiceCharge: unknown method=${method}`);
  }

  // 收尾
  const distributed = lines.reduce((s, l) => s + l.amount, 0);
  addStep(trace, {
    label: '分配完成',
    formula: 'sum(lines.amount)',
    value: distributed,
    note: `共 ${lines.length} 位員工，分配 ${Math.round(distributed).toLocaleString()} 元`,
  });

  setSummary(
    trace,
    `服務費 ${Math.round(totalCollected).toLocaleString()} 元（${method}）分配 ${lines.length} 人；` +
      `雇主自留 ${Math.round(employerRetained).toLocaleString()}、分配 ${Math.round(distributed).toLocaleString()} 元`,
  );

  return {
    result: {
      totalCollected,
      employerRetained,
      distributed,
      lines,
    },
    trace,
  };
}

/**
 * 預設職務權重模板（餐飲常見）— 雇主可依工作規則調整。
 * 數字僅為比例，非法定。
 */
export const DEFAULT_ROLE_WEIGHTS = Object.freeze({
  '主廚': 3,
  '副廚': 2,
  '廚師': 1.5,
  '外場主管': 2,
  '外場服務生': 1,
  '吧台': 1.2,
  '備餐': 1,
  '清潔': 0.8,
});
