/**
 * parental-leave.js — 育嬰留停津貼 + 產假薪資（traced）
 *
 * ## 法源（每條皆已於 https://law.moj.gov.tw 全國法規資料庫驗證）
 *
 * - 勞基法§50（產假）
 *     女工分娩前後，應停止工作，給予產假八星期；妊娠三個月以上流產者，應停止工作，
 *     給予產假四星期；妊娠二個月以上未滿三個月流產者，應停止工作，給予產假一星期；
 *     妊娠未滿二個月流產者，應停止工作，給予產假五日。
 *     前項女工受僱工作在六個月以上者，停止工作期間工資照給；未滿六個月者減半發給。
 *
 * - 性別平等工作法§15 I（產假，與勞基法§50 並行；產假以勞基法為準）
 *     雇主於女性受僱者分娩前後，應使其停止工作，給予產假八星期；妊娠三個月以上流產者，
 *     應使其停止工作，給予產假四星期⋯⋯
 *
 * - 性別平等工作法§16 I（育嬰留職停薪資格）
 *     受僱者任職滿六個月後，於每一子女滿三歲前，得申請育嬰留職停薪，期間至該子女滿
 *     三歲止，但不得逾二年。同時撫育子女二人以上者，其育嬰留職停薪期間應合併計算，
 *     最長以最幼子女受撫育二年為限。
 *
 * - 就業保險法§19-2 I（育嬰留停津貼）
 *     育嬰留職停薪津貼，以被保險人育嬰留職停薪之當月起前六個月平均月投保薪資百分之
 *     六十計算，於被保險人育嬰留職停薪期間，按月發給，每一子女合計最長發給六個月。
 *
 * - 行政院「育嬰留職停薪薪資補助要點」（110.7.1 施行）
 *     就業保險法§19-2 之育嬰留職停薪津貼發給期間，由勞動部加發其平均月投保薪資百分
 *     之二十之補助，與津貼合併發給，無須另行申請。
 *     ⇒ 實質給付 = 投保薪資 × 80% × 最長 6 個月
 *
 * ## 計算範圍
 *
 * 本檔提供三支函式：
 *   1. calcMaternityPay   — 產假薪資（勞基法§50；月薪 × 56/30，年資未滿 6 月減半）
 *   2. calcParentalAllowance — 育嬰留停津貼（就保§19-2 + 行政院補助）
 *   3. calcParentalLeavePackage — 上述兩支合計，附完整 trace
 *
 * 男性受僱者僅請領育嬰留停津貼（無產假，§15 為陪產檢及陪產假；交由
 * core-labor/leave.js 的 paternity/prenatal 路徑處理，本檔不重複實作）。
 *
 * @module parental-leave
 */

import { createTrace, addStep, addLaw, setSummary } from './trace.js';

/** 勞基法§50 八星期 = 56 日 */
export const MATERNITY_LEAVE_DAYS = 56;

/** 勞基法§50 年資 ≥ 6 個月給全薪、否則半薪 */
export const MATERNITY_FULL_PAY_TENURE_MONTHS = 6;

/** 就保§19-2 法定基本給付率 */
export const PARENTAL_ALLOWANCE_BASE_RATE = 0.6;

/** 行政院 110.7.1 起加發補助率 */
export const PARENTAL_ALLOWANCE_SUPPLEMENT_RATE = 0.2;

/** 補助要點施行日 */
export const PARENTAL_SUPPLEMENT_EFFECTIVE_FROM = '2021-07-01';

/** 每一子女合計最長月數（就保§19-2） */
export const PARENTAL_ALLOWANCE_MAX_MONTHS = 6;

/** 性平法§16 申請門檻：任職滿 6 個月 */
export const PARENTAL_LEAVE_MIN_TENURE_MONTHS = 6;

function clampMonths(months) {
  if (months == null || !Number.isFinite(months) || months < 0) return 0;
  return Math.min(months, PARENTAL_ALLOWANCE_MAX_MONTHS);
}

function roundCurrency(n) {
  return Math.round(n);
}

/**
 * 產假薪資（勞基法§50）
 *
 * - 月薪 × 56/30：八星期 56 日，月薪以 30 日為基期換算。
 * - 年資滿 6 個月 → 全薪；未滿 → 半薪。
 *
 * @param {object} params
 * @param {number} params.monthlySalary 月薪（NT$）
 * @param {number} params.tenureMonths 受僱年資（月）
 * @returns {{ amount: number, rate: number, days: number, trace: object }}
 */
export function calcMaternityPay({ monthlySalary, tenureMonths }) {
  if (!Number.isFinite(monthlySalary) || monthlySalary < 0) {
    throw new Error('calcMaternityPay: monthlySalary 必須為 ≥ 0 的數字');
  }
  if (!Number.isFinite(tenureMonths) || tenureMonths < 0) {
    throw new Error('calcMaternityPay: tenureMonths 必須為 ≥ 0 的數字');
  }
  const trace = createTrace();
  const isFullPay = tenureMonths >= MATERNITY_FULL_PAY_TENURE_MONTHS;
  const rate = isFullPay ? 1 : 0.5;
  const baseDays = MATERNITY_LEAVE_DAYS;
  const factor = baseDays / 30;
  const amount = roundCurrency(monthlySalary * factor * rate);

  addStep(trace, {
    label: '產假基期',
    formula: `${baseDays} 日 / 30 日`,
    inputs: { days: baseDays, monthDivisor: 30 },
    value: Number(factor.toFixed(4)),
    note: '勞基法§50 產假 56 日（八星期），以月薪 30 日為基期換算月數',
  });
  addStep(trace, {
    label: '給付率',
    inputs: { tenureMonths, threshold: MATERNITY_FULL_PAY_TENURE_MONTHS },
    value: rate,
    note: isFullPay
      ? '年資滿 6 個月 → 工資照給（全薪）'
      : '年資未滿 6 個月 → 減半發給（半薪）',
  });
  addStep(trace, {
    label: '產假薪資',
    formula: 'monthlySalary × (56/30) × rate',
    inputs: { monthlySalary, factor: Number(factor.toFixed(4)), rate },
    value: amount,
  });
  addLaw(trace, {
    article: '勞基法§50',
    description:
      '產假 56 日（八星期）；年資滿 6 個月者工資照給，未滿者減半發給。',
  });
  addLaw(trace, {
    article: '性別平等工作法§15 I',
    description: '產假 56 日，與勞基法§50 並行；產假給付以勞基法為準。',
  });
  setSummary(
    trace,
    `產假薪資 ${amount.toLocaleString()} 元（月薪 ${monthlySalary.toLocaleString()} × 56/30 × ${rate === 1 ? '100%' : '50%'}）`,
  );

  return { amount, rate, days: baseDays, trace };
}

/**
 * 育嬰留停津貼（就保§19-2 + 行政院 110/7/1 起加發 20%）
 *
 * - 法定基本：投保薪資 × 60% × 最長 6 個月
 * - 行政院補助：投保薪資 × 20%（與津貼合併發給）
 * - 預設 includeSupplement = true（110/7/1 後實務作法）
 *
 * @param {object} params
 * @param {number} params.insuredSalary 平均月投保薪資（NT$）
 * @param {number} [params.months=6] 申請月數，clamp 到 0–6
 * @param {boolean} [params.includeSupplement=true] 是否含 20% 補助
 * @returns {{ monthlyAllowance: number, totalAllowance: number, months: number, effectiveRate: number, trace: object }}
 */
export function calcParentalAllowance({
  insuredSalary,
  months = PARENTAL_ALLOWANCE_MAX_MONTHS,
  includeSupplement = true,
}) {
  if (!Number.isFinite(insuredSalary) || insuredSalary < 0) {
    throw new Error('calcParentalAllowance: insuredSalary 必須為 ≥ 0 的數字');
  }
  const safeMonths = clampMonths(months);
  const effectiveRate = includeSupplement
    ? PARENTAL_ALLOWANCE_BASE_RATE + PARENTAL_ALLOWANCE_SUPPLEMENT_RATE
    : PARENTAL_ALLOWANCE_BASE_RATE;
  const monthlyAllowance = roundCurrency(insuredSalary * effectiveRate);
  const totalAllowance = monthlyAllowance * safeMonths;

  const trace = createTrace();
  addStep(trace, {
    label: '基本津貼率',
    inputs: { rate: PARENTAL_ALLOWANCE_BASE_RATE },
    value: PARENTAL_ALLOWANCE_BASE_RATE,
    note: '就保§19-2：投保薪資 60%',
  });
  if (includeSupplement) {
    addStep(trace, {
      label: '加發補助率',
      inputs: { rate: PARENTAL_ALLOWANCE_SUPPLEMENT_RATE },
      value: PARENTAL_ALLOWANCE_SUPPLEMENT_RATE,
      note: `行政院 ${PARENTAL_SUPPLEMENT_EFFECTIVE_FROM} 起加發投保薪資 20% 補助`,
    });
  }
  addStep(trace, {
    label: '每月津貼',
    formula: includeSupplement
      ? 'insuredSalary × (60% + 20%)'
      : 'insuredSalary × 60%',
    inputs: { insuredSalary, effectiveRate },
    value: monthlyAllowance,
  });
  addStep(trace, {
    label: '合計給付',
    formula: 'monthly × months',
    inputs: { monthly: monthlyAllowance, months: safeMonths },
    value: totalAllowance,
    note:
      safeMonths < months
        ? `就保§19-2 每一子女最長 ${PARENTAL_ALLOWANCE_MAX_MONTHS} 個月，已 clamp`
        : undefined,
  });
  addLaw(trace, {
    article: '就業保險法§19-2 I',
    description:
      '育嬰留職停薪津貼以當月起前六個月平均月投保薪資 60% 計算，每一子女合計最長發給 6 個月。',
  });
  if (includeSupplement) {
    addLaw(trace, {
      article: '行政院「育嬰留職停薪薪資補助要點」（110.7.1 施行）',
      description:
        '就保§19-2 期間加發投保薪資 20% 補助，與津貼合併發給，無須另行申請。',
    });
  }
  addLaw(trace, {
    article: '性別平等工作法§16 I',
    description:
      '受僱者任職滿 6 個月後，於每一子女滿 3 歲前得申請育嬰留職停薪，最長 2 年。',
  });
  setSummary(
    trace,
    `育嬰留停津貼合計 ${totalAllowance.toLocaleString()} 元（${monthlyAllowance.toLocaleString()} × ${safeMonths} 個月）`,
  );

  return {
    monthlyAllowance,
    totalAllowance,
    months: safeMonths,
    effectiveRate,
    trace,
  };
}

/**
 * 整套試算（產假 + 育嬰留停津貼）— 女性受僱者
 *
 * 男性僅 calc 育嬰留停津貼即可，產假部分傳 includeMaternity=false。
 *
 * @param {object} params
 * @param {number} params.monthlySalary 月薪
 * @param {number} params.insuredSalary 平均月投保薪資
 * @param {number} params.tenureMonths 受僱年資（月）— 影響產假給付率
 * @param {boolean} [params.includeMaternity=true]
 * @param {number} [params.parentalMonths=6]
 * @param {boolean} [params.includeSupplement=true]
 * @returns {{
 *   maternity: ReturnType<typeof calcMaternityPay> | null,
 *   parental: ReturnType<typeof calcParentalAllowance>,
 *   grandTotal: number,
 *   eligibleForParental: boolean
 * }}
 */
export function calcParentalLeavePackage({
  monthlySalary,
  insuredSalary,
  tenureMonths,
  includeMaternity = true,
  parentalMonths = PARENTAL_ALLOWANCE_MAX_MONTHS,
  includeSupplement = true,
}) {
  const maternity =
    includeMaternity && monthlySalary > 0
      ? calcMaternityPay({ monthlySalary, tenureMonths })
      : null;
  const parental = calcParentalAllowance({
    insuredSalary,
    months: parentalMonths,
    includeSupplement,
  });
  // 性平法§16 申請門檻：任職滿 6 個月才能申請育嬰留停
  const eligibleForParental = tenureMonths >= PARENTAL_LEAVE_MIN_TENURE_MONTHS;
  const grandTotal = (maternity?.amount ?? 0) + parental.totalAllowance;
  return { maternity, parental, grandTotal, eligibleForParental };
}
