/**
 * overtime.js — 加班費與時薪
 *
 * ## 法源
 * - 勞基法§24（平日延長工時加成）
 * - 勞基法§24 II、§36（休息日出勤）
 * - 勞動部 106.6.16 勞動條 2 字第 1060131319 號函（休息日 2 小時以上加成細節）
 * - 勞基法§37、§39（國定假日）、§36、§40（例假）
 */

/**
 * 時薪計算（月薪 ÷ 30 ÷ 8）
 */
export function getHourlyRate(monthlySalary) {
  return monthlySalary / 30 / 8;
}

/**
 * 日薪計算（月薪 ÷ 30）
 */
export function getDailyRate(monthlySalary) {
  return monthlySalary / 30;
}

/**
 * 加班費計算（雇主角度）
 *
 * 法源：
 * - 平日延長工時（勞基法§24）：前 2 小時 × 4/3（+33.3%）、第 3-4 小時 × 5/3（+66.7%）
 * - 休息日出勤（勞基法§24 II、§36）：前 2 小時 × 4/3、2~8 小時 × 5/3、超過 8 小時 × 5/3
 *   （休息日超 2 小時之加成率與平日第 3-4 小時相同，細節見勞動部 106.6.16 勞動條 2
 *   字第 1060131319 號函）
 * - 國定假日（§37、§39）與例假（§36、§40）另依雙倍工資計算，本函式以 'holiday' 類型處理（× 2）
 *
 * @param {number} monthlySalary 月薪
 * @param {number} hours 加班時數
 * @param {'weekday'|'restday'|'mixed'|'holiday'} type 加班類型
 * @returns {number} 加班費金額
 */
export function calcOvertimeCost(monthlySalary, hours, type) {
  const hourly = monthlySalary / 30 / 8;
  if (type === 'weekday') {
    // 法源：§24 規定前 2 小時 4/3、第 3 小時起 5/3。§32 規定每日延長工時 4 小時上限，
    // 但這是「禁止超時」不是「超時免付」。實務勞動爭議中超時部分仍要算加班費追償，
    // 故本函式對 hours > 4 不做 cap，超出部分以 5/3 計算。
    // 雇主若需算「合法工時上限」之成本估算，應由 caller 端先 cap (Math.min(hours, 4))。
    const h1 = Math.min(hours, 2);
    const h2 = Math.max(hours - 2, 0); // 第 3 小時起全部 5/3，無 cap
    return h1 * hourly * (4 / 3) + h2 * hourly * (5 / 3);
  }
  if (type === 'restday') {
    const r1 = Math.min(hours, 2);
    const r2 = Math.max(Math.min(hours - 2, 6), 0);
    const r3 = Math.max(hours - 8, 0);
    return r1 * hourly * (4 / 3) + r2 * hourly * (5 / 3) + r3 * hourly * (5 / 3);
  }
  if (type === 'mixed') {
    const wdH = hours * 0.6;
    const rdH = hours * 0.4;
    return calcOvertimeCost(monthlySalary, wdH, 'weekday')
         + calcOvertimeCost(monthlySalary, rdH, 'restday');
  }
  return hours * hourly * 2; // holiday
}
