/**
 * scenarios.js — What-If 情境模擬器（教授戰略 P0：事前模擬）
 *
 * ## 為何存在
 * 教授原話：「計算只是基礎。讓工具從『事後算帳』變成『事前規劃』。
 *           例：不只算加班費，還能模擬『調整排班結構，能省下多少法規風險成本』。」
 *
 * 既有 traced 函式（overtime / severance）回答「現在這筆要付多少」。
 * 本檔提供「如果做 X 改動，全年成本/合規風險差多少」的對比模擬。
 *
 * ## 設計原則
 * - 純函式、無 side effect（同 trace.js 慣例）
 * - 全部回 { result, trace }，trace.steps + trace.laws 與既有 traced 風格相容
 * - 罰鍰金額一律從 LABOR_PENALTIES 拉，**禁止自創**
 * - 法源：勞基法§32（延長工時上限）、§32-1（補休）、§34（11h 連續休息）、
 *         §36（例假/休息日）、§40（例假停止）、§79（罰則）
 * - 條文版本同 penalties.js：勞基法 民國 113.7.31 公布
 *
 * @see HR-UX-* / 教授戰略建議 P0「事前模擬」
 */

import { createTrace, addStep, addLaw, setSummary } from './trace.js';
import { LABOR_PENALTIES, getPenaltyByArticle } from './penalties.js';
import { LEGAL_FLOOR, resolveValue } from './overrides.js';
import { parseDateTW } from './dates.js';
import { calcSeveranceNewTraced, calcSeveranceOldTraced } from './severance-traced.js';

// ─── 法規上限常數（勞基法 113.7.31 公布版逐字驗證）──────────────
/** §32 II：單月延長工時上限（小時） */
const OT_MONTHLY_CAP = 46;
/** §32 III：經工會/勞資會議同意，單月延長工時上限 */
const OT_MONTHLY_CAP_APPROVED = 54;
/** §32 III：3 個月延長工時合計上限 */
const OT_QUARTERLY_CAP_APPROVED = 138;
/** §34 I：輪班制換班間應有 11 小時連續休息（一般行業，自 108.3.1 施行） */
const REST_BETWEEN_SHIFTS_HOURS = 11;
/** §32 / §30：單日正常 + 延長工時上限 */
const DAILY_TOTAL_HOURS_CAP = 12;

/** §79 I 1 範圍（2 萬–100 萬，2-100w） */
const PENALTY_RANGE_OT_CAP = (() => {
  const p = getPenaltyByArticle('勞基法§32');
  if (!p) throw new Error('penalties.js 缺 lba-32-overtime-cap');
  return { min: p.penaltyMin, max: p.penaltyMax, articleCited: p.articleCited, penaltyArticle: p.penaltyArticle, id: p.id };
})();
/** §30 違反（出勤紀錄 / 正常工時超限）：本檔將「§34 違反」歸入此款 */
const PENALTY_RANGE_WORKTIME = (() => {
  const p = getPenaltyByArticle('勞基法§30');
  if (!p) throw new Error('penalties.js 缺 lba-30-worktime');
  return { min: p.penaltyMin, max: p.penaltyMax, articleCited: p.articleCited, penaltyArticle: p.penaltyArticle, id: p.id };
})();
/** §39 違反（例假/休假/特休工資）— 例假出勤未經§40 程序時的對應罰則 */
const PENALTY_RANGE_RESTPAY = (() => {
  const p = getPenaltyByArticle('勞基法§39');
  if (!p) throw new Error('penalties.js 缺 lba-39-restpay');
  return { min: p.penaltyMin, max: p.penaltyMax, articleCited: p.articleCited, penaltyArticle: p.penaltyArticle, id: p.id };
})();
/** §24 違反（加班費未依法給付） */
const PENALTY_RANGE_OT_PAY = (() => {
  const p = getPenaltyByArticle('勞基法§24');
  if (!p) throw new Error('penalties.js 缺 lba-24-overtime');
  return { min: p.penaltyMin, max: p.penaltyMax, articleCited: p.articleCited, penaltyArticle: p.penaltyArticle, id: p.id };
})();

/**
 * @typedef {Object} EmployeeOTSnapshot
 * @property {string} id                   員工識別（前端傳入即可，不必 UUID）
 * @property {number} hourlyEquiv          時薪等效（NTD/小時）
 * @property {number} currentMonthlyOT     目前月加班時數
 * @property {number} targetReductionPct   目標縮減百分比（0-100）
 */

/**
 * @typedef {Object} ComplianceImpact
 * @property {string} article          觸發條文（例 '勞基法§32'）
 * @property {string} reason           白話原因
 * @property {number} affectedCount    受影響員工數
 * @property {number} penaltyMin       罰鍰下限
 * @property {number} penaltyMax       罰鍰上限
 * @property {string} penaltyArticle   罰則條文
 */

/**
 * @typedef {Object} OvertimeReductionResult
 * @property {number} currentAnnualOTCost      當前年加班費（NTD）
 * @property {number} targetAnnualOTCost       目標年加班費
 * @property {number} savedCost                節省成本（current - target）
 * @property {number} reducedRiskAmountMin     合規風險罰鍰下限改善
 * @property {number} reducedRiskAmountMax     合規風險罰鍰上限改善
 * @property {number} currentViolations        當前違反人次
 * @property {number} targetViolations         調整後違反人次
 * @property {ComplianceImpact[]} complianceImpact
 */

/**
 * 模擬「縮減加班費」情境
 *
 * 計算：
 *   當前加班費（hourlyEquiv × 月加班時數 × 1.34，採加權平均倍率近似）vs
 *   目標縮減後加班費 → 差額 × 月數 = 全年節省。
 *
 * 風險面：
 *   逐員工檢查當前月加班時數是否超過 §32 II（46 h）或 §32 III（54 h），
 *   若超過則命中 LABOR_PENALTIES 中 lba-32-overtime-cap（§79 I 1：2-100 萬）。
 *   調整後重新檢查，回報減少的違反人次與罰鍰風險區間（上下限）。
 *
 * 注意：
 *   - 本函式僅做「事前模擬」估算，倍率以 1.34（前 2h 1/3 加成）做加權近似，
 *     若需精確金額，請對單員工逐筆呼叫 calcOvertimeCostTraced。
 *   - 未顧及 §32 III 三個月 138 h 上限（須 3 月歷史資料），由 UI 提示。
 *
 * @param {Object} input
 * @param {EmployeeOTSnapshot[]} input.employees
 * @param {number} input.months                   模擬月數（通常 12）
 * @param {boolean} [input.hasUnionApproval]      是否經工會/勞資會議同意（影響 §32 上限）
 * @returns {{ result: OvertimeReductionResult, trace: import('./trace.js').CalcTrace }}
 */
export function simulateOvertimeReduction(input) {
  const { employees, months, hasUnionApproval = false } = input;
  if (!Array.isArray(employees)) throw new Error('employees must be an array');
  if (!Number.isFinite(months) || months <= 0) throw new Error('months must be > 0');

  const trace = createTrace();
  addLaw(trace, {
    article: '勞基法§24',
    description: '平日延長工時前 2 小時加給 1/3、第 3-4 小時加給 2/3（加權平均近似 1.34）',
  });
  addLaw(trace, {
    article: '勞基法§32 II / III',
    description: hasUnionApproval
      ? `經工會或勞資會議同意，單月延長工時上限 ${OT_MONTHLY_CAP_APPROVED} 小時`
      : `單月延長工時不得超過 ${OT_MONTHLY_CAP} 小時`,
  });
  addLaw(trace, {
    article: PENALTY_RANGE_OT_CAP.penaltyArticle,
    description: `違反§32 上限：罰鍰 ${PENALTY_RANGE_OT_CAP.min.toLocaleString()}–${PENALTY_RANGE_OT_CAP.max.toLocaleString()} 元（每 1 名違反人次計）`,
  });

  // 加權平均倍率（前 2h × 1/3 + 後 2h × 2/3 ≈ 1.5；前 2h ≈ 1.34；採保守 1.34 估算）
  const AVG_OT_RATE = 4 / 3;
  const monthlyCap = hasUnionApproval ? OT_MONTHLY_CAP_APPROVED : OT_MONTHLY_CAP;

  let currentAnnualOTCost = 0;
  let targetAnnualOTCost = 0;
  let currentViolations = 0;
  let targetViolations = 0;

  employees.forEach((emp) => {
    if (!Number.isFinite(emp.hourlyEquiv) || emp.hourlyEquiv < 0) {
      throw new Error(`invalid hourlyEquiv for employee ${emp.id}`);
    }
    if (!Number.isFinite(emp.currentMonthlyOT) || emp.currentMonthlyOT < 0) {
      throw new Error(`invalid currentMonthlyOT for employee ${emp.id}`);
    }
    if (!Number.isFinite(emp.targetReductionPct) || emp.targetReductionPct < 0 || emp.targetReductionPct > 100) {
      throw new Error(`targetReductionPct must be 0-100 for employee ${emp.id}`);
    }
    const targetMonthlyOT = emp.currentMonthlyOT * (1 - emp.targetReductionPct / 100);
    const empCurrent = emp.hourlyEquiv * AVG_OT_RATE * emp.currentMonthlyOT * months;
    const empTarget = emp.hourlyEquiv * AVG_OT_RATE * targetMonthlyOT * months;
    currentAnnualOTCost += empCurrent;
    targetAnnualOTCost += empTarget;

    if (emp.currentMonthlyOT > monthlyCap) currentViolations += 1;
    if (targetMonthlyOT > monthlyCap) targetViolations += 1;
  });

  addStep(trace, {
    label: '當前年加班費（加權近似）',
    formula: 'Σ hourlyEquiv × 1.333 × monthlyOT × months',
    inputs: { employees: employees.length, months, avgRate: AVG_OT_RATE },
    value: currentAnnualOTCost,
    note: '前 2h 1/3 加成保守估；精確金額請對單員工呼叫 calcOvertimeCostTraced',
  });
  addStep(trace, {
    label: '目標年加班費',
    formula: 'Σ hourlyEquiv × 1.333 × (monthlyOT × (1 − targetReductionPct/100)) × months',
    value: targetAnnualOTCost,
  });
  const savedCost = currentAnnualOTCost - targetAnnualOTCost;
  addStep(trace, {
    label: '年節省成本',
    formula: 'currentAnnualOTCost − targetAnnualOTCost',
    value: savedCost,
  });

  // 合規風險：超過 §32 上限的人次 × 罰鍰範圍
  const reducedViolations = Math.max(currentViolations - targetViolations, 0);
  const reducedRiskAmountMin = reducedViolations * PENALTY_RANGE_OT_CAP.min;
  const reducedRiskAmountMax = reducedViolations * PENALTY_RANGE_OT_CAP.max;

  addStep(trace, {
    label: '當前超 §32 上限人次',
    formula: `count(currentMonthlyOT > ${monthlyCap})`,
    value: currentViolations,
    note: hasUnionApproval ? '已假設經工會/勞資會議同意（54h 線）' : '無工會/勞資會議同意（46h 線）',
  });
  addStep(trace, {
    label: '調整後超 §32 上限人次',
    formula: `count(targetMonthlyOT > ${monthlyCap})`,
    value: targetViolations,
  });
  addStep(trace, {
    label: '合規風險罰鍰減少（區間）',
    formula: `reducedViolations × [${PENALTY_RANGE_OT_CAP.min}, ${PENALTY_RANGE_OT_CAP.max}]`,
    value: reducedRiskAmountMin,
    note: `下限 ${reducedRiskAmountMin.toLocaleString()} ~ 上限 ${reducedRiskAmountMax.toLocaleString()} 元（${PENALTY_RANGE_OT_CAP.penaltyArticle}）`,
  });

  /** @type {ComplianceImpact[]} */
  const complianceImpact = [];
  if (reducedViolations > 0) {
    complianceImpact.push({
      article: PENALTY_RANGE_OT_CAP.articleCited,
      reason: `${reducedViolations} 名員工從超 ${monthlyCap}h/月 降回合規區間`,
      affectedCount: reducedViolations,
      penaltyMin: PENALTY_RANGE_OT_CAP.min,
      penaltyMax: PENALTY_RANGE_OT_CAP.max,
      penaltyArticle: PENALTY_RANGE_OT_CAP.penaltyArticle,
    });
  }

  setSummary(
    trace,
    `加班削減模擬：年省 ${Math.round(savedCost).toLocaleString()} 元` +
      (reducedViolations > 0
        ? ` · 減 ${reducedViolations} 名違反 §32 員工，罰鍰風險 -${reducedRiskAmountMin.toLocaleString()}~${reducedRiskAmountMax.toLocaleString()} 元`
        : ' · 無 §32 違反人次變動'),
  );

  return {
    result: {
      currentAnnualOTCost,
      targetAnnualOTCost,
      savedCost,
      reducedRiskAmountMin,
      reducedRiskAmountMax,
      currentViolations,
      targetViolations,
      complianceImpact,
    },
    trace,
  };
}

/**
 * @typedef {Object} ShiftRecord
 * @property {string} employeeId
 * @property {string} shiftDate         'YYYY-MM-DD'
 * @property {string} startAt           ISO 或 'YYYY-MM-DD HH:mm' 字串（Date.parse 可解析）
 * @property {string} endAt
 * @property {boolean} [isRestDay]      是否為休息日（§36）
 * @property {boolean} [isHoliday]      是否為例假/國定假日（§36 例假；§37 國定）
 */

/**
 * @typedef {Object} ShiftViolation
 * @property {string} kind          'rest_below_11h' | 'overtime_cap' | 'rest_day_work' | 'daily_total_over_12h'
 * @property {string} article
 * @property {string} description
 * @property {string} employeeId
 * @property {string} [refDate]
 */

/**
 * @typedef {Object} ShiftRestructureResult
 * @property {{ shifts: number, violations: number, byKind: Record<string, number> }} current
 * @property {{ shifts: number, violations: number, byKind: Record<string, number> }} proposed
 * @property {number} reducedViolations
 * @property {number} reducedRiskAmountMin
 * @property {number} reducedRiskAmountMax
 * @property {ComplianceImpact[]} complianceImpact
 * @property {ShiftViolation[]} sampleViolations    最多列 20 筆典型違反
 */

/**
 * 模擬「排班重組」情境：對比 currentShifts vs proposedShifts 的違規數
 *
 * 檢查項目：
 *   - §34 I：同一勞工兩班次間應有 11 小時連續休息
 *   - §32 II：單月延長工時 > 46 h（無工會同意時）
 *   - §40 I：例假停止（isHoliday=true 且有出勤）→ 對應 §39 罰鍰
 *   - §32 + §30：單日正常 + 延長 > 12 h
 *
 * @param {Object} input
 * @param {ShiftRecord[]} input.shifts
 * @param {ShiftRecord[]} input.proposedShifts
 * @param {boolean} [input.hasUnionApproval]
 * @returns {{ result: ShiftRestructureResult, trace: import('./trace.js').CalcTrace }}
 */
export function simulateShiftRestructure(input) {
  const { shifts, proposedShifts, hasUnionApproval = false } = input;
  if (!Array.isArray(shifts) || !Array.isArray(proposedShifts)) {
    throw new Error('shifts and proposedShifts must be arrays');
  }

  const trace = createTrace();
  addLaw(trace, {
    article: '勞基法§34 I',
    description: `輪班制換班間應有 ${REST_BETWEEN_SHIFTS_HOURS} 小時連續休息（108.3.1 施行）`,
  });
  addLaw(trace, {
    article: '勞基法§32 II',
    description: `延長工時單月不得超過 ${OT_MONTHLY_CAP} 小時（無工會同意）`,
  });
  addLaw(trace, {
    article: '勞基法§40 I',
    description: '非天災事變或突發事件不得停止例假；例假出勤須加倍工資並補假',
  });
  addLaw(trace, {
    article: '勞基法§30 V',
    description: '單日正常 + 延長工時不得超過 12 小時',
  });
  addLaw(trace, {
    article: PENALTY_RANGE_WORKTIME.penaltyArticle,
    description: `違反§30/§34：罰鍰 ${PENALTY_RANGE_WORKTIME.min.toLocaleString()}–${PENALTY_RANGE_WORKTIME.max.toLocaleString()} 元`,
  });
  addLaw(trace, {
    article: PENALTY_RANGE_RESTPAY.penaltyArticle,
    description: `違反§39（含例假未依§40 程序停止）：罰鍰 ${PENALTY_RANGE_RESTPAY.min.toLocaleString()}–${PENALTY_RANGE_RESTPAY.max.toLocaleString()} 元`,
  });

  const monthlyCap = hasUnionApproval ? OT_MONTHLY_CAP_APPROVED : OT_MONTHLY_CAP;
  const cur = analyzeShifts(shifts, monthlyCap);
  const prop = analyzeShifts(proposedShifts, monthlyCap);

  addStep(trace, {
    label: '當前排班違反數',
    formula: 'count(violations: rest_below_11h | overtime_cap | rest_day_work | daily_total_over_12h)',
    inputs: { shifts: shifts.length },
    value: cur.violations.length,
  });
  addStep(trace, {
    label: '提案排班違反數',
    formula: 'count(violations on proposedShifts)',
    inputs: { shifts: proposedShifts.length },
    value: prop.violations.length,
  });

  const reducedViolations = Math.max(cur.violations.length - prop.violations.length, 0);

  // 罰鍰風險：對 by-kind 分別套用對應條文範圍（採取「按次處罰」保守估，不重複疊加）
  const reducedByKind = subtractKindCounts(cur.byKind, prop.byKind);
  const otCapReduced = reducedByKind.overtime_cap || 0;
  const restReduced = (reducedByKind.rest_below_11h || 0) + (reducedByKind.daily_total_over_12h || 0);
  const restDayReduced = reducedByKind.rest_day_work || 0;

  const reducedRiskAmountMin =
    otCapReduced * PENALTY_RANGE_OT_CAP.min +
    restReduced * PENALTY_RANGE_WORKTIME.min +
    restDayReduced * PENALTY_RANGE_RESTPAY.min;
  const reducedRiskAmountMax =
    otCapReduced * PENALTY_RANGE_OT_CAP.max +
    restReduced * PENALTY_RANGE_WORKTIME.max +
    restDayReduced * PENALTY_RANGE_RESTPAY.max;

  addStep(trace, {
    label: '減少違反項分類',
    formula: 'overtime_cap × §32 + rest_below_11h/daily × §30/§34 + rest_day_work × §39',
    inputs: { overtime_cap: otCapReduced, rest_violations: restReduced, rest_day_work: restDayReduced },
    value: reducedViolations,
  });
  addStep(trace, {
    label: '罰鍰風險減少（區間）',
    formula: 'Σ reducedKindCount × LABOR_PENALTIES[kind].penaltyMin/Max',
    value: reducedRiskAmountMin,
    note: `下限 ${reducedRiskAmountMin.toLocaleString()} ~ 上限 ${reducedRiskAmountMax.toLocaleString()} 元`,
  });

  /** @type {ComplianceImpact[]} */
  const complianceImpact = [];
  if (otCapReduced > 0) {
    complianceImpact.push({
      article: PENALTY_RANGE_OT_CAP.articleCited,
      reason: `${otCapReduced} 員月加班 > ${monthlyCap}h 違反項移除`,
      affectedCount: otCapReduced,
      penaltyMin: PENALTY_RANGE_OT_CAP.min,
      penaltyMax: PENALTY_RANGE_OT_CAP.max,
      penaltyArticle: PENALTY_RANGE_OT_CAP.penaltyArticle,
    });
  }
  if (restReduced > 0) {
    complianceImpact.push({
      article: PENALTY_RANGE_WORKTIME.articleCited,
      reason: `${restReduced} 件班次間休息不足 11h 或單日 > 12h`,
      affectedCount: restReduced,
      penaltyMin: PENALTY_RANGE_WORKTIME.min,
      penaltyMax: PENALTY_RANGE_WORKTIME.max,
      penaltyArticle: PENALTY_RANGE_WORKTIME.penaltyArticle,
    });
  }
  if (restDayReduced > 0) {
    complianceImpact.push({
      article: PENALTY_RANGE_RESTPAY.articleCited,
      reason: `${restDayReduced} 件例假/休假出勤違反項`,
      affectedCount: restDayReduced,
      penaltyMin: PENALTY_RANGE_RESTPAY.min,
      penaltyMax: PENALTY_RANGE_RESTPAY.max,
      penaltyArticle: PENALTY_RANGE_RESTPAY.penaltyArticle,
    });
  }

  setSummary(
    trace,
    `排班重組模擬：違反 ${cur.violations.length} → ${prop.violations.length} 件 ` +
      `(-${reducedViolations})，罰鍰風險 -${reducedRiskAmountMin.toLocaleString()}~${reducedRiskAmountMax.toLocaleString()} 元`,
  );

  return {
    result: {
      current: { shifts: shifts.length, violations: cur.violations.length, byKind: cur.byKind },
      proposed: { shifts: proposedShifts.length, violations: prop.violations.length, byKind: prop.byKind },
      reducedViolations,
      reducedRiskAmountMin,
      reducedRiskAmountMax,
      complianceImpact,
      sampleViolations: cur.violations.slice(0, 20),
    },
    trace,
  };
}

/**
 * 排班分析：回傳違反清單 + by-kind 計數
 * @param {ShiftRecord[]} shifts
 * @param {number} monthlyCap
 * @returns {{ violations: ShiftViolation[], byKind: Record<string, number> }}
 */
function analyzeShifts(shifts, monthlyCap) {
  /** @type {ShiftViolation[]} */
  const violations = [];
  /** @type {Record<string, number>} */
  const byKind = { rest_below_11h: 0, overtime_cap: 0, rest_day_work: 0, daily_total_over_12h: 0 };

  // 依員工 + 時間排序
  const byEmployee = new Map();
  shifts.forEach((s) => {
    const arr = byEmployee.get(s.employeeId) ?? [];
    arr.push(s);
    byEmployee.set(s.employeeId, arr);
  });

  byEmployee.forEach((arr, employeeId) => {
    const sorted = [...arr].sort((a, b) => Date.parse(a.startAt) - Date.parse(b.startAt));

    // §34：兩班次間 11 小時連續休息
    for (let i = 1; i < sorted.length; i += 1) {
      const prevEnd = Date.parse(sorted[i - 1].endAt);
      const curStart = Date.parse(sorted[i].startAt);
      if (!Number.isFinite(prevEnd) || !Number.isFinite(curStart)) continue;
      const gapHours = (curStart - prevEnd) / 3_600_000;
      if (gapHours >= 0 && gapHours < REST_BETWEEN_SHIFTS_HOURS) {
        violations.push({
          kind: 'rest_below_11h',
          article: '勞基法§34 I',
          description: `班次間連續休息僅 ${gapHours.toFixed(1)}h（< ${REST_BETWEEN_SHIFTS_HOURS}h）`,
          employeeId,
          refDate: sorted[i].shiftDate,
        });
        byKind.rest_below_11h += 1;
      }
    }

    // §30/§32：單日正常 + 延長 > 12 h
    sorted.forEach((s) => {
      const start = Date.parse(s.startAt);
      const end = Date.parse(s.endAt);
      if (!Number.isFinite(start) || !Number.isFinite(end) || end <= start) return;
      const hours = (end - start) / 3_600_000;
      if (hours > DAILY_TOTAL_HOURS_CAP) {
        violations.push({
          kind: 'daily_total_over_12h',
          article: '勞基法§32 II（單日 12h 上限）',
          description: `單日工時 ${hours.toFixed(1)}h 超過 ${DAILY_TOTAL_HOURS_CAP}h`,
          employeeId,
          refDate: s.shiftDate,
        });
        byKind.daily_total_over_12h += 1;
      }
    });

    // §40：例假 isHoliday=true 仍出勤 → 違反
    sorted.forEach((s) => {
      if (s.isHoliday) {
        violations.push({
          kind: 'rest_day_work',
          article: '勞基法§40 I',
          description: '例假出勤未經天災/事變/突發事件程序',
          employeeId,
          refDate: s.shiftDate,
        });
        byKind.rest_day_work += 1;
      }
    });

    // §32：以「月加班時數」估，正常 8h 以外的時數視為延長工時
    const monthly = new Map();
    sorted.forEach((s) => {
      const start = Date.parse(s.startAt);
      const end = Date.parse(s.endAt);
      if (!Number.isFinite(start) || !Number.isFinite(end) || end <= start) return;
      const hours = (end - start) / 3_600_000;
      const otHours = Math.max(hours - 8, 0);
      const ym = (s.shiftDate || '').slice(0, 7);
      monthly.set(ym, (monthly.get(ym) ?? 0) + otHours);
    });
    monthly.forEach((otSum, ym) => {
      if (otSum > monthlyCap) {
        violations.push({
          kind: 'overtime_cap',
          article: '勞基法§32 II',
          description: `${ym} 月延長工時 ${otSum.toFixed(1)}h 超過 ${monthlyCap}h 上限`,
          employeeId,
          refDate: ym,
        });
        byKind.overtime_cap += 1;
      }
    });
  });

  return { violations, byKind };
}

/** subtract by-kind counts; clamp to 0 */
function subtractKindCounts(a, b) {
  /** @type {Record<string, number>} */
  const out = {};
  Object.keys(a).forEach((k) => {
    out[k] = Math.max((a[k] || 0) - (b[k] || 0), 0);
  });
  return out;
}

/**
 * @typedef {Object} OverridePolicyChangeResult
 * @property {number} annualCostDelta              年度成本增減（NTD，正=增加）
 * @property {Array<{
 *   ruleKey: string,
 *   currentValue: number,
 *   proposedValue: number,
 *   legalFloor: number,
 *   legallyValid: boolean,
 *   estimatedCostDelta: number,
 *   note?: string,
 * }>} ruleImpacts
 * @property {ComplianceImpact[]} complianceImpact
 */

/**
 * 模擬「內部規範變更」情境：對比 currentOverrides vs proposedOverrides 的成本影響
 *
 * 對應 rule_keys（與 LEGAL_FLOOR / overrides.js 對齊）：
 *   - severance.cap_months（資遣費上限月數，法規 6）
 *   - severance.base_per_year_months（資遣基數，法規 0.5）
 *   - overtime.rate_weekday_h1_h2（平日前 2h 倍率）
 *   - overtime.rate_weekday_h3_h4
 *   - overtime.rate_restday_h1_h2
 *   - overtime.rate_restday_h2_h8
 *   - overtime.rate_holiday
 *
 * 估算法（保守線性）：
 *   - severance.cap_months：年度資遣人數 × baseSalary × (proposed - current)
 *   - severance.base_per_year_months：年度資遣人數 × 平均年資(年) × baseSalary × (proposed - current)
 *   - overtime.rate_*：員工數 × 月平均加班時數(假設 12h) × 12 × baseSalary/30/8 × (proposed - current)
 *
 * 同時回報「proposed 是否仍合法」（>= LEGAL_FLOOR）。
 *
 * @param {Object} input
 * @param {string} [input.workspaceId]
 * @param {Record<string, { value: any, is_active?: boolean, source_ref?: string|null, note?: string|null }>} [input.currentOverrides]
 * @param {Record<string, { value: any, is_active?: boolean, source_ref?: string|null, note?: string|null }>} input.proposedOverrides
 * @param {number} input.employeeBaseSalary             代表性月薪（NTD）
 * @param {number} input.sampleEmployeeCount            員工樣本數
 * @param {number} [input.annualSeveranceCount]         年度資遣人數估計（預設 sampleEmployeeCount × 5%）
 * @param {number} [input.avgYearsOfService]            平均年資（年，預設 5）
 * @param {number} [input.avgMonthlyOTHours]            平均月加班時數（預設 12）
 * @returns {{ result: OverridePolicyChangeResult, trace: import('./trace.js').CalcTrace }}
 */
export function simulateOverridePolicyChange(input) {
  const {
    currentOverrides = {},
    proposedOverrides,
    employeeBaseSalary,
    sampleEmployeeCount,
    annualSeveranceCount,
    avgYearsOfService = 5,
    avgMonthlyOTHours = 12,
  } = input;
  if (!proposedOverrides || typeof proposedOverrides !== 'object') {
    throw new Error('proposedOverrides required');
  }
  if (!Number.isFinite(employeeBaseSalary) || employeeBaseSalary <= 0) {
    throw new Error('employeeBaseSalary must be > 0');
  }
  if (!Number.isFinite(sampleEmployeeCount) || sampleEmployeeCount <= 0) {
    throw new Error('sampleEmployeeCount must be > 0');
  }

  const severanceCount = Number.isFinite(annualSeveranceCount)
    ? annualSeveranceCount
    : Math.max(Math.round(sampleEmployeeCount * 0.05), 0);

  const trace = createTrace();
  addLaw(trace, { article: '勞退條例§12', description: '新制資遣費上限 6 個月平均工資' });
  addLaw(trace, { article: '勞基法§17', description: '舊制資遣費基數每滿 1 年 1 個月平均工資' });
  addLaw(trace, { article: '勞基法§24', description: '加班費倍率法定下限' });

  /** @type {OverridePolicyChangeResult['ruleImpacts']} */
  const ruleImpacts = [];
  let annualCostDelta = 0;

  /** 列出我們會計算的 rule_keys + valuePath + LEGAL_FLOOR 對應 */
  const TRACKED = [
    {
      ruleKey: 'severance.cap_months',
      valuePath: 'months',
      legalFloor: LEGAL_FLOOR.severance_cap_months,
      // 上限提高 → 高年資員工資遣費隨之提高，每多 1 個月 = baseSalary
      delta: (cur, prop) => severanceCount * employeeBaseSalary * (prop - cur),
      note: `年度資遣人數估 ${severanceCount} 名 × 月薪`,
    },
    {
      ruleKey: 'severance.base_per_year_months',
      valuePath: 'months',
      legalFloor: LEGAL_FLOOR.severance_base_per_year_months,
      delta: (cur, prop) => severanceCount * avgYearsOfService * employeeBaseSalary * (prop - cur),
      note: `年資 ${avgYearsOfService} 年 × ${severanceCount} 名 × 月薪`,
    },
    {
      ruleKey: 'overtime.rate_weekday_h1_h2',
      valuePath: 'rate',
      legalFloor: LEGAL_FLOOR.overtime_rate_weekday_h1_h2,
      delta: (cur, prop) =>
        sampleEmployeeCount * (employeeBaseSalary / 30 / 8) * avgMonthlyOTHours * 12 * (prop - cur),
      note: `${sampleEmployeeCount} 員 × ${avgMonthlyOTHours}h/月 × 12 月`,
    },
    {
      ruleKey: 'overtime.rate_weekday_h3_h4',
      valuePath: 'rate',
      legalFloor: LEGAL_FLOOR.overtime_rate_weekday_h3_h4,
      delta: (cur, prop) =>
        sampleEmployeeCount * (employeeBaseSalary / 30 / 8) * (avgMonthlyOTHours * 0.3) * 12 * (prop - cur),
      note: '保守估 30% 加班發生在第 3-4 小時段',
    },
    {
      ruleKey: 'overtime.rate_restday_h1_h2',
      valuePath: 'rate',
      legalFloor: LEGAL_FLOOR.overtime_rate_restday_h1_h2,
      delta: (cur, prop) =>
        sampleEmployeeCount * (employeeBaseSalary / 30 / 8) * (avgMonthlyOTHours * 0.2) * 12 * (prop - cur),
      note: '保守估 20% 加班發生在休息日前 2h',
    },
    {
      ruleKey: 'overtime.rate_restday_h2_h8',
      valuePath: 'rate',
      legalFloor: LEGAL_FLOOR.overtime_rate_restday_h2_h8,
      delta: (cur, prop) =>
        sampleEmployeeCount * (employeeBaseSalary / 30 / 8) * (avgMonthlyOTHours * 0.2) * 12 * (prop - cur),
      note: '保守估 20% 加班發生在休息日 2-8h 段',
    },
    {
      ruleKey: 'overtime.rate_holiday',
      valuePath: 'rate',
      legalFloor: LEGAL_FLOOR.overtime_rate_holiday,
      delta: (cur, prop) =>
        sampleEmployeeCount * (employeeBaseSalary / 30 / 8) * 8 * 6 * (prop - cur),
      note: '保守估每員年 6 日國定/例假出勤 × 8h',
    },
  ];

  TRACKED.forEach(({ ruleKey, valuePath, legalFloor, delta, note }) => {
    const cur = resolveValue(currentOverrides, ruleKey, valuePath, legalFloor);
    const prop = resolveValue(proposedOverrides, ruleKey, valuePath, legalFloor);
    // 如果 current 與 proposed 都沒設且等於 legalFloor 就跳過（沒影響）
    const proposedRaw = pickRaw(proposedOverrides, ruleKey, valuePath);
    const currentRaw = pickRaw(currentOverrides, ruleKey, valuePath);
    if (proposedRaw === null && currentRaw === null) return;

    const legallyValid = prop.value + 1e-9 >= legalFloor;
    const estimatedCostDelta = delta(cur.value, prop.value);
    annualCostDelta += estimatedCostDelta;

    ruleImpacts.push({
      ruleKey,
      currentValue: cur.value,
      proposedValue: prop.value,
      legalFloor,
      legallyValid,
      estimatedCostDelta,
      note,
    });

    addStep(trace, {
      label: `${ruleKey}：${cur.value} → ${prop.value}`,
      formula: legallyValid ? `delta × scale (${note})` : 'INVALID 提案值低於法規下限',
      inputs: { current: cur.value, proposed: prop.value, legalFloor },
      value: estimatedCostDelta,
      note: legallyValid
        ? `年成本影響 ${Math.round(estimatedCostDelta).toLocaleString()} 元（${note}）`
        : `❌ 提案值 ${prop.value} 低於法規下限 ${legalFloor}，不可實施`,
    });
  });

  addStep(trace, {
    label: '年度成本影響合計',
    formula: 'Σ ruleImpacts.estimatedCostDelta',
    value: annualCostDelta,
    note: annualCostDelta >= 0 ? '正數＝成本增加' : '負數＝成本減少',
  });

  /** @type {ComplianceImpact[]} */
  const complianceImpact = ruleImpacts
    .filter((r) => !r.legallyValid)
    .map((r) => ({
      article: `${r.ruleKey}（法規下限 ${r.legalFloor}）`,
      reason: `提案值 ${r.proposedValue} 低於法規下限，將被 API validateRuleValue 擋下`,
      affectedCount: sampleEmployeeCount,
      penaltyMin: 0,
      penaltyMax: 0,
      penaltyArticle: 'override-rules API validation',
    }));

  setSummary(
    trace,
    `內部規範變更模擬：年成本 ${annualCostDelta >= 0 ? '+' : ''}${Math.round(annualCostDelta).toLocaleString()} 元 · ` +
      `${ruleImpacts.length} 項規則受影響` +
      (complianceImpact.length > 0 ? ` · ${complianceImpact.length} 項提案違法被攔` : ''),
  );

  return {
    result: { annualCostDelta, ruleImpacts, complianceImpact },
    trace,
  };
}

/** 抽 raw value（不套 fallback），用來判斷 current/proposed 是否其實沒設值 */
function pickRaw(overrides, ruleKey, valuePath) {
  if (!overrides) return null;
  const r = overrides[ruleKey];
  if (!r || r.is_active === false) return null;
  const v = r.value;
  if (typeof v === 'number' && Number.isFinite(v)) return v;
  if (v && typeof v === 'object') {
    const n = v[valuePath];
    if (typeof n === 'number' && Number.isFinite(n)) return n;
  }
  return null;
}

/** 給 UI 用的「全部受支援 rule_keys」列表（讀取 LABOR_PENALTIES 不需要，純 helper） */
export const SUPPORTED_OVERRIDE_RULES = Object.freeze([
  'severance.cap_months',
  'severance.base_per_year_months',
  'overtime.rate_weekday_h1_h2',
  'overtime.rate_weekday_h3_h4',
  'overtime.rate_restday_h1_h2',
  'overtime.rate_restday_h2_h8',
  'overtime.rate_holiday',
]);

/**
 * computeSeverance — HR-UX-3 Pack A 規格 API：自動處理勞退新舊制 94/7/1 銜接
 *
 * 規則（已於 https://law.moj.gov.tw 全國法規資料庫驗證）：
 *   - 勞工退休金條例 94.6.30 公布、94.7.1 施行
 *   - 94/7/1 之前的年資：走舊制（勞基法§17）每滿 1 年 1 個月平均工資，無上限
 *   - 94/7/1 之後的年資：走新制（勞退條例§12）每滿 1 年 0.5 個月平均工資，最高 6 個月
 *   - 跨日員工：以 94/7/1 切兩段，分別套用後加總
 *
 * 注意：本函式假設員工為一律改提新制（94/7/1 後在職新進或既有員工改提）。
 *       若員工選擇保留舊制（勞退條例§9），整段年資皆走舊制，請於 caller 手動切換。
 *
 * @param {Object} params
 * @param {string|Date} params.startDate   到職日（'YYYY-MM-DD'）
 * @param {string|Date} params.endDate     離職日（'YYYY-MM-DD'）
 * @param {number} params.monthlyPay       平均工資（NTD/月）
 * @returns {{
 *   amount: number,
 *   oldAmount: number,
 *   newAmount: number,
 *   oldYears: number,
 *   newYears: number,
 *   trace: import('./trace.js').CalcTrace,
 * }}
 */
export function computeSeverance(params) {
  const { startDate, endDate, monthlyPay } = params;
  if (typeof monthlyPay !== 'number' || monthlyPay <= 0) {
    throw new Error('computeSeverance: invalid monthlyPay');
  }

  const start = parseDateTW(startDate);
  const end = parseDateTW(endDate);
  if (Number.isNaN(start.getTime()) || Number.isNaN(end.getTime()) || end <= start) {
    throw new Error('computeSeverance: invalid startDate/endDate');
  }

  // 勞退條例 94.7.1 施行（民國 94 年 = 西元 2005 年）
  const PIVOT = new Date(2005, 6, 1); // 2005-07-01 (本地時區)
  const PIVOT_LABEL = '94/7/1（勞退條例施行日）';

  const trace = createTrace();
  addLaw(trace, {
    article: '勞退條例§11',
    description: `94/7/1 前年資保留適用勞基法舊制；94/7/1 後年資適用新制（勞退條例§12）`,
  });
  addLaw(trace, { article: '勞基法§17', description: '舊制資遣費每滿 1 年 1 個月平均工資（不足 1 年按比例），無上限' });
  addLaw(trace, { article: '勞退條例§12', description: '新制資遣費每滿 1 年 0.5 個月平均工資，最高 6 個月' });

  // 切段：[start, min(PIVOT, end)] = 舊制 / [max(PIVOT, start), end] = 新制
  const oldStart = start;
  const oldEnd = end < PIVOT ? end : PIVOT;
  const newStart = start > PIVOT ? start : PIVOT;
  const newEnd = end;

  const DAY = 86_400_000;
  const oldDays = Math.max((oldEnd.getTime() - oldStart.getTime()) / DAY, 0);
  const newDays = Math.max((newEnd.getTime() - newStart.getTime()) / DAY, 0);
  const oldYears = oldDays / 365;
  const newYears = newDays / 365;

  addStep(trace, {
    label: '年資切段',
    formula: `舊制 = [start, min(${PIVOT_LABEL}, end)]；新制 = [max(${PIVOT_LABEL}, start), end]`,
    inputs: { oldDays, newDays },
    value: oldYears + newYears,
    note: `舊制 ${oldYears.toFixed(3)} 年 / 新制 ${newYears.toFixed(3)} 年`,
  });

  let oldAmount = 0;
  let newAmount = 0;

  if (oldYears > 0) {
    const r = calcSeveranceOldTraced(oldYears * 12, monthlyPay);
    oldAmount = r.result;
    addStep(trace, {
      label: '舊制資遣費（§17）',
      formula: 'oldYears × 1 × monthlyPay',
      inputs: { oldYears, monthlyPay },
      value: oldAmount,
      note: '無上限',
    });
  }

  if (newYears > 0) {
    const r = calcSeveranceNewTraced(newYears * 12, monthlyPay);
    newAmount = r.result;
    addStep(trace, {
      label: '新制資遣費（勞退條例§12）',
      formula: 'min(newYears × 0.5, 6) × monthlyPay',
      inputs: { newYears, monthlyPay },
      value: newAmount,
      note: '上限 6 個月',
    });
  }

  const amount = oldAmount + newAmount;
  addStep(trace, {
    label: '資遣費合計',
    formula: 'oldAmount + newAmount',
    value: amount,
  });

  setSummary(
    trace,
    `資遣費合計 ${Math.round(amount).toLocaleString()} 元 ` +
      `(舊 ${Math.round(oldAmount).toLocaleString()} + 新 ${Math.round(newAmount).toLocaleString()})`,
  );

  return { amount, oldAmount, newAmount, oldYears, newYears, trace };
}

// LABOR_PENALTIES 必須能正確 import（防 dead code 漏抓）
if (!Array.isArray(LABOR_PENALTIES) || LABOR_PENALTIES.length === 0) {
  throw new Error('LABOR_PENALTIES 未正確 import');
}
