/**
 * insurance-compliance.js — 高薪低報合規檢查（雇主版風險告誡 / 勞工版給付影響）
 *
 * 把實際月薪組成（含技術獎金、輪班補助、膳食費等）依§2 III 經常性給與判定出
 * 「月薪資總額」（= 投保薪資應申報基準，勞保條例§14），對照雇主實際申報的投保
 * 薪資，算出低報差額、補繳保費、罰鍰與刑事風險（雇主版）；以及被低報後勞工各項
 * 給付的縮水（勞工版）。計算引擎重用 wage-analysis（工資判定）+ brackets（級距查表）。
 *
 * ⚠️ 民眾版（勞工角度）與專業版（雇主角度）嚴格分流：本檔提供「計算」共用核心，
 *    兩條產品線的 UI / 文案 / prompt 各自包裝，不得共用敘事。
 *
 * ## 法源（每條已於 https://law.moj.gov.tw 全國法規資料庫逐字驗證 2026-05-30）
 *
 * - 勞工保險條例§14（pcode N0050001）
 *     月投保薪資由投保單位按被保險人之月薪資總額，依投保薪資分級表申報。
 *
 * - 勞工保險條例§72 III（pcode N0050001）— 高薪低報罰則
 *     投保單位將投保薪資金額以多報少或以少報多者，自事實發生之日起，按其短報或
 *     多報之保險費金額，處四倍罰鍰，並追繳其溢領給付金額；勞工因此所受損失，
 *     並應由投保單位賠償之。（固定 4 倍）
 *
 * - 全民健康保險法§89（pcode L0060001）— 健保低報罰則
 *     投保金額以多報少者，除追繳短繳之保險費外，按其短繳之保險費金額處以
 *     二倍至四倍之罰鍰。（2~4 倍區間）
 *
 * - 刑法§339 II 詐欺得利（pcode C0000001）
 *     以詐術使勞保局／健保署陷於錯誤、少收保費 → 雇主得財產上不法利益。
 *     業務登載不實（§215）為低度行為，被行使不實文書（§216）吸收；與詐欺得利
 *     想像競合（§55），從一重論詐欺得利罪。
 *
 * - 刑法§16
 *     不得因不知法律而免除刑事責任；雇主有據實投保之法定義務，難以「不知道」阻卻故意。
 *
 * - 勞工保險條例§58-1（老年年金第 2 式）
 *     平均月投保薪資 × 保險年資 × 1.55%。低報直接壓低平均月投保薪資。
 *
 * - 就業保險法§16（失業給付）
 *     按離職退保當月起前 6 個月平均月投保薪資 60% 發給，最長 6 個月。
 *
 * @module insurance-compliance
 */

import { getLaborInsuranceBracket, getNhiBracket } from './brackets.js';
import { LABOR_RATES_2026 } from './insurance.js';
import { analyzeWageStructure } from './wage-analysis.js';
import { createTrace, addStep, addLaw, setSummary } from './trace.js';

/** 勞保條例§72 III 固定罰鍰倍數 */
export const LABOR_UNDERREPORT_PENALTY_MULTIPLE = 4;
/** 健保法§89 罰鍰倍數區間 */
export const NHI_UNDERREPORT_PENALTY_MIN_MULTIPLE = 2;
export const NHI_UNDERREPORT_PENALTY_MAX_MULTIPLE = 4;
/** 勞保老年年金第 2 式給付率（勞保條例§58-1） */
export const OLD_AGE_PENSION_ACCRUAL_RATE = 0.0155;
/** 失業給付率（就業保險法§16） */
export const UNEMPLOYMENT_BENEFIT_RATE = 0.6;
/** 失業給付最長月數（就業保險法§16） */
export const UNEMPLOYMENT_BENEFIT_MAX_MONTHS = 6;

/**
 * 把薪資項目陣列換算成「月薪資總額」（投保薪資應申報基準）。
 * 直接重用 analyzeWageStructure：計入工資總額（含爭議暫列）即為應申報基準。
 *
 * @param {Array<{ name: string, amount: number, isRegular?: boolean }>} items
 * @returns {{ wageBasis: number, wageAnalysis: ReturnType<typeof analyzeWageStructure> }}
 */
function deriveWageBasis(items) {
  const wageAnalysis = analyzeWageStructure(items);
  return { wageBasis: wageAnalysis.wageTotal, wageAnalysis };
}

function assertPositiveNumber(label, value) {
  const n = Number(value);
  if (!Number.isFinite(n) || n < 0) {
    throw new Error(`insurance-compliance: ${label} 必須為 ≥ 0 的數值`);
  }
  return n;
}

/**
 * 雇主版：高薪低報合規檢查（風險告誡角度）
 *
 * @param {Object} params
 * @param {Array<{ name: string, amount: number, isRegular?: boolean }>} params.items
 *        實際月薪組成（底薪、技術獎金、輪班補助、膳食費…）
 * @param {number} params.declaredMonthlyInsuranceSalary 雇主目前申報之月投保薪資
 * @param {number} [params.monthsUnderReported=1] 低報已持續月數（用於累計補繳與罰鍰基數）
 * @returns {{
 *   underReported: boolean,
 *   wageBasis: number,
 *   correctLaborBracket: number, declaredLaborBracket: number,
 *   correctNhiBracket: number, declaredNhiBracket: number,
 *   monthlyLaborPremiumGap: number, monthlyNhiPremiumGap: number, monthlyPremiumGap: number,
 *   months: number,
 *   backPremium: { labor: number, nhi: number, total: number },
 *   penalty: { laborMin: number, laborMax: number, nhiMin: number, nhiMax: number, totalMin: number, totalMax: number },
 *   criminalRisk: { crime: string, article: string, note: string } | null,
 *   wageAnalysis: object,
 *   trace: object
 * }}
 */
export function checkUnderReporting({
  items,
  declaredMonthlyInsuranceSalary,
  monthsUnderReported = 1,
}) {
  const declared = assertPositiveNumber('declaredMonthlyInsuranceSalary', declaredMonthlyInsuranceSalary);
  const months = Math.max(1, Math.floor(assertPositiveNumber('monthsUnderReported', monthsUnderReported)));

  const { wageBasis, wageAnalysis } = deriveWageBasis(items);

  const correctLaborBracket = getLaborInsuranceBracket(wageBasis);
  const declaredLaborBracket = getLaborInsuranceBracket(declared);
  const correctNhiBracket = getNhiBracket(wageBasis);
  const declaredNhiBracket = getNhiBracket(declared);

  const laborBracketGap = Math.max(0, correctLaborBracket - declaredLaborBracket);
  const nhiBracketGap = Math.max(0, correctNhiBracket - declaredNhiBracket);

  // 短報之「保險費」差額（全額保費，作為罰鍰基數；勞保含就保 12.5%、健保 5.17%）
  const monthlyLaborPremiumGap = Math.round(laborBracketGap * LABOR_RATES_2026.labor);
  const monthlyNhiPremiumGap = Math.round(nhiBracketGap * LABOR_RATES_2026.nhi);
  const monthlyPremiumGap = monthlyLaborPremiumGap + monthlyNhiPremiumGap;

  const underReported = laborBracketGap > 0 || nhiBracketGap > 0;

  const backLabor = monthlyLaborPremiumGap * months;
  const backNhi = monthlyNhiPremiumGap * months;
  const backPremium = { labor: backLabor, nhi: backNhi, total: backLabor + backNhi };

  // 罰鍰：勞保§72 III 固定 4 倍短報保費；健保§89 為 2~4 倍
  const laborPenalty = backLabor * LABOR_UNDERREPORT_PENALTY_MULTIPLE;
  const nhiPenaltyMin = backNhi * NHI_UNDERREPORT_PENALTY_MIN_MULTIPLE;
  const nhiPenaltyMax = backNhi * NHI_UNDERREPORT_PENALTY_MAX_MULTIPLE;
  const penalty = {
    laborMin: laborPenalty,
    laborMax: laborPenalty,
    nhiMin: nhiPenaltyMin,
    nhiMax: nhiPenaltyMax,
    totalMin: laborPenalty + nhiPenaltyMin,
    totalMax: laborPenalty + nhiPenaltyMax,
  };

  const criminalRisk = underReported
    ? {
        crime: '詐欺得利罪',
        article: '刑法§339 II',
        note:
          '以低報投保薪資使勞保局／健保署少收保費，雇主得財產上不法利益，' +
          '實務上成立詐欺得利罪（業務登載不實§215 被行使不實文書§216 吸收，' +
          '再與§339 II 想像競合從一重論處）。「不知道法律」依刑法§16 不能免責，' +
          '雇主負據實投保之法定義務，難以阻卻故意。',
      }
    : null;

  const trace = createTrace();
  addStep(trace, {
    label: '月薪資總額（投保薪資應申報基準）',
    formula: 'sum(經常性給與)',
    inputs: { wageTotalStrict: wageAnalysis.wageTotalStrict, disputedIncluded: wageBasis - wageAnalysis.wageTotalStrict },
    value: wageBasis,
    note: '依§2 III + 細則§10 判定計入工資之項目；爭議項目（如全勤獎金）暫列入',
  });
  addStep(trace, {
    label: '正確 vs 申報投保級距',
    inputs: {
      correctLaborBracket,
      declaredLaborBracket,
      correctNhiBracket,
      declaredNhiBracket,
    },
    value: laborBracketGap,
    note: underReported ? '申報級距低於應申報級距 → 構成高薪低報' : '申報級距已達應申報級距，無低報',
  });
  if (underReported) {
    addStep(trace, {
      label: '每月短報保費差額',
      formula: '勞保差額×12.5% + 健保差額×5.17%',
      inputs: { laborBracketGap, nhiBracketGap },
      value: monthlyPremiumGap,
    });
    addStep(trace, {
      label: `補繳保費（${months} 個月）`,
      formula: 'monthlyPremiumGap × months',
      inputs: { monthlyPremiumGap, months },
      value: backPremium.total,
    });
    addStep(trace, {
      label: '罰鍰',
      formula: '勞保 4×短報保費 + 健保 (2~4)×短報保費',
      inputs: { backLabor, backNhi },
      value: penalty.totalMin,
      note: `區間 ${penalty.totalMin.toLocaleString()} ~ ${penalty.totalMax.toLocaleString()} 元（健保 2~4 倍裁量）`,
    });
  }

  addLaw(trace, {
    article: '勞工保險條例§14',
    description: '月投保薪資按月薪資總額依分級表申報。',
    url: 'https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=N0050001&flno=14',
  });
  if (underReported) {
    addLaw(trace, {
      article: '勞工保險條例§72 III',
      description: '投保薪資以多報少，按短報保險費處 4 倍罰鍰，並追繳溢領給付、賠償勞工損失。',
      url: 'https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=N0050001&flno=72',
    });
    addLaw(trace, {
      article: '全民健康保險法§89',
      description: '投保金額以多報少，追繳短繳保險費並處 2~4 倍罰鍰。',
      url: 'https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=L0060001&flno=89',
    });
    addLaw(trace, {
      article: '刑法§339 II',
      description: '詐術使保險人少收保費、雇主得不法利益 → 詐欺得利罪。',
      url: 'https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=C0000001&flno=339',
    });
    addLaw(trace, {
      article: '刑法§16',
      description: '不得因不知法律免除刑責（至多減輕）。',
      url: 'https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=C0000001&flno=16',
    });
  }

  setSummary(
    trace,
    underReported
      ? `高薪低報：應申報 ${correctLaborBracket.toLocaleString()}（勞保）/ ${correctNhiBracket.toLocaleString()}（健保），` +
          `每月短報保費 ${monthlyPremiumGap.toLocaleString()} 元；${months} 個月補繳 ${backPremium.total.toLocaleString()} 元，` +
          `罰鍰 ${penalty.totalMin.toLocaleString()}~${penalty.totalMax.toLocaleString()} 元，另有刑法§339 II 詐欺得利風險。`
      : `投保薪資申報無低報（應申報 ${correctLaborBracket.toLocaleString()}，已申報 ${declaredLaborBracket.toLocaleString()}）。`,
  );

  return {
    underReported,
    wageBasis,
    correctLaborBracket,
    declaredLaborBracket,
    correctNhiBracket,
    declaredNhiBracket,
    monthlyLaborPremiumGap,
    monthlyNhiPremiumGap,
    monthlyPremiumGap,
    months,
    backPremium,
    penalty,
    criminalRisk,
    wageAnalysis,
    trace,
  };
}

/**
 * 勞工版：被高薪低報後各項給付縮水估算（自保角度）
 *
 * 老年年金、失業給付皆以「平均月投保薪資」為基數；被低報後基數變小，給付跟著縮水。
 * 本函式輸出「被低報造成的差額」（估算）。
 *
 * @param {Object} params
 * @param {Array<{ name: string, amount: number, isRegular?: boolean }>} params.items 實際月薪組成
 * @param {number} params.declaredMonthlyInsuranceSalary 雇主實際申報之月投保薪資
 * @param {number} [params.yearsOfService=0] 勞保年資（年），用於估老年年金月差額
 * @returns {{
 *   underReported: boolean,
 *   wageBasis: number,
 *   correctLaborBracket: number, declaredLaborBracket: number,
 *   insuredSalaryGap: number,
 *   oldAgePension: { monthlyReductionPerYear: number, estimatedMonthlyReduction: number },
 *   unemployment: { monthlyBenefitGap: number, maxTotalGap: number },
 *   trace: object
 * }}
 */
export function estimateWorkerBenefitImpact({
  items,
  declaredMonthlyInsuranceSalary,
  yearsOfService = 0,
}) {
  const declared = assertPositiveNumber('declaredMonthlyInsuranceSalary', declaredMonthlyInsuranceSalary);
  const years = assertPositiveNumber('yearsOfService', yearsOfService);

  const { wageAnalysis } = deriveWageBasis(items);
  const wageBasis = wageAnalysis.wageTotal;

  const correctLaborBracket = getLaborInsuranceBracket(wageBasis);
  const declaredLaborBracket = getLaborInsuranceBracket(declared);
  const insuredSalaryGap = Math.max(0, correctLaborBracket - declaredLaborBracket);
  const underReported = insuredSalaryGap > 0;

  const monthlyReductionPerYear = Math.round(insuredSalaryGap * OLD_AGE_PENSION_ACCRUAL_RATE);
  const estimatedMonthlyReduction = Math.round(insuredSalaryGap * OLD_AGE_PENSION_ACCRUAL_RATE * years);

  const monthlyBenefitGap = Math.round(insuredSalaryGap * UNEMPLOYMENT_BENEFIT_RATE);
  const maxTotalGap = monthlyBenefitGap * UNEMPLOYMENT_BENEFIT_MAX_MONTHS;

  const trace = createTrace();
  addStep(trace, {
    label: '應投保 vs 實際申報',
    inputs: { wageBasis, correctLaborBracket, declaredLaborBracket },
    value: insuredSalaryGap,
    note: underReported ? '投保薪資被低報，各項給付基數縮水' : '無低報',
  });
  if (underReported) {
    addStep(trace, {
      label: '老年年金月差額（每 1 年年資）',
      formula: 'insuredSalaryGap × 1.55%',
      inputs: { insuredSalaryGap },
      value: monthlyReductionPerYear,
      note: '勞保老年年金第 2 式；乘上實際年資得總月差額',
    });
    addStep(trace, {
      label: `老年年金月差額（${years} 年年資）`,
      formula: 'insuredSalaryGap × 1.55% × 年資',
      inputs: { insuredSalaryGap, years },
      value: estimatedMonthlyReduction,
    });
    addStep(trace, {
      label: '失業給付月差額',
      formula: 'insuredSalaryGap × 60%',
      inputs: { insuredSalaryGap },
      value: monthlyBenefitGap,
      note: `最長 ${UNEMPLOYMENT_BENEFIT_MAX_MONTHS} 個月，合計差額 ${maxTotalGap.toLocaleString()} 元`,
    });
  }
  addLaw(trace, {
    article: '勞工保險條例§58-1',
    description: '老年年金第 2 式＝平均月投保薪資 × 年資 × 1.55%。',
    url: 'https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=N0050001&flno=58-1',
  });
  addLaw(trace, {
    article: '就業保險法§16',
    description: '失業給付＝平均月投保薪資 60%，最長 6 個月。',
    url: 'https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=N0050021&flno=16',
  });
  setSummary(
    trace,
    underReported
      ? `投保薪資被低報 ${insuredSalaryGap.toLocaleString()} 元：老年年金每年年資每月少領約 ${monthlyReductionPerYear.toLocaleString()} 元、` +
          `失業給付每月少領約 ${monthlyBenefitGap.toLocaleString()} 元（最長 6 個月共 ${maxTotalGap.toLocaleString()} 元）。`
      : '投保薪資無低報，給付基數正常。',
  );

  return {
    underReported,
    wageBasis,
    correctLaborBracket,
    declaredLaborBracket,
    insuredSalaryGap,
    oldAgePension: { monthlyReductionPerYear, estimatedMonthlyReduction },
    unemployment: { monthlyBenefitGap, maxTotalGap },
    trace,
  };
}
