/**
 * severance.js — 資遣費與預告期間
 *
 * ## 法源
 * - 勞退條例§12（新制資遣費）
 * - 勞基法§17（舊制資遣費）
 * - 勞基法§16（預告期間）
 */

/**
 * 新制資遣費（勞退條例§12）
 * 每滿1年 = 0.5個月平均薪資，上限6個月
 */
export function calcSeveranceNew(totalMonths, avgWage) {
  if (!Number.isFinite(totalMonths) || totalMonths < 0) throw new TypeError('totalMonths 必須為非負有限數');
  if (!Number.isFinite(avgWage) || avgWage < 0) throw new TypeError('avgWage 必須為非負有限數');
  const raw = totalMonths / 12 * 0.5;
  return Math.min(raw, 6) * avgWage;
}

/**
 * 舊制資遣費（勞基法§17）
 * 每滿1年 = 1個月平均薪資，不足1年按比例，無上限
 */
export function calcSeveranceOld(totalMonths, avgWage) {
  if (!Number.isFinite(totalMonths) || totalMonths < 0) throw new TypeError('totalMonths 必須為非負有限數');
  if (!Number.isFinite(avgWage) || avgWage < 0) throw new TypeError('avgWage 必須為非負有限數');
  const raw = totalMonths / 12;
  return raw * avgWage;
}

/**
 * 預告期間（勞基法§16）— 門檻型，應傳入整數月曆月（calcMonths 之 fullCalendarMonths）。
 * 傳入 serviceYears × 12 之 totalMonths 亦可運作，但邊界日（如滿 3 個月前後）會有 ±3 天偏差。
 * @returns {{ days: number, amount: number, label: string }}
 */
export function calcNotice(calendarMonths, avgWage) {
  if (!Number.isFinite(calendarMonths) || calendarMonths < 0) throw new TypeError('calendarMonths 必須為非負有限數');
  if (!Number.isFinite(avgWage) || avgWage < 0) throw new TypeError('avgWage 必須為非負有限數');
  if (calendarMonths < 3)  return { days: 0,  amount: 0,                 label: '未滿3個月，無需預告' };
  if (calendarMonths < 12) return { days: 10, amount: avgWage / 30 * 10, label: '3個月以上未滿1年：10日' };
  if (calendarMonths < 36) return { days: 20, amount: avgWage / 30 * 20, label: '1年以上未滿3年：20日' };
  return                        { days: 30, amount: avgWage / 30 * 30, label: '3年以上：30日' };
}
