/**
 * schedule-checker.js — HR P0 排班合規檢查器（minimal viable）
 *
 * ## 法源（每條皆已於 https://law.moj.gov.tw 全國法規資料庫驗證原文）
 * - 勞基法§32 II   雇主延長勞工之工作時間連同正常工作時間，一日不得超過十二小時。
 *                  延長之工作時間，一個月不得超過四十六小時（協商上限 54hr 不在 P0 範圍）。
 * - 勞基法§34 II   輪班制勞工更換班次時，至少應有連續十一小時之休息時間。
 *                  （但因工作特性或特殊原因經中央目的事業主管機關商請中央主管機關公告者，
 *                  得變更休息時間不少於連續八小時 — 例外不在 P0 範圍。）
 * - 勞基法§36 I    勞工每七日中應有二日之休息，其中一日為例假，一日為休息日。
 * - 勞基法§38      特別休假：
 *                  - 6 月以上 1 年未滿：3 日
 *                  - 1 年以上 2 年未滿：7 日
 *                  - 2 年以上 3 年未滿：10 日
 *                  - 3 年以上 5 年未滿：每年 14 日
 *                  - 5 年以上 10 年未滿：每年 15 日
 *                  - 10 年以上：每 1 年加 1 日，上限 30 日
 *
 * ## 範圍說明（minimal viable, P0）
 *  - 純函式 checkSchedule(shifts, employee) → Violation[]
 *  - 不依賴 DB、不發 IO；UI 端直接呼叫 client-side
 *  - 只實作 4 條 base rule；§32 採 46hr 預設（協商 54hr 暫不開）
 *  - 規則皆對應 law.moj URL，方便 violation 卡片直連條文出處
 *
 * ## 2026-05-13 manifest 參數化（spec A1 收尾）
 *  - threshold 不再 hardcode；改由 rules/{identity}.js manifest 提供。
 *  - employee.identity 決定查哪一份 manifest（dispatcher: rules/_schema.js）。
 *  - opts.enableSection32Extension（§32 III 54hr toggle）維持原語意。
 *  - 沒給 identity 或 manifest 缺值 → 各自有 hardcoded fallback，與舊行為一致。
 *
 * @module schedule-checker
 */

import { calcMonths } from './dates.js';
import { getAnnualLeaveDays } from './leave.js';
import { getRulesFor } from '../rules/_schema.js';

/**
 * @typedef {Object} ShiftEntry
 * @property {string} employeeId
 * @property {string} date              YYYY-MM-DD（民國/西元皆可被 Date 解析；建議西元）
 * @property {string} startTime         HH:mm（24h）
 * @property {string} endTime           HH:mm（24h）；若跨日由 date+1 推算
 * @property {number} breakMinutes      休息分鐘數（不計入工作時間）
 * @property {'regular'|'overtime'|'restday_work'|'holiday_work'|'leave'} shiftType
 * @property {'annual'|'personal'|'sick'|'official'|undefined} [leaveCategory]
 *           請假分類（shiftType==='leave' 時生效；省略 = 未指定）。
 *           annual=特休（§38）、personal=事假（§43）、sick=普通傷病假（§35）、
 *           official=公假（§44）。R-38 只以 annual 扣特休額度。
 */

/**
 * @typedef {Object} EmployeeMeta
 * @property {string} id
 * @property {'restaurant'|'public_sector'|'enterprise'} identity
 * @property {string} startDate         YYYY-MM-DD（到職日）
 * @property {boolean} isMonthly        月薪制 true / 時薪制 false
 */

/**
 * @typedef {Object} Violation
 * @property {string} ruleId
 * @property {string} statuteRef
 * @property {'violation'|'warning'} severity
 * @property {string} message
 * @property {string[]} affectedDates   YYYY-MM-DD
 * @property {string} lawMojUrl
 */

const LAW_MOJ_BASE =
  'https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=N0030001&flno=';

// ─── manifest helper ────────────────────────────────────────────

/**
 * 從 identity manifest 拉指定 ruleId 的 params。manifest 缺漏 → undefined。
 * @param {ReadonlyArray<any>} manifest
 * @param {string} ruleId
 * @returns {Record<string, any>}
 */
function paramsFor(manifest, ruleId) {
  const rule = manifest.find((r) => r && r.id === ruleId);
  return (rule && rule.params) || {};
}

// ─── 內部工具 ────────────────────────────────────────────────────

/**
 * 將一筆 ShiftEntry 轉換為 { startMs, endMs, durationHours }
 * - endTime ≤ startTime 視為跨日（endDate = date + 1）
 * - 工作時數 = (endMs - startMs)/3600000 - breakMinutes/60
 * @param {ShiftEntry} s
 */
function shiftToInterval(s) {
  const [sh, sm] = s.startTime.split(':').map(Number);
  const [eh, em] = s.endTime.split(':').map(Number);
  const startMs = new Date(`${s.date}T${pad(sh)}:${pad(sm)}:00`).getTime();
  let endMs = new Date(`${s.date}T${pad(eh)}:${pad(em)}:00`).getTime();
  if (endMs <= startMs) endMs += 24 * 3600 * 1000; // 跨日
  const durationHours = (endMs - startMs) / 3600000 - (s.breakMinutes || 0) / 60;
  return { startMs, endMs, durationHours: Math.max(0, durationHours) };
}

function pad(n) {
  return String(n).padStart(2, '0');
}

/**
 * 工作時數中超過 8 小時的部分視為「延長工時（加班）」。
 * shiftType=='overtime' 全部視為加班；其餘類型只計超出 8hr 部分。
 * @param {ShiftEntry} s
 * @param {number} durationHours
 */
function overtimeHours(s, durationHours) {
  if (s.shiftType === 'leave') return 0;
  if (s.shiftType === 'overtime') return durationHours;
  return Math.max(0, durationHours - 8);
}

/**
 * 將同員工 shifts 按日期分組（同一天可能 split shift）
 * @param {ShiftEntry[]} shifts
 */
function groupByDate(shifts) {
  /** @type {Map<string, ShiftEntry[]>} */
  const m = new Map();
  for (const s of shifts) {
    if (!m.has(s.date)) m.set(s.date, []);
    /** @type {ShiftEntry[]} */ (m.get(s.date)).push(s);
  }
  return m;
}

function addDays(dateStr, n) {
  const [y, m, d] = dateStr.split('-').map(Number);
  const date = new Date(Date.UTC(y, m - 1, d));
  date.setUTCDate(date.getUTCDate() + n);
  return date.toISOString().slice(0, 10);
}

// ─── R-32  §32 II 加班時數 ──────────────────────────────────────

/**
 * R-32: 每日加班 ≤ 12hr（一日總工時 ≤ 12hr）；每月加班 ≤ 46hr。
 *
 * 2026-05-13 A3 spec 拍板（boss pivot v2 第 3 拍）：
 *   - 預設 46hr（§32 第 2 項法定）
 *   - opts.enableSection32Extension === true 才放寬到 54hr（§32 第 3 項
 *     工會 / 勞資會議同意條款）。3 個月內合計仍上限 138hr（54×3 - 24）
 *     [本 P0 暫只擋月上限，季上限留 P1]。
 *   - warning 線：開放上限的 80%（46×0.8≈36 / 54×0.8≈43）
 *
 * 2026-05-13 A1 收尾：threshold 改讀 manifest:
 *   - R-32-DAILY.maxDailyHours（fallback 12）
 *   - R-32-MONTHLY.maxMonthlyOvertime / warningLine（fallback 46/36）
 *   - §32 III toggle 仍用 hardcoded 54/43（協商上限是法定，不由 identity 改）
 *
 * @param {ShiftEntry[]} shifts
 * @param {ReadonlyArray<any>} manifest
 * @param {{ enableSection32Extension?: boolean }} [opts]
 * @returns {Violation[]}
 */
function ruleR32(shifts, manifest, opts) {
  const extended = !!(opts && opts.enableSection32Extension);
  const dailyParams = paramsFor(manifest, 'R-32-DAILY');
  const monthlyParams = paramsFor(manifest, 'R-32-MONTHLY');
  const maxDailyHours =
    typeof dailyParams.maxDailyHours === 'number' ? dailyParams.maxDailyHours : 12;
  const baseMonthlyCap =
    typeof monthlyParams.maxMonthlyOvertime === 'number'
      ? monthlyParams.maxMonthlyOvertime
      : 46;
  const baseWarningLine =
    typeof monthlyParams.warningLine === 'number' ? monthlyParams.warningLine : 36;
  // §32 III 協商上限維持法定 54hr（不由 identity manifest 改）
  const monthlyCap = extended ? 54 : baseMonthlyCap;
  const warningLine = extended ? 43 : baseWarningLine;
  /** @type {Violation[]} */
  const out = [];
  const byDate = groupByDate(shifts);

  // 每日 ≤ maxDailyHours（含正常工時）
  /** @type {string[]} */
  const dayHits = [];
  for (const [date, list] of byDate) {
    const total = list.reduce(
      (acc, s) => acc + shiftToInterval(s).durationHours,
      0,
    );
    if (total > maxDailyHours + 1e-9) {
      dayHits.push(`${date}（${total.toFixed(1)}hr）`);
    }
  }
  if (dayHits.length > 0) {
    out.push({
      ruleId: 'R-32-DAILY',
      statuteRef: '勞基法 §32 II',
      severity: 'violation',
      message: `一日工作時間（含延長）超過 ${maxDailyHours} 小時：${dayHits.join('、')}`,
      affectedDates: dayHits.map((s) => s.split('（')[0]),
      lawMojUrl: `${LAW_MOJ_BASE}32`,
    });
  }

  // 每月加班 ≤ monthlyCap
  /** @type {Map<string, number>} */
  const monthly = new Map();
  for (const s of shifts) {
    const month = s.date.slice(0, 7);
    const dur = shiftToInterval(s).durationHours;
    const ot = overtimeHours(s, dur);
    monthly.set(month, (monthly.get(month) || 0) + ot);
  }
  for (const [month, total] of monthly) {
    if (total > monthlyCap + 1e-9) {
      out.push({
        ruleId: 'R-32-MONTHLY',
        statuteRef: extended ? '勞基法 §32 III' : '勞基法 §32 II',
        severity: 'violation',
        message: extended
          ? `${month} 月加班 ${total.toFixed(1)}hr，超過協商上限 ${monthlyCap} 小時（§32 III）`
          : `${month} 月加班 ${total.toFixed(1)}hr，超過法定 ${monthlyCap} 小時上限`,
        affectedDates: shifts
          .filter((s) => s.date.startsWith(month))
          .map((s) => s.date),
        lawMojUrl: `${LAW_MOJ_BASE}32`,
      });
    } else if (total > warningLine + 1e-9) {
      out.push({
        ruleId: 'R-32-WARNING',
        statuteRef: extended ? '勞基法 §32 III' : '勞基法 §32 II',
        severity: 'warning',
        message: `${month} 月加班 ${total.toFixed(1)}hr，已逾 ${warningLine} 小時建議警戒線（距 ${monthlyCap}hr 上限 ${(monthlyCap - total).toFixed(1)}hr）`,
        affectedDates: shifts
          .filter((s) => s.date.startsWith(month))
          .map((s) => s.date),
        lawMojUrl: `${LAW_MOJ_BASE}32`,
      });
    }
  }

  return out;
}

// ─── R-34  §34 II 輪班間隔 ≥ 11hr ───────────────────────────────

/**
 * R-34: 輪班制勞工更換班次間應有連續 11 小時休息。
 *       排序所有 shift 後檢查相鄰兩筆 endMs → 下一筆 startMs 之間隔。
 *
 * 2026-05-13 A1 收尾：threshold 改讀 manifest:
 *   - R-34.minShiftGapHours（fallback 11）
 *   - 餐飲 manifest 雖含 indicatedIndustryGapHours=8（§34 II 後段公告例外），
 *     P0 仍以 minShiftGapHours 為法定下限；指定行業放寬待 HR 主介面接
 *     「公告/勞資會議同意書」狀態後再啟用，避免漏抓。
 *
 * @param {ShiftEntry[]} shifts
 * @param {ReadonlyArray<any>} manifest
 * @returns {Violation[]}
 */
function ruleR34(shifts, manifest) {
  const params = paramsFor(manifest, 'R-34');
  const minGap =
    typeof params.minShiftGapHours === 'number' ? params.minShiftGapHours : 11;
  /** @type {Violation[]} */
  const out = [];
  const intervals = shifts
    .filter((s) => s.shiftType !== 'leave')
    .map((s) => ({ s, ...shiftToInterval(s) }))
    .sort((a, b) => a.startMs - b.startMs);

  for (let i = 1; i < intervals.length; i++) {
    const prev = intervals[i - 1];
    const cur = intervals[i];
    // §34 II 規範「更換班次（跨工作日輪班）」間隔，不含同一工作日的分段班
    // （如餐飲午餐班+晚餐班）；同日多班的合計工時由 R-32 daily 規則涵蓋。
    if (cur.s.date === prev.s.date) continue;
    const gapHours = (cur.startMs - prev.endMs) / 3600000;
    if (gapHours >= 0 && gapHours < minGap - 1e-9) {
      out.push({
        ruleId: 'R-34',
        statuteRef: '勞基法 §34 II',
        severity: 'violation',
        message: `${prev.s.date} 班次結束至 ${cur.s.date} 下一班次開始僅間隔 ${gapHours.toFixed(1)}hr，未達 ${minGap} 小時最低休息`,
        affectedDates: [prev.s.date, cur.s.date],
        lawMojUrl: `${LAW_MOJ_BASE}34`,
      });
    }
  }
  return out;
}

// ─── R-36  §36 I 七休一（例假 vs 休息日分流） ────────────────────

/**
 * R-36: §36 I「勞工每七日中應有二日之休息，其中一日為例假，一日為休息日」。
 *
 * 例假與休息日法律性質不同：
 *   - 例假：原則上不得使勞工出勤（§40 天災事變經主管機關核備例外）。
 *           ⇒ 必須是「完全不排班」之日。
 *   - 休息日：可加班但需依 §24 III 加倍工資。
 *           ⇒ 出勤類型為 restday_work 仍算「該日為休息日」。
 *
 * 分流出兩個子規則：
 *   - R-36-EXAMPLE：每 7 日 ≥ 1 日完全不排班（例假）。
 *   - R-36-REST_DAY：每 7 日「正常工時班」≤ 5 日
 *                   （即至少 2 日不上正常班 = 例假 1 + 休息日 1，
 *                   休息日加班 restday_work 仍計入「2 日休息」）。
 *
 * 分類（依 shiftType）：
 *   - regular / overtime / holiday_work → 正常工時班（normal_work）
 *   - restday_work → 休息日加班（rest_day_work，算「不上正常班」但非例假）
 *   - leave → 請假（保守視為非正常班，但不替代例假）
 *   - 不在 shifts → 完全 off（fully_off，可作例假）
 *
 * 彈性工時例外（§36 IV/V 公告行業）不在 P0 範圍。
 *
 * 2026-05-13 A1 收尾：threshold 改讀 manifest:
 *   - R-36-EXAMPLE.windowDays / requiredFullOffDays
 *   - R-36-REST_DAY.windowDays（maxNormalWorkDays = windowDays - 2 推導）
 *
 * @param {ShiftEntry[]} shifts
 * @param {ReadonlyArray<any>} manifest
 * @returns {Violation[]}
 */
function ruleR36(shifts, manifest) {
  const exampleParams = paramsFor(manifest, 'R-36-EXAMPLE');
  const restDayParams = paramsFor(manifest, 'R-36-REST_DAY');
  const windowDays =
    typeof exampleParams.windowDays === 'number' ? exampleParams.windowDays : 7;
  const requiredFullOff =
    typeof exampleParams.requiredFullOffDays === 'number'
      ? exampleParams.requiredFullOffDays
      : 1;
  // 「正常班 ≤ windowDays - 2」是 §36 「例假 1 + 休息日 1」共 2 日休的固定推論
  const restWindowDays =
    typeof restDayParams.windowDays === 'number' ? restDayParams.windowDays : windowDays;
  const maxNormalWorkDays = restWindowDays - 2;

  /** @type {Violation[]} */
  const out = [];
  if (shifts.length === 0) return out;

  const dates = shifts.map((s) => s.date).sort();
  const start = dates[0];
  const end = dates[dates.length - 1];

  const byDate = groupByDate(shifts);

  /**
   * 七休一分類：
   * - fully_off    無排班（可能是例假/休息日/未排班）
   * - normal_work  正常出勤（含加班、國定日加班）
   * - rest_day_work 休息日加班（休息日仍視為已給休息日 → 不算 normal_work，
   *                 但也不算 fully_off）
   * - leave        請假（事/病/特休/陪產等）— **通說屬出勤義務，不能替代例假**，
   *                故既不算 fully_off 也不算 normal_work；違反 fullyOff < 1 時仍會 trigger。
   *                (2026-05-24 P2-6 doc 釐清)
   * @param {string} date
   * @returns {'fully_off'|'normal_work'|'rest_day_work'|'leave'}
   */
  function classify(date) {
    const list = byDate.get(date) || [];
    if (list.length === 0) return 'fully_off';
    const types = list.map((s) => s.shiftType);
    if (types.some((t) => t === 'regular' || t === 'overtime' || t === 'holiday_work')) {
      return 'normal_work';
    }
    if (types.some((t) => t === 'restday_work')) return 'rest_day_work';
    if (types.every((t) => t === 'leave')) return 'leave';
    return 'normal_work';
  }

  let exampleHit = false;
  let restDayHit = false;
  let cursor = start;

  while (cursor <= end) {
    /** @type {string[]} */
    const windowDaysList = [];
    for (let i = 0; i < windowDays; i++) windowDaysList.push(addDays(cursor, i));
    const tags = windowDaysList.map(classify);
    const fullyOff = tags.filter((t) => t === 'fully_off').length;
    const normalWork = tags.filter((t) => t === 'normal_work').length;

    if (!exampleHit && fullyOff < requiredFullOff) {
      out.push({
        ruleId: 'R-36-EXAMPLE',
        statuteRef: '勞基法 §36 I',
        severity: 'violation',
        message: `${cursor} 起 ${windowDays} 日內無 ${requiredFullOff} 日完全不排班，缺例假（§36 I 例假原則不得出勤，§40 天災事變例外）`,
        affectedDates: windowDaysList.filter((_d, i) => tags[i] !== 'fully_off'),
        lawMojUrl: `${LAW_MOJ_BASE}36`,
      });
      exampleHit = true;
    }
    if (!restDayHit && normalWork > maxNormalWorkDays) {
      out.push({
        ruleId: 'R-36-REST_DAY',
        statuteRef: '勞基法 §36 I',
        severity: 'violation',
        message: `${cursor} 起 ${restWindowDays} 日內安排 ${normalWork} 日正常班，每 ${restWindowDays} 日「例假 1 + 休息日 1」共需 2 日休息（休息日加班 restday_work 仍計入）`,
        affectedDates: windowDaysList.filter((_d, i) => tags[i] === 'normal_work'),
        lawMojUrl: `${LAW_MOJ_BASE}36`,
      });
      restDayHit = true;
    }

    if (exampleHit && restDayHit) break;
    cursor = addDays(cursor, windowDays);
  }
  return out;
}

// ─── R-38  §38 特別休假按年資 ───────────────────────────────────

/**
 * R-38（2026-05-12 升級）：依年資查表計算法定特休 entitled，
 *   並依 leaveCategory 分流：
 *   - leaveCategory === 'annual'（特休）：超過 entitled = **violation**（升級從 warning）
 *     法源：§38 第 1 項 — 雇主給予低於法定下限即違反，不只是警告
 *   - shiftType === 'leave' 但無 leaveCategory（未分類）：發 warning，要求標註類別
 *   - personal / sick / official：不擋（其他條文管轄）
 *
 *   差異：annual leave 超休 = violation（雇主允許超休 = 等同未足額給予的反例不存在，
 *   實務上若 HR 系統記為「特休」但天數超出 entitled，代表年資/帳戶錯誤需立即修正）。
 *
 * 2026-05-13 A1 收尾：年資查表改由 leave.js `getAnnualLeaveDays` 為單一真理（unchanged）。
 *   manifest 上的 thresholds 暫只作 documentation，不另抽（避免兩份真理）。
 *
 * **不支援跨特休週年期**（2026-05-24 P2-3 doc）：
 *   本函式取 shifts 中位日為 referenceDate，將 startDate→referenceDate 算出
 *   單一 fullCalendarMonths 並查 entitled。若 shifts 區間跨越年資週年（例如年資
 *   1.9 → 2.0 年，entitled 中途由 7 升 10），函式只取一個 snapshot，可能略低估或
 *   高估 entitled。P2 接 employee 特休帳戶表後改為帳戶餘額比對；目前 demo / 月度
 *   排班場景影響可忽略。
 *
 * @param {ShiftEntry[]} shifts
 * @param {EmployeeMeta} employee
 * @returns {Violation[]}
 */
function ruleR38(shifts, employee) {
  /** @type {Violation[]} */
  const out = [];
  const dates = shifts.map((s) => s.date).sort();
  const refDate = dates.length > 0 ? dates[Math.floor(dates.length / 2)] : null;
  if (!refDate) return out;

  const monthInfo = calcMonths(employee.startDate, refDate);
  const months = monthInfo && typeof monthInfo === 'object' && 'fullCalendarMonths' in monthInfo
    ? monthInfo.fullCalendarMonths
    : Number(monthInfo) || 0;
  const entitled = getAnnualLeaveDays(months);

  const leaveShifts = shifts.filter((s) => s.shiftType === 'leave');
  const annualLeaveDays = new Set(
    leaveShifts.filter((s) => s.leaveCategory === 'annual').map((s) => s.date),
  ).size;
  const unclassifiedLeave = leaveShifts.filter((s) => !s.leaveCategory);

  // (1) 特休超過法定 → violation
  if (annualLeaveDays > entitled) {
    out.push({
      ruleId: 'R-38',
      statuteRef: '勞基法 §38',
      severity: 'violation',
      message:
        entitled === 0
          ? `員工年資 ${months} 個月未達 6 個月（特休 0 日），不應有特休 ${annualLeaveDays} 日`
          : `特休 ${annualLeaveDays} 日已超出年資 ${months} 個月對應法定特休 ${entitled} 日`,
      affectedDates: leaveShifts
        .filter((s) => s.leaveCategory === 'annual')
        .map((s) => s.date),
      lawMojUrl: `${LAW_MOJ_BASE}38`,
    });
  }

  // (2) 未分類 leave → warning（請 HR 標註類別才能準確計算）
  if (unclassifiedLeave.length > 0) {
    out.push({
      ruleId: 'R-38',
      statuteRef: '勞基法 §38',
      severity: 'warning',
      message: `${unclassifiedLeave.length} 日請假未指定類別（特休 / 事假 / 病假 / 公假），請補標註以正確計入特休額度`,
      affectedDates: unclassifiedLeave.map((s) => s.date),
      lawMojUrl: `${LAW_MOJ_BASE}38`,
    });
  }

  return out;
}

// ─── 對外入口 ────────────────────────────────────────────────────

/**
 * 跑全部 base rule（R-32 / R-34 / R-36 / R-38）並回傳 violations。
 * 純函式：相同 input 一律相同 output；不發 IO、不寫 DB。
 *
 * @param {ShiftEntry[]} shifts        該員工本期所有 shift
 * @param {EmployeeMeta} employee      員工 meta
 * @param {{ enableSection32Extension?: boolean }} [opts]
 *        2026-05-13 spec A3：workspace setting，true = 允許 §32 III 54hr 協商上限
 *        （需有工會 / 勞資會議同意書面紀錄）。預設 false。
 * @returns {Violation[]}
 */
export function checkSchedule(shifts, employee, opts) {
  /** @type {Violation[]} */
  const out = [];
  if (!Array.isArray(shifts) || shifts.length === 0) return out;
  // 只看屬於該員工的 shifts
  const mine = shifts.filter((s) => s.employeeId === employee.id);
  // 依 identity 查 manifest（dispatcher 對未知 identity 已 fallback 到 enterprise）
  const manifest = getRulesFor(employee && employee.identity ? employee.identity : 'enterprise');
  out.push(...ruleR32(mine, manifest, opts));
  out.push(...ruleR34(mine, manifest));
  out.push(...ruleR36(mine, manifest));
  out.push(...ruleR38(mine, employee));
  return out;
}

