/**
 * work-hours-compliance.js — §30 / §32 / §34 / §36 工時合規檢查（traced）
 *
 * 多項勾稽：每週工時、月加班、輪班間隔、例休安排。
 * 抽自 apps/etp/public/hr-tools/work-hours.html 的 runChecks() inline 邏輯。
 *
 * ## 法源（每條已於 https://law.moj.gov.tw 全國法規資料庫驗證）
 *
 * - 勞基法§30 I（每日 / 每週正常工時上限）
 *     勞工正常工作時間，每日不得超過八小時，每週不得超過四十小時。
 *
 * - 勞基法§32 II（延長工時／加班上限）
 *     前項雇主延長勞工之工作時間連同正常工作時間，一日不得超過十二小時；延長之
 *     工作時間，一個月不得超過四十六小時，但雇主經工會同意，如事業單位無工會
 *     者，經勞資會議同意後，得將前項第二款之延長工作時間，一個月不得超過五十
 *     四小時，每三個月不得超過一百三十八小時。
 *
 * - 勞基法§34 II（輪班換班間隔）
 *     依前項更換班次時，至少應有連續十一小時之休息時間。
 *
 * - 勞基法§36 I（七休一 + 休息日）
 *     勞工每七日中應有二日之休息，其中一日為例假，一日為休息日。
 *
 * ## 等級
 *
 * 每項 check 回傳 level：
 *   - 'pass'  完全合規
 *   - 'warn'  落在「有協議擴張」或「缺休息日但有例假」等灰區
 *   - 'fail'  違法
 *   - 'info'  本項不適用（如未輪班時 §34）— 對外不算違規亦不算合規通過
 *
 * @module work-hours-compliance
 */

import { createTrace, addStep, addLaw, setSummary } from './trace.js';

/** 勞基法§30 I 每週正常工時上限 */
export const WEEKLY_HOURS_LIMIT = 40;

/** 勞基法§30 I 每日正常工時上限 */
export const DAILY_HOURS_LIMIT = 8;

/** 勞基法§32 II 每日含加班總工時上限 */
export const DAILY_INCL_OT_LIMIT = 12;

/** 勞基法§32 II 月加班上限（無協議） */
export const MONTHLY_OT_LIMIT_NO_AGREEMENT = 46;

/** 勞基法§32 II 月加班上限（有工會 / 勞資會議協議） */
export const MONTHLY_OT_LIMIT_WITH_AGREEMENT = 54;

/** 勞基法§32 II 每 3 個月加班上限（有協議才適用） */
export const THREE_MONTH_OT_LIMIT = 138;

/** 勞基法§34 II 輪班換班最低間隔（小時） */
export const SHIFT_GAP_MIN_HOURS = 11;

/** 受檢輸入：休息安排型態 */
export const REST_PATTERN_VALUES = Object.freeze({
  FULL: 'full', // 例假 + 休息日 雙具備
  HOLIDAY_ONLY: 'holiday_only', // 只有例假，缺休息日
  NONE: 'none', // 兩者皆無（重大違法）
});

function makeCheck(article, level, status, note) {
  return { article, level, status, note };
}

/**
 * §30 I 週工時檢查
 * @param {number} weeklyHours
 * @returns {{ article: string, level: 'pass'|'fail', status: string, note: string }}
 */
export function checkWeeklyHours(weeklyHours) {
  if (!Number.isFinite(weeklyHours) || weeklyHours < 0) {
    throw new Error('checkWeeklyHours: weeklyHours 必須為 ≥ 0 的數字');
  }
  if (weeklyHours <= WEEKLY_HOURS_LIMIT) {
    return makeCheck(
      '勞基法§30',
      'pass',
      `週工時 ${weeklyHours} 小時 ≤ 40 小時`,
      '§30 I 每週正常工時上限 40 小時，目前合規。延長工時須另循§32。',
    );
  }
  const over = Number((weeklyHours - WEEKLY_HOURS_LIMIT).toFixed(1));
  return makeCheck(
    '勞基法§30',
    'fail',
    `週工時超出 ${over} 小時`,
    '§30 I 規定每週正常工時不得超過 40 小時。延長工時應依§32 II 經工會 / 勞資會議同意並另計加班費。',
  );
}

/**
 * §32 II 月加班檢查
 * @param {number} monthlyOvertimeHours
 * @param {boolean} hasAgreement 是否經工會 / 勞資會議同意
 */
export function checkMonthlyOvertime(monthlyOvertimeHours, hasAgreement = false) {
  if (!Number.isFinite(monthlyOvertimeHours) || monthlyOvertimeHours < 0) {
    throw new Error('checkMonthlyOvertime: monthlyOvertimeHours 必須為 ≥ 0 的數字');
  }
  const ot = monthlyOvertimeHours;
  if (ot <= MONTHLY_OT_LIMIT_NO_AGREEMENT) {
    return makeCheck(
      '勞基法§32',
      'pass',
      `當月加班 ${ot} 小時 ≤ 46 小時`,
      '§32 II 預設月加班上限 46 小時，目前合規。雇主仍應依§24 支付加班費。',
    );
  }
  if (hasAgreement && ot <= MONTHLY_OT_LIMIT_WITH_AGREEMENT) {
    return makeCheck(
      '勞基法§32',
      'warn',
      `加班 ${ot} 小時介於 46–54 小時，需勞資協議擴張`,
      '§32 II 但書經工會 / 勞資會議同意可至 54 小時，且 3 個月合計 ≤ 138 小時。建議定期勾稽 3 個月累計與協議有效性。',
    );
  }
  if (!hasAgreement && ot > MONTHLY_OT_LIMIT_NO_AGREEMENT) {
    return makeCheck(
      '勞基法§32',
      'fail',
      `加班 ${ot} 小時 > 46 小時 但無協議`,
      '§32 II 無協議時月加班不得逾 46 小時。應立即檢討或循工會 / 勞資會議同意程序。',
    );
  }
  // hasAgreement && ot > 54
  return makeCheck(
    '勞基法§32',
    'fail',
    `加班 ${ot} 小時 > 54 小時 縱有協議亦違法`,
    '§32 II 縱有勞資協議，月加班最高 54 小時不得突破；每 3 個月合計上限 138 小時亦同。',
  );
}

/**
 * §34 II 輪班換班間隔檢查
 * shiftGapHours = 換班至下次上班之間隔（小時）。≥ 24 視為非輪班制，標 info。
 */
export function checkShiftGap(shiftGapHours) {
  if (!Number.isFinite(shiftGapHours) || shiftGapHours < 0) {
    throw new Error('checkShiftGap: shiftGapHours 必須為 ≥ 0 的數字');
  }
  if (shiftGapHours >= 24) {
    return makeCheck(
      '勞基法§34',
      'info',
      '非輪班制，§34 不適用',
      '換班間隔 ≥ 24 小時視為無輪班，§34 II 11 小時規定不適用於此情形。',
    );
  }
  if (shiftGapHours >= SHIFT_GAP_MIN_HOURS) {
    return makeCheck(
      '勞基法§34',
      'pass',
      `換班間隔 ${shiftGapHours} 小時 ≥ 11 小時`,
      '§34 II 輪班換班最低間隔 11 小時，目前合規。',
    );
  }
  const diff = Number((SHIFT_GAP_MIN_HOURS - shiftGapHours).toFixed(1));
  return makeCheck(
    '勞基法§34',
    'fail',
    `換班間隔 ${shiftGapHours} 小時，差 ${diff} 小時未達 11`,
    '§34 II 規定輪班制勞工換班至少 11 小時連續休息。建議調整排班補足合法間隔。',
  );
}

/**
 * §36 I 例假 + 休息日檢查
 * @param {'full'|'holiday_only'|'none'} restDayPattern
 */
export function checkRestDays(restDayPattern) {
  if (restDayPattern === REST_PATTERN_VALUES.FULL) {
    return makeCheck(
      '勞基法§36',
      'pass',
      '每 7 日有例假 + 休息日',
      '§36 I 每 7 日應有 1 例假 + 1 休息日，目前完整合規。',
    );
  }
  if (restDayPattern === REST_PATTERN_VALUES.HOLIDAY_ONLY) {
    return makeCheck(
      '勞基法§36',
      'warn',
      '有例假但缺休息日',
      '§36 I 規定每 7 日 1 例假 + 1 休息日；目前缺休息日。例假不違，但休息日缺失仍應補足。',
    );
  }
  if (restDayPattern === REST_PATTERN_VALUES.NONE) {
    return makeCheck(
      '勞基法§36',
      'fail',
      '無例假亦無休息日',
      '§36 I 例假為強制規定，雇主不得剝奪。目前安排違反每 7 日最低休息要求，屬重大違法。',
    );
  }
  throw new Error(
    `checkRestDays: restDayPattern 必須為 'full'|'holiday_only'|'none'，收到 ${restDayPattern}`,
  );
}

/**
 * 整套合規檢查（traced）
 *
 * @param {object} params
 * @param {number} params.weeklyHours 每週工時
 * @param {number} params.monthlyOvertimeHours 當月加班時數
 * @param {boolean} [params.hasOvertimeAgreement=false]
 * @param {number} params.shiftGapHours 輪班換班間隔（無輪班填 24）
 * @param {'full'|'holiday_only'|'none'} params.restDayPattern
 * @returns {{
 *   checks: { weekly, monthlyOT, shiftGap, restDays },
 *   summary: { passCount, warnCount, failCount, infoCount, verdict, level },
 *   trace: object
 * }}
 */
export function checkWorkHoursCompliance({
  weeklyHours,
  monthlyOvertimeHours,
  hasOvertimeAgreement = false,
  shiftGapHours,
  restDayPattern,
}) {
  const weekly = checkWeeklyHours(weeklyHours);
  const monthlyOT = checkMonthlyOvertime(monthlyOvertimeHours, hasOvertimeAgreement);
  const shiftGap = checkShiftGap(shiftGapHours);
  const restDays = checkRestDays(restDayPattern);

  const all = [weekly, monthlyOT, shiftGap, restDays];
  const passCount = all.filter((c) => c.level === 'pass').length;
  const warnCount = all.filter((c) => c.level === 'warn').length;
  const failCount = all.filter((c) => c.level === 'fail').length;
  const infoCount = all.filter((c) => c.level === 'info').length;

  let level;
  let verdict;
  if (failCount > 0) {
    level = 'fail';
    verdict = '有違規風險，建議立即改善';
  } else if (warnCount > 0) {
    level = 'warn';
    verdict = '部分注意事項，建議檢視';
  } else {
    level = 'pass';
    verdict = '整體合規，符合法定規定';
  }

  const trace = createTrace();
  addStep(trace, {
    label: '§30 I 週工時',
    inputs: { weeklyHours, limit: WEEKLY_HOURS_LIMIT },
    value: weeklyHours,
    note: weekly.status,
  });
  addStep(trace, {
    label: '§32 II 月加班',
    inputs: {
      monthlyOvertimeHours,
      hasAgreement: hasOvertimeAgreement,
      noAgreementLimit: MONTHLY_OT_LIMIT_NO_AGREEMENT,
      withAgreementLimit: MONTHLY_OT_LIMIT_WITH_AGREEMENT,
    },
    value: monthlyOvertimeHours,
    note: monthlyOT.status,
  });
  addStep(trace, {
    label: '§34 II 換班間隔',
    inputs: { shiftGapHours, minHours: SHIFT_GAP_MIN_HOURS },
    value: shiftGapHours,
    note: shiftGap.status,
  });
  addStep(trace, {
    label: '§36 I 例休',
    inputs: { restDayPattern },
    value: passCount + warnCount + failCount + infoCount,
    note: restDays.status,
  });
  addLaw(trace, {
    article: '勞基法§30 I',
    description: '每日 ≤ 8 小時、每週 ≤ 40 小時。',
  });
  addLaw(trace, {
    article: '勞基法§32 II',
    description:
      '加班含正常一日 ≤ 12 小時；月 ≤ 46 小時，經工會 / 勞資會議同意可至 54，每 3 個月 ≤ 138。',
  });
  addLaw(trace, {
    article: '勞基法§34 II',
    description: '輪班制換班連續休息至少 11 小時。',
  });
  addLaw(trace, {
    article: '勞基法§36 I',
    description: '每 7 日 1 例假 + 1 休息日。',
  });
  setSummary(
    trace,
    `合規 ${passCount} 項 · 注意 ${warnCount} 項 · 違規 ${failCount} 項${
      infoCount > 0 ? ` · 不適用 ${infoCount} 項` : ''
    } → ${verdict}`,
  );

  return {
    checks: { weekly, monthlyOT, shiftGap, restDays },
    summary: { passCount, warnCount, failCount, infoCount, verdict, level },
    trace,
  };
}
