/**
 * overtime-calculator.js — 加班費試算（細項追溯版）
 *
 * 與舊 src/overtime.js 的差異：
 *  - overtime.js 只回「總金額」（雇主成本估算）；本檔回「細項 + 條號 + 計算式」（爭議追溯／勞工自查）。
 *  - 兩者並存：UI/雇主成本沿用 overtime.js；workspace 爭點/出勤異常用本檔。
 *
 * ## 法源（已於 https://law.moj.gov.tw 全國法規資料庫驗證原文 2026-05-13）
 *
 * 勞基法 §24：
 *   I  雇主延長勞工工作時間者，其延長工作時間之工資，依下列標準加給：
 *       一、延長工作時間在二小時以內者，按平日每小時工資額加給三分之一以上。
 *       二、再延長工作時間在二小時以內者，按平日每小時工資額加給三分之二以上。
 *       三、依第三十二條第四項規定（天災事變突發事件），按平日每小時工資額加倍發給。
 *   II 雇主使勞工於第三十六條所定休息日工作，工作時間在二小時以內者，其工資按平日
 *       每小時工資額另再加給一又三分之一以上；工作二小時後再繼續工作者，按平日每小時
 *       工資額另再加給一又三分之二以上。
 *
 * 勞基法 §32 II：
 *   一日延長工作時間連同正常工作時間不得超過 12 小時。
 *   → 平日加班時數上限 = 12 - 8 = 4 小時（正常工時 8hr 為前提）。
 *   ※ 但「禁止超時」≠「超時不付」；超時部分仍以 §24 I 二款 5/3 倍率計，UI 端應同時警示違規。
 *
 * 勞基法 §36：休息日定義（每七日二日休：一例假、一休息日）。休息日出勤適用 §24 II。
 *   §36 III：休息日工作時數計入 §32 II 月延時 46hr 總額。
 *
 * 勞基法 §37：紀念日、勞動節、其他中央主管機關規定之休假（國定假日）。
 * 勞基法 §39：§37 之休假工資應由雇主照給；經勞工同意於休假日工作者，工資加倍發給。
 *   → 「加倍」通說 = 原本日薪 + 另給一日工資（合計「加給」一倍 = 該日工資總計 2 倍）。
 *
 * 勞基法 §40：因天災事變或突發事件，雇主使勞工於例假工作者，工資應加倍發給，並應給予事後補假休息。
 *   → 例假原則禁止出勤；本檔以 'mandatory_leave'（例假出勤）類型輸出 violation flag 但仍試算加倍工資。
 *
 * ## 倍率釐清（避免「1.34 / 1.67」常見誤稱）
 *  - 條文寫「加給三分之一以上」「加給三分之二以上」「另再加給一又三分之一以上」。
 *  - 通說以 4/3、5/3 為總額乘數（含本薪），即時薪 × 4/3 ≈ 1.3333、× 5/3 ≈ 1.6667。
 *  - 「1.34 / 1.67」為四捨五入俗稱，本檔以分數計算，最後 round 到分（cents）。
 *
 * @module overtime-calculator
 */

const LAW_MOJ = (flno) =>
  `https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=N0030001&flno=${flno}`;

/**
 * 班別類型
 * - weekday        平日加班（§24 I）
 * - restday        休息日出勤（§24 II、§36）
 * - mandatory_leave 例假出勤（§36、§40；原則禁止，僅天災事變例外加倍）
 * - statutory_holiday 國定假日出勤（§37、§39 加倍）
 *
 * @typedef {'weekday'|'restday'|'mandatory_leave'|'statutory_holiday'} ShiftKind
 */

/**
 * @typedef {Object} OvertimeInput
 * @property {ShiftKind} shiftKind         班別
 * @property {number} overtimeHours        加班時數（>0）
 * @property {number} hourlyWage           平日每小時工資額（NTD/hr；月薪制可用 月薪/30/8）
 * @property {boolean} [emergency]         是否為 §32 IV 天災事變突發事件（true → 平日適用加倍）
 */

/**
 * @typedef {Object} OvertimeSegment
 * @property {string} label                "前 2 小時" / "第 3-4 小時" / "8 小時以後" 等
 * @property {number} hours                該段時數
 * @property {string} rateText             "4/3 倍" / "5/3 倍" / "加倍" 等
 * @property {number} multiplier           實際倍率（4/3, 5/3, 2）
 * @property {number} amount               該段加班費（NTD，round 到分）
 * @property {string} statuteRef           "勞基法 §24 I 一款" 等
 * @property {string} lawMojUrl            條文網址
 */

/**
 * @typedef {Object} OvertimeResult
 * @property {ShiftKind} shiftKind
 * @property {number} totalHours
 * @property {number} totalAmount          加班費總額（NTD，round 到分）
 * @property {OvertimeSegment[]} segments  細項
 * @property {string[]} warnings           違規警示（如平日 > 4hr 違 §32 II）
 * @property {string} formula              人類可讀計算式
 */

/** 將 4/3、5/3 等分數轉成 2 位小數 round 後的金額 */
function roundCents(n) {
  return Math.round(n * 100) / 100;
}

function rateLabel(mult) {
  if (mult === 4 / 3) return '4/3 倍（加給 1/3）';
  if (mult === 5 / 3) return '5/3 倍（加給 2/3）';
  if (mult === 2) return '加倍（×2）';
  return `${mult} 倍`;
}

/**
 * 計算加班費（細項追溯版）
 * @param {OvertimeInput} input
 * @returns {OvertimeResult}
 */
export function calcOvertimePay(input) {
  const { shiftKind, overtimeHours, hourlyWage, emergency = false } = input;

  if (!Number.isFinite(overtimeHours) || overtimeHours < 0) {
    throw new Error('overtimeHours must be a non-negative finite number');
  }
  if (!Number.isFinite(hourlyWage) || hourlyWage < 0) {
    throw new Error('hourlyWage must be a non-negative finite number');
  }

  /** @type {OvertimeSegment[]} */
  const segments = [];
  /** @type {string[]} */
  const warnings = [];

  if (overtimeHours === 0) {
    return {
      shiftKind,
      totalHours: 0,
      totalAmount: 0,
      segments: [],
      warnings: [],
      formula: '加班時數為 0，加班費 0 元。',
    };
  }

  if (shiftKind === 'weekday') {
    if (emergency) {
      // §32 IV 天災事變突發事件 → §24 I 三款 加倍
      segments.push({
        label: `平日加班（天災事變）${overtimeHours} 小時`,
        hours: overtimeHours,
        rateText: rateLabel(2),
        multiplier: 2,
        amount: roundCents(overtimeHours * hourlyWage * 2),
        statuteRef: '勞基法 §24 I 三款（§32 IV）',
        lawMojUrl: LAW_MOJ(24),
      });
    } else {
      const h1 = Math.min(overtimeHours, 2);
      const h2 = Math.min(Math.max(overtimeHours - 2, 0), 2);
      const h3 = Math.max(overtimeHours - 4, 0);

      if (h1 > 0) {
        segments.push({
          label: '平日前 2 小時',
          hours: h1,
          rateText: rateLabel(4 / 3),
          multiplier: 4 / 3,
          amount: roundCents(h1 * hourlyWage * (4 / 3)),
          statuteRef: '勞基法 §24 I 一款',
          lawMojUrl: LAW_MOJ(24),
        });
      }
      if (h2 > 0) {
        segments.push({
          label: '平日第 3-4 小時',
          hours: h2,
          rateText: rateLabel(5 / 3),
          multiplier: 5 / 3,
          amount: roundCents(h2 * hourlyWage * (5 / 3)),
          statuteRef: '勞基法 §24 I 二款',
          lawMojUrl: LAW_MOJ(24),
        });
      }
      if (h3 > 0) {
        // §32 II 一日延時上限 4hr；超過仍應給付（實務追償），但屬違規
        segments.push({
          label: `平日第 5 小時起（${roundCents(h3)} 小時）`,
          hours: h3,
          rateText: rateLabel(5 / 3),
          multiplier: 5 / 3,
          amount: roundCents(h3 * hourlyWage * (5 / 3)),
          statuteRef: '勞基法 §24 I 二款（超 §32 II 上限）',
          lawMojUrl: LAW_MOJ(24),
        });
        warnings.push(
          `平日加班 ${overtimeHours} 小時超過 §32 II 一日 4 小時上限 ${roundCents(h3)} 小時，雇主違反工時規定，但超時部分仍應給付加班費（5/3 倍）。`,
        );
      }
    }
  } else if (shiftKind === 'restday') {
    // §24 II + §36
    const r1 = Math.min(overtimeHours, 2);
    const r2 = Math.max(overtimeHours - 2, 0);

    if (r1 > 0) {
      segments.push({
        label: '休息日前 2 小時',
        hours: r1,
        rateText: rateLabel(4 / 3),
        multiplier: 4 / 3,
        amount: roundCents(r1 * hourlyWage * (4 / 3)),
        statuteRef: '勞基法 §24 II 前段',
        lawMojUrl: LAW_MOJ(24),
      });
    }
    if (r2 > 0) {
      segments.push({
        label: `休息日第 3 小時起（${roundCents(r2)} 小時）`,
        hours: r2,
        rateText: rateLabel(5 / 3),
        multiplier: 5 / 3,
        amount: roundCents(r2 * hourlyWage * (5 / 3)),
        statuteRef: '勞基法 §24 II 後段',
        lawMojUrl: LAW_MOJ(24),
      });
    }
    if (overtimeHours > 12) {
      warnings.push(
        `休息日出勤 ${overtimeHours} 小時超過 §32 II 一日 12 小時總工時上限 ${roundCents(overtimeHours - 12)} 小時，違反工時規定（但工資仍應給付）。`,
      );
    }
  } else if (shiftKind === 'statutory_holiday') {
    // §37 + §39 加倍
    segments.push({
      label: `國定假日出勤 ${overtimeHours} 小時`,
      hours: overtimeHours,
      rateText: rateLabel(2),
      multiplier: 2,
      amount: roundCents(overtimeHours * hourlyWage * 2),
      statuteRef: '勞基法 §37、§39（加倍發給）',
      lawMojUrl: LAW_MOJ(39),
    });
  } else if (shiftKind === 'mandatory_leave') {
    // §36 例假 + §40 天災事變例外加倍
    segments.push({
      label: `例假出勤 ${overtimeHours} 小時`,
      hours: overtimeHours,
      rateText: rateLabel(2),
      multiplier: 2,
      amount: roundCents(overtimeHours * hourlyWage * 2),
      statuteRef: '勞基法 §40（例假天災事變例外加倍）',
      lawMojUrl: LAW_MOJ(40),
    });
    warnings.push(
      '例假原則禁止使勞工出勤（§36），僅在天災、事變或突發事件得例外（§40），且事後應補假休息。此筆出勤如非 §40 例外，屬違規。',
    );
  } else {
    throw new Error(`Unknown shiftKind: ${shiftKind}`);
  }

  const totalAmount = roundCents(
    segments.reduce((acc, seg) => acc + seg.amount, 0),
  );

  const formula = segments
    .map(
      (s) =>
        `${s.label}：${roundCents(s.hours)}hr × NTD${hourlyWage} × ${s.rateText} = NTD${s.amount}（${s.statuteRef}）`,
    )
    .join('\n');

  return {
    shiftKind,
    totalHours: overtimeHours,
    totalAmount,
    segments,
    warnings,
    formula,
  };
}

/**
 * 月薪制 → 平日每小時工資額（勞動部解釋慣例：月薪 / 30 / 8）
 * @param {number} monthlySalary
 * @returns {number}
 */
export function monthlyToHourly(monthlySalary) {
  return monthlySalary / 30 / 8;
}

// Re-export 法源網址工具，UI 端可直接 link
export const LAW_MOJ_URL = LAW_MOJ;
