/**
 * Public Sector（公部門）規則包
 *
 * 雙引擎：勞基法 base rule + 公務員服務法 / 公務人員請假規則。
 *
 * 2026-05-13 verify-before-seed 完工：pcode S0020038 = 公務員服務法（27 條），
 * 已用 verify-cspsl-pcode.ts 線上驗過名稱與條文數；§12 §15 原文亦從 law.moj
 * （https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=S0020038）抓回逐字確認後填入。
 *
 * §12 原文摘要（線上 verify 2026-05-13）：
 *   每日辦公 8hr / 每週辦公 40hr / 每週應有 2 日休息日；
 *   延長辦公連同正常每日 ≤ 12hr，每月 ≤ 60hr；
 *   輪班制更換班次至少 11hr 連續休息（特殊勤務情形例外）。
 *
 * §15 原文摘要（線上 verify 2026-05-13）：
 *   除法令規定外不得兼任他項公職、依法令兼職者不得兼薪；
 *   除法令規定外不得兼任領證職業及反覆從事同種類業務（但法定工時以外
 *   從事社會公益性質、非經常持續性工作且未影響本職者不在此限）；
 *   兼任教學/研究/非營利事業職務應經服務機關（構）同意。
 */

import { IDENTITY_RULES as BASE } from './enterprise.js';

const LAW_MOJ_CSPSL =
  'https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=S0020038&flno='; // 公務員服務法

export const IDENTITY_RULES = Object.freeze([
  // ──── §32 月加班上限 override：60hr（公服法 §12）vs 勞基法 46hr ────
  // schedule-checker.js paramsFor() 用 find() 取第一筆，故此 override 必須在 BASE 之前。
  // 不 override 會走 enterprise R-32-MONTHLY 46hr fallback → 對公部門誤報違規。
  Object.freeze({
    id: 'R-32-MONTHLY',
    statuteRef: '公務員服務法 §12 / 勞基法 §32 II',
    lawMojUrl: `${LAW_MOJ_CSPSL}12`,
    severity: 'violation',
    params: Object.freeze({ maxMonthlyOvertime: 60, warningLine: 48 }),
    notes:
      '公部門月延長辦公 ≤ 60hr（公服法 §12）；警戒線 48hr。' +
      '較勞基法 §32 II 46hr 寬鬆。',
  }),
  // Base（公部門編制內勞工仍適用勞基法其他條文）
  ...BASE,
  // 公務員服務法 §12 工作時數（保留 manifest 結構供 UI / 法源連結用）
  Object.freeze({
    id: 'R-CSPSL-§12',
    statuteRef: '公務員服務法 §12',
    lawMojUrl: `${LAW_MOJ_CSPSL}12`,
    severity: 'violation',
    params: Object.freeze({
      // 來源：S0020038 §12（law.moj 2026-05-13 verify）
      dailyOfficeHours: 8,        // 每日辦公時數
      weeklyOfficeHours: 40,      // 每週辦公總時數
      weeklyRestDays: 2,          // 每週應有休息日
      maxDailyTotalHours: 12,     // 延長辦公連同正常每日上限
      maxMonthlyOvertimeHours: 60, // 延長辦公每月上限（注意：較勞基法 §32 II 46hr 寬鬆）
      shiftHandoverMinRestHours: 11, // 輪班制更換班次最低連續休息
    }),
    notes:
      '公務員服務法 §12：8/40 工時、12hr 日上限、60hr 月加班、輪班 11hr 間隔。' +
      '搶救重大災害/緊急突發/重大專案等例外由總統府、國安會及五院分別定之（不在 P0 範圍）。',
  }),
  // 公務員服務法 §15 兼職規範
  Object.freeze({
    id: 'R-CSPSL-§15',
    statuteRef: '公務員服務法 §15',
    lawMojUrl: `${LAW_MOJ_CSPSL}15`,
    severity: 'violation',
    params: Object.freeze({
      // §15 原文：除法令規定外，不得兼任他項公職；依法令兼職者不得兼薪
      allowConcurrentPublicOffice: false,
      paidConcurrentOffice: false, // 法令兼職亦不得兼薪
      // 兼任領證職業 / 反覆從事同種類業務：原則禁止（公益/非經常性例外）
      allowLicensedSideBusiness: false,
      sideBusinessExceptions: Object.freeze([
        'social_welfare_outside_work_hours', // 法定工時以外社會公益性質
        'non_recurring_outside_work_hours',   // 法定工時以外非經常持續性
      ]),
      // 兼任教學/研究/非營利事業職務：應經服務機關同意
      teachingResearchNeedsApproval: true,
      // 機關（構）首長兼職：須上級機關（構）同意
      headOfAgencyEscalatesApproval: true,
    }),
    notes:
      '公務員服務法 §15：兼職原則禁止＋同意制；違反屬倫理 violation。' +
      '本 P0 僅暴露 manifest 結構，實際 violation 偵測待 HR 主介面接「兼職申報」表單後再實作。',
  }),
]);
