/**
 * Rules manifest schema — 2026-05-13 spec A1 拍板
 *
 * 結構模仿 YAML rule pack（boss 選 A：YAML 規則包 + dispatcher）。
 * 暫用 JS module 表達 schema 避開 yaml parser dep；後續若要切真 yaml 只需 swap 來源。
 *
 * 每個 identity (restaurant / public_sector / enterprise) 一檔，export `IDENTITY_RULES`：
 *
 *   /**
 *    * @typedef {Object} RuleConfig
 *    * @property {string} id              R-32-DAILY / R-32-MONTHLY / R-34 / R-36-EXAMPLE / R-36-REST_DAY / R-38
 *    * @property {string} statuteRef      勞基法 §32 II 等
 *    * @property {string} lawMojUrl       law.moj.gov.tw deep link
 *    * @property {'violation'|'warning'|'info'} severity
 *    * @property {Record<string, unknown>} params  rule 參數（threshold 等）
 *    * @property {string=} notes           備註
 *    *|/
 *
 * dispatcher：`getRulesFor(identity: 'restaurant'|'public_sector'|'enterprise')` 回 RuleConfig[]。
 *
 * 注意：本 manifest 目前只「揭露」 rule 結構，schedule-checker.js 的硬編 threshold 暫保留；
 * 下一輪 refactor 把 ruleR32 等改成讀 config.params。
 */

import { IDENTITY_RULES as RESTAURANT_RULES } from './restaurant.js';
import { IDENTITY_RULES as PUBLIC_SECTOR_RULES } from './public-sector.js';
import { IDENTITY_RULES as ENTERPRISE_RULES } from './enterprise.js';

/**
 * @param {'restaurant'|'public_sector'|'enterprise'} identity
 * @returns {ReadonlyArray<unknown>}
 */
export function getRulesFor(identity) {
  switch (identity) {
    case 'restaurant':
      return RESTAURANT_RULES;
    case 'public_sector':
      return PUBLIC_SECTOR_RULES;
    case 'enterprise':
      return ENTERPRISE_RULES;
    default:
      return ENTERPRISE_RULES; // fallback
  }
}

export { RESTAURANT_RULES, PUBLIC_SECTOR_RULES, ENTERPRISE_RULES };
