/**
 * wage-analysis.js — 工資結構分析（§2 III 經常性給與 / 施行細則§10 非經常性）
 *
 * 抽 apps/etp/public/hr-tools/wage-analysis.html 的 ITEMS + analyzeItems +
 * calculateResult 進 core-labor。產出 平均工資 計算所需的「計入工資」總額。
 *
 * ## 法源（每條已於 https://law.moj.gov.tw 全國法規資料庫驗證）
 *
 * - 勞基法§2 III（工資定義）
 *     工資：指勞工因工作而獲得之報酬；包括工資、薪金及按計時、計日、計月、計件
 *     以現金或實物等方式給付之獎金、津貼及其他任何名義之經常性給與均屬之。
 *
 * - 勞基法§2 IV（平均工資定義）
 *     平均工資：謂計算事由發生之當日前六個月內所得工資總額除以該期間之總日數所
 *     得之金額。⋯⋯
 *
 * - 勞動基準法施行細則§10（非經常性給與列舉，第 1 款至第 11 款）
 *     本法第二條第三款所稱之其他任何名義之經常性給與，係指左列各款以外之給與：
 *       一、紅利
 *       二、獎金：指年終獎金、競賽獎金、研究發明獎金、特殊功績獎金、久任獎金、
 *           節約燃料物料獎金及其他非經常性獎金
 *       三、春節、端午節、中秋節給與之節金
 *       四、醫療補助費、勞工及其子女教育補助費
 *       五、勞工直接受自顧客之服務費
 *       六、婚喪喜慶由雇主致送之賀禮、慰問金或奠儀等
 *       七、職業災害補償費
 *       八、勞工保險及雇主以勞工為被保險人加入商業保險支付之保險費
 *       九、差旅費、差旅津貼及交際費
 *       十、工作服、作業用品及其代金
 *       十一、其他經中央主管機關會同中央目的事業主管機關指定者
 *
 * ## 分類 status
 *
 * - 'yes'     計入工資（依§2 III 經常性給與）
 * - 'no'      不計入（細則§10 列舉之非經常性或實支實付）
 * - 'warn'    實務多計入但有爭議（如全勤獎金、按月績效獎金）
 *             → 預設「暫列入」工資總額並標註
 * - 'special' 另計（如加班費依§24 另計，不併入平均工資）
 * - 'depends' 視「經常性」與否；UI 由 isRegular 旗標決定
 *
 * @module wage-analysis
 */

import { createTrace, addStep, addLaw, setSummary } from './trace.js';

/** 標準薪資項目分類字典（與 hr-tools wage-analysis.html ITEMS 對齊） */
export const WAGE_ITEM_CATALOG = Object.freeze([
  Object.freeze({ name: '底薪', isWage: true, note: '勞務對價，屬經常性給與（§2 III）' }),
  Object.freeze({
    name: '全勤獎金',
    isWage: 'warn',
    note: '實務多認屬經常性給與（最高法院判決多數見解），惟仍存爭議；本系統暫列入',
  }),
  Object.freeze({
    name: '伙食津貼',
    isWage: true,
    note: '按月固定發給屬經常性給與；每月 2,400 元以下免納所得稅，但仍計入工資',
  }),
  Object.freeze({
    name: '交通補助',
    isWage: 'depends',
    defaultWage: true,
    note: '按月固定發給 → 計入；實支實報核銷 → 不計入（細則§10 九 差旅）',
  }),
  Object.freeze({ name: '職務加給', isWage: true, note: '因職務固定支領，屬經常性給與' }),
  Object.freeze({
    name: '績效獎金',
    isWage: 'warn',
    note: '按月 / 按季固定發 → 可能屬工資；不定期不定額 → 多被認非經常性',
  }),
  Object.freeze({
    name: '年終獎金',
    isWage: false,
    note: '恩惠性給與，細則§10 二明列非經常性',
  }),
  Object.freeze({
    name: '加班費',
    isWage: 'special',
    note: '依§24 另計，計算平均工資時 不併入（最高法院判決亦同）',
  }),
  Object.freeze({
    name: '差旅費',
    isWage: false,
    note: '實支實付，細則§10 九 明列非經常性',
  }),
  Object.freeze({
    name: '其他',
    isWage: 'depends',
    defaultWage: false,
    note: '依是否「經常性給與」個案判斷；舉證責任在雇主',
  }),
]);

/** 平均工資計算：日薪 = 月工資總額 / 30 */
export const AVG_WAGE_DAY_DIVISOR = 30;
/** 每日 8 小時計薪 */
export const HOURS_PER_DAY = 8;

function lookupDef(name) {
  return WAGE_ITEM_CATALOG.find((i) => i.name === name) ?? null;
}

/**
 * 單項分類：給名稱 + isRegular，回 status + tag + reason
 *
 * @param {{ name: string, isRegular?: boolean }} item
 * @returns {{ status: 'yes'|'no'|'warn'|'special', tag: string, reason: string, def: object | null }}
 */
export function classifyWageItem({ name, isRegular = false }) {
  const def = lookupDef(name);
  if (!def) {
    return {
      status: isRegular ? 'yes' : 'no',
      tag: isRegular ? '薪資' : '非薪資',
      reason: '未列於標準字典，依「經常性」旗標判定',
      def: null,
    };
  }
  switch (def.isWage) {
    case true:
      return { status: 'yes', tag: '薪資', reason: def.note, def };
    case false:
      return { status: 'no', tag: '非薪資', reason: def.note, def };
    case 'warn':
      return { status: 'warn', tag: '爭議', reason: def.note, def };
    case 'special':
      return { status: 'special', tag: '另計', reason: def.note, def };
    case 'depends':
      return {
        status: isRegular ? 'yes' : 'no',
        tag: isRegular ? '薪資' : '非薪資',
        reason: def.note,
        def,
      };
    default:
      return {
        status: isRegular ? 'yes' : 'no',
        tag: isRegular ? '薪資' : '非薪資',
        reason: '未識別 isWage 值，依「經常性」旗標判定',
        def,
      };
  }
}

/**
 * 整套分析：給薪資項目陣列 → 回 計入工資總額 + 日薪 + 時薪 + 爭議列
 *
 * @param {Array<{ name: string, amount: number, isRegular?: boolean }>} items
 * @returns {{
 *   analyzedRows: Array<{ name: string, amount: number, status: string, tag: string, reason: string }>,
 *   wageTotal: number,                       // 計入（含 warn 暫列）
 *   wageTotalStrict: number,                 // 嚴格版（不含 warn）
 *   dailyWage: number, hourlyWage: number,
 *   specialItems: array,                     // 加班費等另計
 *   disputedItems: array,                    // warn
 *   excludedItems: array,                    // no
 *   trace: object
 * }}
 */
export function analyzeWageStructure(items) {
  if (!Array.isArray(items)) {
    throw new Error('analyzeWageStructure: items 必須為陣列');
  }
  const analyzedRows = items.map((item) => {
    const amount = Number(item.amount);
    if (!Number.isFinite(amount) || amount < 0) {
      throw new Error(
        `analyzeWageStructure: ${item.name ?? '<unknown>'} 之 amount 必須為 ≥ 0`,
      );
    }
    const classification = classifyWageItem({
      name: item.name,
      isRegular: item.isRegular ?? false,
    });
    return {
      name: item.name,
      amount,
      status: classification.status,
      tag: classification.tag,
      reason: classification.reason,
    };
  });

  const wageItems = analyzedRows.filter((r) => r.status === 'yes');
  const disputedItems = analyzedRows.filter((r) => r.status === 'warn');
  const specialItems = analyzedRows.filter((r) => r.status === 'special');
  const excludedItems = analyzedRows.filter((r) => r.status === 'no');

  const wageTotalStrict = wageItems.reduce((s, r) => s + r.amount, 0);
  // 暫列入 disputed 進工資總額（hr-tools 預設行為，便於 worker 主張上限）
  const wageTotal =
    wageTotalStrict + disputedItems.reduce((s, r) => s + r.amount, 0);
  const dailyWage = wageTotal / AVG_WAGE_DAY_DIVISOR;
  const hourlyWage = dailyWage / HOURS_PER_DAY;

  const trace = createTrace();
  addStep(trace, {
    label: '經常性給與分類',
    inputs: {
      total: analyzedRows.length,
      yes: wageItems.length,
      warn: disputedItems.length,
      special: specialItems.length,
      no: excludedItems.length,
    },
    value: analyzedRows.length,
    note: '依§2 III + 細則§10 將項目分為 yes / no / warn / special / depends',
  });
  addStep(trace, {
    label: '計入工資總額（嚴格）',
    formula: 'sum(yes)',
    inputs: { count: wageItems.length },
    value: Math.round(wageTotalStrict),
    note: '只計入明確認屬工資之項目',
  });
  if (disputedItems.length > 0) {
    addStep(trace, {
      label: '計入工資總額（含爭議暫列）',
      formula: 'sum(yes) + sum(warn)',
      inputs: {
        strict: Math.round(wageTotalStrict),
        warn: Math.round(wageTotal - wageTotalStrict),
      },
      value: Math.round(wageTotal),
      note: '爭議項目（如全勤獎金）依最高法院多數見解暫列入；建議保留發放紀錄',
    });
  }
  addStep(trace, {
    label: '日薪',
    formula: 'wageTotal / 30',
    inputs: { wageTotal: Math.round(wageTotal), divisor: AVG_WAGE_DAY_DIVISOR },
    value: Math.round(dailyWage),
  });
  addStep(trace, {
    label: '時薪',
    formula: 'dailyWage / 8',
    inputs: { dailyWage: Math.round(dailyWage), hoursPerDay: HOURS_PER_DAY },
    value: Number(hourlyWage.toFixed(2)),
  });
  addLaw(trace, {
    article: '勞基法§2 III',
    description:
      '工資包含經常性給與；獎金 / 津貼 / 其他任何名義之經常性給與均屬工資。',
  });
  addLaw(trace, {
    article: '勞基法§2 IV',
    description: '平均工資 = 計算事由發生前 6 個月工資總額 / 該期間總日數。',
  });
  addLaw(trace, {
    article: '勞動基準法施行細則§10',
    description:
      '列舉 11 款「非經常性給與」：紅利、年終 / 競賽 / 久任獎金、節金、醫療 / 教育補助、服務費、賀禮 / 慰問金、職災補償費、保險費、差旅費 / 津貼、工作服等。',
  });
  if (specialItems.length > 0) {
    addLaw(trace, {
      article: '勞基法§24',
      description: '加班費另計；計算平均工資時不併入。',
    });
  }
  setSummary(
    trace,
    `工資總額 ${Math.round(wageTotal).toLocaleString()} 元（嚴格 ${Math.round(wageTotalStrict).toLocaleString()} + 爭議暫列 ${Math.round(wageTotal - wageTotalStrict).toLocaleString()}）；日薪 ${Math.round(dailyWage).toLocaleString()} 元 / 時薪 ${hourlyWage.toFixed(2)} 元。`,
  );

  return {
    analyzedRows,
    wageTotal: Math.round(wageTotal),
    wageTotalStrict: Math.round(wageTotalStrict),
    dailyWage: Math.round(dailyWage),
    hourlyWage: Number(hourlyWage.toFixed(2)),
    specialItems,
    disputedItems,
    excludedItems,
    trace,
  };
}
